	Tree               string `json:"tree,omitempty"`
	Profile            string `json:"profile"`
	Query              string `json:"query"`
	File               string `json:"file,omitempty"`
	Line               int    `json:"line,omitempty"`
	Depth              int    `json:"depth"`
