func recordsByRelationSupport(recordsByFile map[string][]SymbolRecord, relationType string) map[string][]SymbolRecord {
	filtered := map[string][]SymbolRecord{}
	for path, records := range recordsByFile {
		var kept []SymbolRecord
		for _, record := range records {
			if languageSupportsRelation(record.Language, relationType) {
				kept = append(kept, record)
			}
		}
		if len(kept) > 0 {
			filtered[path] = kept
		}
	}
	return filtered
}

func languageSupportsRelation(language, relationType string) bool {
	for _, supported := range ooRelationSupport[language] {
		if supported == relationType {
			return true
		}
	}
	return false
}

func useFastCFamilyParser(spec profileSpec, langSpec languageSpec) bool {
	if spec.name == ProfileFull {
		return false
	}
	return langSpec.language == "C" || langSpec.language == "C++"
}

// evidenceDigest fingerprints an evidence array so two records for one edge can
// be compared without keeping either. Order matters: the array is canonically
// ordered, so a reordering is a real difference.
func evidenceDigest(evidence []Evidence) uint64 {
	h := fnv.New64a()
	for _, e := range evidence {
		_, _ = h.Write([]byte(e.Kind))
		_, _ = h.Write([]byte{0})
		_, _ = h.Write([]byte(e.Detail))
		_, _ = h.Write([]byte{0})
	}
	return h.Sum64()
}

// unmergedDataFlowEvidenceWarning reports DATA_FLOWS edges that more than one
// symbol justified. Evidence is grouped where flows are emitted, which sees one
// `from` symbol at a time, so an edge produced from two symbols keeps the first
// producer's flows. Merging them needs a boundary that sees every producer,
// which on a write-through stream means buffering every DATA_FLOWS record to the
// end of the pass and emitting them out of canonical order. The count is
// disclosed instead, so a consumer can tell a thin evidence array from a
// complete one.
func unmergedDataFlowEvidenceWarning(edges int) ProviderWarning {
	return ProviderWarning{
		Code:                 "W_DATA_FLOW_EVIDENCE_UNMERGED",
		Severity:             "info",
		EffectOnCompleteness: "each DATA_FLOWS relation carries every flow found by the symbol that produced it; on these 
edges a second symbol justified the same edge and its flows were dropped, so the evidence array explains the edge from 
one side only. The affected edges are counted, not identified: each record had already been written when its second 
producer appeared, so none of them can be marked individually and a consumer cannot tell from a relation alone whether 
it is one of them",
		Detail: fmt.Sprintf(
			"%d DATA_FLOWS edge(s) were justified by more than one symbol, typically mutual recursion where one side forwards a 
parameter and the other returns a call; the relation, its confidence and its reason are unaffected. Independent of 
EVIDENCE_TRUNCATED: one edge can be both, neither supersedes the other, and this count includes edges that were also 
truncated",
			edges,
		),
	}
}

// relationDedupKey hashes a relation's identity (from, to, type) to a compact
// 64-bit key for the streaming dedup set, keeping that set's memory small on
// large repositories.
func relationDedupKey(r RelationRecord) uint64 {
	h := fnv.New64a()
	_, _ = h.Write([]byte(r.FromID))
	_, _ = h.Write([]byte{0})
	_, _ = h.Write([]byte(r.ToID))
	_, _ = h.Write([]byte{0})
	_, _ = h.Write([]byte(r.Type))
	return h.Sum64()
}

// SnapshotSummary is the trailing record of a streamed snapshot. It carries the
// totals known only after the whole repository is processed; a streaming
// consumer reads it for languages, warnings, partial failures, stats, and the
// completeness breakdown (the leading header leaves these empty).
type SnapshotSummary struct {
	RecordType      string             `json:"record_type"`
	Languages       []string           `json:"languages"`
	LanguageTiers   map[string]string  `json:"language_tiers,omitempty"`
	Warnings        []ProviderWarning  `json:"warnings"`
	PartialFailures []PartialFailure   `json:"partial_failures"`
	Stats           ProviderStats      `json:"stats"`
	Completeness    CompletenessReport `json:"completeness"`
}

// prepareSource resolves repository identity, lists the source files, and
// builds a per-file content reader without loading any content.
func prepareSource(ctx context.Context, repo string, options ProviderSnapshotOptions) (sourceContext, error) {
	absRepo, err := filepath.Abs(repo)
	if err != nil {
		return sourceContext{}, err
	}
	key := "local/" + filepath.Base(absRepo)
	commit := ""
	tree := ""
	var headErr error
	ctx, metadataSafe := newGitMetadataValidation(ctx, absRepo)
	if metadataSafe {
		key = repoKey(ctx, absRepo)
		commit, tree, headErr = resolveCommittedHEAD(ctx, absRepo)
	} else {
		headErr = fmt.Errorf("refuse Git subprocesses for unsafe or unreadable repository metadata under %q", absRepo)
	}

	// The provider is local-only. NoNetwork is accepted to make that contract
	// explicit for callers that enforce no-egress provider execution.
	_ = options.NoNetwork
	committedRevision := ""
	if !options.Worktree && headErr == nil {
		committedRevision = commit
	}
	opened, err := openSource(ctx, absRepo, committedRevision, sourceOptions{
		ignoreFiles:  options.IgnoreFiles,
		includeFiles: options.IncludeFiles,
		cachePolicy:  options.cachePolicy,
		maxReadBytes: resolveMaxParseBytes(options.MaxParseBytes),
		maxFiles:     options.MaxFiles,
	})
	if err != nil {
		return sourceContext{}, err
	}
	paths := opened.paths
	if len(options.OnlyFiles) > 0 {
		allowed := make(map[string]bool, len(options.OnlyFiles))
		for _, filePath := range options.OnlyFiles {
			allowed[filepath.ToSlash(filepath.Clean(filePath))] = true
		}
		filtered := paths[:0]
		for _, filePath := range paths {
			if allowed[filepath.ToSlash(filePath)] {
				filtered = append(filtered, filePath)
			}
		}
		paths = filtered
	}
	if opened.prime != nil {
		if err := opened.prime(paths); err != nil {
			if opened.close != nil {
				err = errors.Join(err, opened.close())
			}
			return sourceContext{}, err
		}
	}

	warnings := append([]ProviderWarning(nil), opened.warnings...)
	if options.Worktree {
		warnings = append(warnings, ProviderWarning{
			Code:                 "W_WORKTREE_SNAPSHOT",
			Severity:             "warning",
			EffectOnCompleteness: "snapshot records are read from the working tree because --worktree was requested",
		})
	} else if headErr != nil {
		warnings = append(warnings, ProviderWarning{
			Code:                 "E_NO_GIT_HEAD",
			Severity:             "warning",
			EffectOnCompleteness: "snapshot records are read from the working tree because no HEAD tree is available",
			Detail:               headErr.Error(),
		})
	}
	return sourceContext{
		absRepo:    absRepo,
		key:        key,
		commit:     commit,
		tree:       tree,
		paths:      paths,
		read:       opened.read,
		readPrefix: opened.readPrefix,
		oversize:   opened.oversize,
		ignores:    opened.ignores,
		close:      opened.close,
		warnings:   warnings,
	}, nil
}

// resolveMaxParseBytes resolves the per-file byte cap shared by the content
// reader and the parser: the caller's value, else the provider default. A
// negative value removes the cap, which is the documented escape hatch for a
// caller that really wants a whole file of any size in memory.
func resolveMaxParseBytes(requested int) int {
	if requested != 0 {
		return requested
	}
	return defaultMaxParseBytes
}

// resolveCommittedHEAD binds a repository view to one immutable commit. The
// tree is resolved from that exact object rather than from a second moving
// HEAD expression, preventing mixed commit/tree provenance if HEAD advances
// between subprocesses.
func resolveCommittedHEAD(ctx context.Context, repo string) (string, string, error) {
	if !gitMetadataSafeForSubprocessContext(ctx, repo) {
		err := fmt.Errorf("refuse Git subprocesses for unsafe or unreadable repository metadata under %q", repo)
		return "", "", err
	}
	commit, tree, err := gitutil.HeadCommitAndTree(ctx, repo)
	if err != nil || commit == "" {
		if err == nil {
			err = errors.New("HEAD resolved to an empty commit")
		}
		return "", "", err
	}
	return commit, tree, nil
}

func WriteSnapshotNDJSON(out io.Writer, snapshot ProviderSnapshot) error {
	if err := writeJSONLine(out, snapshot.Header); err != nil {
		return err
	}
	for _, record := range snapshot.Files {
		if err := writeJSONLine(out, record); err != nil {
			return err
		}
	}
	for _, record := range snapshot.Externals {
		if err := writeJSONLine(out, record); err != nil {
			return err
		}
	}
	for _, record := range snapshot.Symbols {
		if err := writeJSONLine(out, record); err != nil {
			return err
		}
	}
	for _, record := range snapshot.Relations {
		if err := writeJSONLine(out, record); err != nil {
			return err
		}
	}
	return nil
}

func WriteSymbolsNDJSON(out io.Writer, snapshot ProviderSnapshot) error {
	if err := writeJSONLine(out, snapshot.Header); err != nil {
		return err
	}
	for _, record := range snapshot.Symbols {
		if err := writeJSONLine(out, record); err != nil {
			return err
		}
	}
	return nil
}

func WriteRelationsNDJSON(out io.Writer, snapshot ProviderSnapshot) error {
	if err := writeJSONLine(out, snapshot.Header); err != nil {
		return err
	}
	for _, record := range snapshot.Relations {
		if err := writeJSONLine(out, record); err != nil {
			return err
		}
	}
	return nil
}

func entitySymbols(repoKey, path, language string, entities []Entity) []SymbolRecord {
	byName := map[string]string{}
	// definitionCounts counts only entities that DEFINE the name; declarationCounts
	// counts the bodyless declarations of it (TypeScript overload signatures,
	// ambient `declare function`). They are kept apart so that adding a signature
	// above an implementation never renames the implementation: a bodyless
	// declaration is not a second definition, and compound-v1 IDs must survive
	// ordinary edits (the same reason Swift extensions are not emitted as classes —
	// see parser.go's swiftExtensionDeclaration note).
	definitionCounts := map[string]int{}
	declarationCounts := map[string]int{}
	sigOrdinals := map[string]int{}
	for _, entity := range entities {
		id := symbolID(repoKey, language, path, entity.Kind, entity.Name)
		if entity.bodyless {
			declarationCounts[id]++
			continue
		}
		definitionCounts[id]++
	}
	// One symbol is emitted per entity, in order, so an entity's index is also its symbol's
	// index — which is what lets a lexical parent be looked up as symbols[parents[index]].
	lexicalParents := lexicalEntityParents(entities)
	symbols := make([]SymbolRecord, 0, len(entities))
	for index, entity := range entities {
		qualified := entity.Name
		id := symbolID(repoKey, language, path, entity.Kind, qualified)
		// A definition collides only with other definitions: overload signatures
		// above it must not push it onto a suffixed ID. A bodyless declaration
		// yields the bare ID to the definition whenever anything else shares the
		// name, and keeps it when it is the only declaration of that name (a lone
		// ambient `declare function`, an abstract member), so no ID that existed
		// before overload signatures were emitted changes.
		colliding := definitionCounts[id] > 1
		if entity.bodyless {
			colliding = definitionCounts[id]+declarationCounts[id] > 1
		}
		if colliding {
			// Disambiguate same-name symbols by signature hash plus an ordinal
			// within the matching-signature group. This is stable across edits
			// that shift line numbers, unlike the previous line-range scheme;
			// overloads with distinct signatures get distinct, stable IDs, and
			// genuine duplicates fall back to a stable definition ordinal.
			signatureHash := hash(entity.Signature)
			ordinalKey := id + "\x00" + signatureHash
			sigOrdinals[ordinalKey]++
			id = fmt.Sprintf("%s#sig:%s", id, signatureHash)
			if ordinal := sigOrdinals[ordinalKey]; ordinal > 1 {
				id = fmt.Sprintf("%s#%d", id, ordinal)
			}
		}
		containerID := ""
		if containerName := containerName(qualified); containerName != "" {
			if parentID, ok := byName[containerName]; ok {
				containerID = parentID
			}
		} else if parent := lexicalParents[index]; parent >= 0 && parent < len(symbols) {
			// The parser gave this declaration no owner at all, so fall back to the declaration
			// that lexically encloses it — see nested_containers.go for why that is the only way
			// a nested type becomes a member of the type it sits in.
			containerID = symbols[parent].ID
		}
		symbol := SymbolRecord{
			RecordType:      "symbol",
			ID:              id,
			StableIDVersion: StableSymbolIDVersion,
			Kind:            entity.Kind,
			Name:            shortEntityName(entity.Name),
			QualifiedName:   qualified,
			FilePath:        path,
			StartLine:       entity.StartLine,
			EndLine:         entity.EndLine,
			Signature:       entity.Signature,
			BodyHash:        entity.BodyHash,
			Language:        language,
			ContainerID:     containerID,
			Local:           entity.Local,
			sourceStartByte: entity.sourceStartByte,
			sourceEndByte:   entity.sourceEndByte,
			bodyless:        entity.bodyless,
			cLinkage:        entity.cLinkage,
		}
		// Carried for every language: the parser marks parameterNamesKnown only
		// when it actually read the names off the parse tree, so a grammar with
		// no recognizable parameter list still falls back to the signature regex
		// downstream rather than reporting an empty list as authoritative.
		symbol.parameterNames = append([]string(nil), entity.parameterNames...)
		symbol.parameterNamesKnown = entity.parameterNamesKnown
		symbol.paramTypeText = entity.paramTypeText
		symbol.returnTypeText = entity.returnTypeText
		symbol.signatureTypesKnown = entity.signatureTypesKnown
		symbols = append(symbols, symbol)
		byName[qualified] = id
	}
	return symbols
}

func syntheticBoundarySymbols(repoKey, path, language, content string, fileSymbols []SymbolRecord) []SymbolRecord {
	var symbols []SymbolRecord
	lines := strings.Split(content, "
")
	if route := webRouteBoundary(path); route != "" {
		source := routeBoundarySource(path, language, fileSymbols)
		symbols = append(symbols, SymbolRecord{
			RecordType:      "symbol",
			ID:              symbolID(repoKey, language, path, "route", route),
			StableIDVersion: StableSymbolIDVersion,
			Kind:            "route",
			Name:            route,
			QualifiedName:   route,
			FilePath:        path,
			StartLine:       source.StartLine,
			EndLine:         source.EndLine,
			Signature:       "route " + route,
			BodyHash:        hash(normalize(content)),
			Language:        language,
			ContainerID:     source.ContainerID,
			sourceStartByte: source.sourceStartByte,
			sourceEndByte:   source.sourceEndByte,
		})
	}
	for _, source := range fileSymbols {
		block := symbolBlockFromLines(lines, source)
		if exact, ok := exactSymbolSource(content, source); ok {
			block = exact
		}
		if !looksLikeToolHandler(source, block) {
			continue
		}
		symbols = append(symbols, SymbolRecord{
			RecordType:      "symbol",
			ID:              symbolID(repoKey, language, path, "tool", source.QualifiedName),
			StableIDVersion: StableSymbolIDVersion,
			Kind:            "tool",
			Name:            source.Name,
			QualifiedName:   source.QualifiedName,
			FilePath:        path,
			StartLine:       source.StartLine,
			EndLine:         source.EndLine,
			Signature:       "tool " + source.QualifiedName,
			BodyHash:        source.BodyHash,
			Language:        language,
			ContainerID:     source.ID,
			sourceStartByte: source.sourceStartByte,
			sourceEndByte:   source.sourceEndByte,
		})
	}
	if workflow := applicationWorkflowBoundary(path); workflow != "" {
		source := routeBoundarySource(path, language, fileSymbols)
		symbols = append(symbols, SymbolRecord{
			RecordType:      "symbol",
			ID:              symbolID(repoKey, language, path, "workflow", workflow),
			StableIDVersion: StableSymbolIDVersion,
			Kind:            "workflow",
			Name:            workflow,
			QualifiedName:   workflow,
			FilePath:        path,
			StartLine:       source.StartLine,
			EndLine:         source.EndLine,
			Signature:       "workflow " + workflow,
			BodyHash:        hash(normalize(content)),
			Language:        language,
			ContainerID:     source.ContainerID,
			sourceStartByte: source.sourceStartByte,
			sourceEndByte:   source.sourceEndByte,
		})
	}
	return symbols
}

type routeSource struct {
	StartLine       int
	EndLine         int
	ContainerID     string
	sourceStartByte int
	sourceEndByte   int
}

type resolvedCallTarget struct {
	SymbolRecord
	Confidence float64
	Reason     string
	Resolution string
	Scope      string
}

func callableTargetKind(kind string) bool {
	return kind == "function" || kind == "method" || typeLikeKind(kind)
}

func routeBoundarySource(path, language string, fileSymbols []SymbolRecord) routeSource {
	file := FileRecord{Path: path, Language: language}
	sourceID := routeBoundarySourceID("", file, fileSymbols)
	for _, symbol := range fileSymbols {
		if symbol.ID == sourceID {
			return routeSource{StartLine: symbol.StartLine, EndLine: symbol.EndLine, ContainerID: symbol.ID, sourceStartByte: 
symbol.sourceStartByte, sourceEndByte: symbol.sourceEndByte}
		}
	}
	return routeSource{StartLine: 1, EndLine: 1}
}

// localReachable enforces lexical nesting in name-match call resolution: a
// function-local (nested/closure) callable is only reachable from within its
// enclosing function — i.e. when `from` lexically contains it in the same file.
// Non-local callables are always reachable. This kills the dominant cross-scope
// false edges (e.g. every decorator factory's nested `decorator`/`new_func`
// name-matching each other) without a full scope resolver.
func localReachable(from, to SymbolRecord) bool {
	if !to.Local {
		return true
	}
	return to.FilePath == from.FilePath && from.StartLine <= to.StartLine && to.StartLine <= from.EndLine
}

// implicitReceiverLanguage reports whether a bare `name()` call can mean
// `this.name()` (an implicit-receiver method call). In such languages a bare
// call legitimately targets a method, so it must not be excluded from name-match
// resolution; in Go/Python/JS/TS a method call always carries an explicit
// receiver and is handled by receiverCallRelations instead.
func implicitReceiverLanguage(lang string) bool {
	switch lang {
	case "Java", "C#", "C++", "Dart", "Elixir", "Groovy", "Kotlin", "Scala", "Ruby", "Swift":
		return true
	}
	return false
}

// allowMethodTargets relaxes the "a bare name() never resolves to a method"
// rule. It must stay false for CALLS resolution (a receiver-less call is a
// function, not a class method), but the DATA_FLOWS argument-forward path
// resolves the *called* symbol of `obj.method(arg)` — which legitimately is a
// method — so it passes true. Folding that distinction into one resolver kept
// the data-flow path from silently dropping the `arg -> method` flow.
// nameCallMayTargetMethod reports whether a name-resolved call (a bare `name()`
// or a path-qualified `Type::name()`) can legitimately bind to a *method*, so
// methods must NOT be excluded from name-match resolution for that language:
//   - implicit-receiver languages: bare `name()` means `this.name()`;
//   - Rust: `Type::name()` / `Trait::name()` path calls and associated
//     functions are written explicitly and resolve to the method by name.
//
// In Go/Python/JS/TS a method call always carries an explicit `.`-receiver and
// is handled by receiverCallRelations instead, so methods stay excluded there.
// (Ported from fix/rust-call-resolution ad6ca4d onto the current gate shape.)
func nameCallMayTargetMethod(lang string) bool {
	return implicitReceiverLanguage(lang) || lang == "Rust"
}

// fsharpNamespaceScope is one `namespace X` declaration: the line it opens on
// and the dotted path it nests everything below it under.
type fsharpNamespaceScope struct {
	line   int
	prefix string
}

// A namespace declaration is a top-level form, so it starts at column 0. `rec`
// is allowed between the keyword and the path (`namespace rec X.Y`).
var fsharpNamespaceDeclPattern = regexp.MustCompile(`(?m)^namespace[ 	]+(?:rec[ 	]+)?([A-Za-z_][A-Za-z0-9_'.]*)[ 
	]*?$`)

// fsharpNamespaceScopes lists the namespaces an F# file opens, in source order.
//
// F# writes `namespace X` when a file's contents nest under a path without
// introducing a module of that name, and the parser emits NO symbol for it --
// a namespace holds no bindings of its own, so there is nothing to emit. The
// container chain a module path is built from therefore starts at the module,
// and `namespace X` + `module A` recorded its members under `A`. The call that
// names them, `X.A.f`, then matched no declared module at all: it was not
// recognised as a module qualifier, recorded bare, resolved unrestricted, and
// bound to whichever same-named definition sat nearest -- or, once a second
// module declared that name too, emitted no edge whatsoever despite naming its
// target in full.
//
// Literals and comments are masked first, so a `namespace` line inside a
// triple-quoted string or a `(* ... *)` block cannot open a scope. `namespace
// global` is the root namespace and adds no prefix.
func fsharpNamespaceScopes(content string) []fsharpNamespaceScope {
	if !strings.Contains(content, "namespace") {
		return nil
	}
	masked := maskFSharpLiteralsAndLineComments(maskFSharpBlockComments(content))
	matches := fsharpNamespaceDeclPattern.FindAllStringSubmatchIndex(masked, -1)
	scopes := make([]fsharpNamespaceScope, 0, len(matches))
	for _, match := range matches {
		prefix := masked[match[2]:match[3]]
		if prefix == "global" {
			prefix = ""
		}
		scopes = append(scopes, fsharpNamespaceScope{line: 1 + strings.Count(masked[:match[0]], "
"), prefix: prefix})
	}
	return scopes
}

// fsharpNamespaceAt returns the namespace a line sits in -- the last one
// declared at or above it. A file may open several in sequence, and anything
// above the first declaration is in none.
func fsharpNamespaceAt(scopes []fsharpNamespaceScope, line int) string {
	prefix := ""
	for _, scope := range scopes {
		if scope.line > line {
			break
		}
		prefix = scope.prefix
	}
	return prefix
}

// fsharpModulePaths maps each symbol in an F# file to the dotted path of the
// modules it is declared in ("A", "LoadingScripts.ScriptGeneration"), and
// returns the set of paths the file declares. F# files routinely hold several
// modules, so a call written `A.convert` must be held to module A's members
// instead of binding to whichever same-named definition sits nearest.
//
// The file's namespace declarations are part of that path even though no
// symbol carries them (see fsharpNamespaceScopes): a file-heading `module
// A.B.C` already spells its whole path in the symbol's name, and `namespace X`
// + `module A` must record the same `X.A` rather than a bare `A`.
func fsharpModulePaths(fileSymbols []SymbolRecord, namespaces []fsharpNamespaceScope) (map[string]string, 
map[string]bool) {
	byID := make(map[string]SymbolRecord, len(fileSymbols))
	for _, symbol := range fileSymbols {
		byID[symbol.ID] = symbol
	}
	pathBySymbolID := make(map[string]string, len(fileSymbols))
	declared := map[string]bool{}
	for _, symbol := range fileSymbols {
		var segments []string
		// Bound by the file's symbol count: a container chain cannot revisit a
		// symbol, and a malformed one stops at the first unknown container.
		for container, hops := symbol.ContainerID, 0; container != "" && hops <= len(fileSymbols); hops++ {
			parent, ok := byID[container]
			if !ok {
				break
			}
			if parent.Kind == "module" {
				segments = append([]string{parent.Name}, segments...)
			}
			container = parent.ContainerID
		}
		path := strings.Join(segments, ".")
		// The namespace the declaration sits in prefixes the whole chain: it is
		// a container the symbol set does not model, not one the walk above
		// missed.
		if prefix := fsharpNamespaceAt(namespaces, symbol.StartLine); prefix != "" {
			if path == "" {
				path = prefix
			} else {
				path = prefix + "." + path
			}
		}
		pathBySymbolID[symbol.ID] = path
		if symbol.Kind == "module" {
			own := symbol.Name
			if path != "" {
				own = path + "." + symbol.Name
			}
			declared[own] = true
		}
	}
	return pathBySymbolID, declared
}

// fsharpProjectModulePaths is fsharpModulePaths over every F# file at once.
//
// F# modules are PROJECT-scoped, not file-scoped, and the usual layout is one
// module per file, so `A.convert` written anywhere in the project names module
// A wherever A is declared. Deciding what a qualifier may name from the caller
// FILE's declarations alone therefore threw the restriction away on exactly the
// calls that most need it: a cross-file `A.convert` was recorded as bare
// `convert`, and once a second module declared a `convert` too, the
// globally-unique fallback emitted NO edge at all despite the explicit
// qualifier. The path map has to widen with it, because the scope a cross-file
// qualifier names lives in another file and a map keyed on this file's symbols
// cannot filter it.
//
// A qualifier naming no module the project declares -- a .NET namespace
// (`System.Text.encode`), a value receiver (`svc.encode`) -- is still not a
// qualifier here and still records as bare, so it keeps resolving unrestricted
// instead of being held to an empty scope and losing its edge.
//
// Container chains never cross files, so merging the per-file maps is exact.
func fsharpProjectModulePaths(files []FileRecord, recordsByFile map[string][]SymbolRecord, readContent contentReader) 
(map[string]string, map[string]bool) {
	pathBySymbolID := map[string]string{}
	declared := map[string]bool{}
	for _, file := range files {
		if file.Language != "F#" {
			continue
		}
		// The file's namespace declarations carry no symbol, so the path map
		// has to read them out of the source.
		var namespaces []fsharpNamespaceScope
		if content, ok := readContent(file.Path); ok {
			namespaces = fsharpNamespaceScopes(content)
		}
		filePaths, fileDeclared := fsharpModulePaths(recordsByFile[file.Path], namespaces)
		for id, path := range filePaths {
			pathBySymbolID[id] = path
		}
		for path := range fileDeclared {
			declared[path] = true
		}
	}
	return pathBySymbolID, declared
}

// fsharpQualifierMatchesModulePath reports whether a call's qualifier names the
// module a symbol is declared in. A qualifier may be written relative to the
// enclosing scope (`ScriptGeneration.f` inside `LoadingScripts`), so a suffix on
// a dot boundary counts.
func fsharpQualifierMatchesModulePath(path, qualifier string) bool {
	return path == qualifier || strings.HasSuffix(path, "."+qualifier)
}

// fsharpRootAnchoredPath reads F#'s `global.` prefix off a qualifier and
// reports whether it was there. `global` is a KEYWORD, not an identifier, and
// the grammar admits it only at the head of a long identifier, so a nested
// `A.global.B` does not parse and only a leading occurrence is stripped --
// leaving a mid-path `global` alone, which is the direction that cannot invent
// a match.
//
// The prefix is an explicit ROOT ANCHOR: `global.Serde` names the top-level
// `Serde` and nothing else, which is exactly why the keyword exists -- it is
// how F# reaches a root path that a nearer declaration of the same name would
// otherwise shadow. So the anchored reading is the stripped path matched
// EXACTLY. Reading it as an ordinary qualifier instead would be wrong in both
// directions at once: `global.Serde` matched no declared path at all, so the
// call recorded bare and bound whatever `serialize` sat nearest; and merely
// dropping the prefix would let the relative rules that follow admit a nested
// `Deep.Serde` or the caller's own `Use.Serde`, collapsing two genuinely
// different modules onto the one spelling the source went out of its way to
// disambiguate.
//
// `namespace global` is the same keyword saying the same thing at the other
// end, and fsharpNamespaceScopes already reads it as "no prefix", so a path
// declared under it is stored at the root and an anchored qualifier finds it.
func fsharpRootAnchoredPath(qualifier string) (string, bool) {
	if qualifier == "global" {
		return "", true
	}
	if rest, anchored := strings.CutPrefix(qualifier, "global."); anchored {
		return rest, true
	}
	return qualifier, false
}

// fsharpModulePathDeclared reports whether the qualifier names a module the
// PROJECT declares -- see fsharpProjectModulePaths for why the caller file's
// own declarations are the wrong question. A qualifier that names no declared
// module is not a module qualifier at all (a .NET namespace, a value receiver),
// so it stays unrestricted and resolves by name.
//
// A root-anchored qualifier is tested against the declared paths EXACTLY: it
// names one absolute path, so the suffix rule -- which exists for a qualifier
// written relative to an enclosing scope -- does not apply to it. `global`
// alone anchors nothing further and names no module, so it declares nothing.
func fsharpModulePathDeclared(declared map[string]bool, qualifier string) bool {
	if root, anchored := fsharpRootAnchoredPath(qualifier); anchored {
		return root != "" && declared[root]
	}
	for path := range declared {
		if fsharpQualifierMatchesModulePath(path, qualifier) {
			return true
		}
	}
	return false
}

// fsharpModuleAbbreviationPattern matches an F# module abbreviation
// (`module Json = Newtonsoft.Json`), which binds a LOCAL name to a module or
// namespace path. The right-hand side is captured so the verbose nested-module
// BLOCK form can be told apart by the one word that heads it; a plain
// `module Nested =` heading a block has nothing after the `=` at all.
//
// The right-hand side used to be required to start with an UPPERCASE letter,
// which is not what distinguishes an abbreviation -- it is only how the paths
// in the common case happen to be spelled. F# writes the global namespace with
// the lowercase keyword `global` (`module Json = global.Newtonsoft.Json`), and
// lets a module or namespace be named in lowercase or with a leading
// underscore, so every one of those abbreviations was missed and the alias it
// binds went unrecorded. A missed abbreviation is not a neutral omission: the
// qualifier is then classified by the project's module declarations alone, so
// `Json.serialize` under `module Json = global.Newtonsoft.Json` was pinned to
// an unrelated project module named `Json`.
//
// The WHOLE dotted right-hand side is captured, not just the word that heads
// it, because the path is what the abbreviation binds the name TO. Keeping only
// the first segment was enough to tell an abbreviation from a `begin` block but
// left `module Json = Deep.Serde` indistinguishable from `module Json = Deep`,
// so the alias could not be followed to the module it actually names.
//
// No accessibility modifier is accepted between `module` and the name, unlike
// the `let` binding below. F# parses `module private Json = Serde` and then
// rejects it outright -- FS0536, "The 'private' accessibility attribute is not
// allowed on module abbreviation. Module abbreviations are always private."
// (`pars.fsy` raises it from the abbreviation branch of the `moduleIntro EQUALS
// namedModuleDefnBlock` rule). An abbreviation therefore never carries one, and
// accepting the spelling would only invent an alias out of a line that does not
// compile. `module private Json =` heading a nested module BLOCK stays outside
// this pattern for the reason every block does: it has no path after the `=`.
var fsharpModuleAbbreviationPattern = regexp.MustCompile(`(?m)^[ 	]*module[ 	]+([A-Za-z_][A-Za-z0-9_']*)[ 	]*=[ 
	]*([A-Za-z_][A-Za-z0-9_']*(?:\.[A-Za-z_][A-Za-z0-9_']*)*)`)

func fsharpModuleAbbreviationTargetIgnored(target string) bool {
	switch target {
	case "begin", "do", "exception", "external", "let", "module", "namespace", "open", "type", "val":
		return true
	default:
		return false
	}
}

// fsharpValueBindingPattern matches a `let`/`use` VALUE binding
// (`let Json = Newtonsoft.Json.JsonConvert`, `let Json : JsonConvert = ...`),
// which also binds the name lexically. A function binding carries parameters
// between the name and the `=`, so it never matches here -- its parameters are
// read by fsharpFunctionParameterNames instead, which is the only other thing
// a `let` line can bind.
//
// The bang forms `let!` and `use!` are the same binding written inside a
// computation expression (`let! Json = fetch ()` in an `async { ... }`), with
// the same ordered, offside-delimited scope. Requiring the bare keyword missed
// every one of them, so a qualifier the CE had rebound was still classified by
// the project's module declarations and pinned `Json.serialize` to an unrelated
// project module named `Json`.
//
// The modifiers before the name are captured rather than skipped because `rec`
// changes the binding's SCOPE: without it the name is invisible inside its own
// initializer, with it the name is in scope there. `rec` was not accepted at
// all, so `let rec Json = ...` bound nothing and its own body was classified by
// the project's module declarations alone.
//
// They are spelled in F#'s own order rather than as a set of interchangeable
// words, because F# fixes that order: `let` takes `rec`, then the binding takes
// `inline`, then `mutable`, and the accessibility modifier is part of the
// PATTERN, so it stands last of all, immediately before the name --
// `let rec inline mutable private Json = ...`. Writing it anywhere else
// (`let private rec Json = ...`) is a syntax error, so a line spelled that way
// is not F# and no shadow is invented for it.
//
// Accessibility was missing entirely, which is the same class of miss as `rec`
// and not a neutral one: `let private Json = ...` bound nothing, so the
// qualifier was classified by the project's module declarations alone and
// `Json.serialize` was pinned to an unrelated project module named `Json` over
// the `serialize` the binding leaves in scope. The gap also split one `let`
// line in half -- fsharpFunctionHeaderPattern has always read `private`, so an
// accessibility-modified FUNCTION bound its parameters while an
// accessibility-modified VALUE bound nothing at all.
var fsharpValueBindingPattern = regexp.MustCompile(`(?m)^[ 	]*(?:let|use)!?[ 	]+((?:rec[ 	]+)?(?:inline[ 
	]+)?(?:mutable[ 	]+)?(?:(?:private|internal|public)[ 	]+)?)([A-Za-z_][A-Za-z0-9_']*)[ 	]*(?::[^=
]*)?=`)

// fsharpShadowBinding is one name a file binds lexically, together with the
// lines that binding governs. F# scoping is ordered and offside-based: a
// binding is invisible to everything written above it, and it dies at the
// dedent that closes the block it was written in.
type fsharpShadowBinding struct {
	name string
	// target is the module path a module ABBREVIATION binds the name to
	// (`Newtonsoft.Json` for `module Json = Newtonsoft.Json`). Every other
	// binder -- a value binding, a function parameter -- binds a value rather
	// than a module and leaves this empty.
	target string
	// fromLine is the first line the binding shadows the name on, 1-based in
	// file coordinates. That is NOT always the line the binding is written on:
	// a non-recursive `let` is not in scope inside its own initializer, so its
	// shadow starts only once the right-hand side has ended.
	fromLine int
	// fromColumn is the 0-based byte column ON fromLine from which the shadow
	// applies; earlier columns of that line are outside it. It is 0 for every
	// binding whose scope starts at a whole line, which is all of them but one:
	// `let Json = value in Json.serialize x` writes the initializer and the body
	// the binding governs on the SAME line, so the line cannot answer both ends
	// of it and the start has to be a point rather than a line.
	fromColumn int
	// throughLine is the last line the binding still shadows the name on.
	throughLine int
}

// fsharpFileShadowBindings lists the bindings this file makes, so a dotted
// prefix spelling one of them can be recognised as NOT naming a project module
// at the call sites the binding actually reaches.
//
// A qualifier was classified by the project's module declarations alone, which
// is the wrong question whenever the file rebinds the name: with
// `module Json = Newtonsoft.Json` (or `let Json = ...`) above a call and an
// unrelated project module `Json` elsewhere, `Json.serialize` was held to the
// project module and fabricated the edge into it. The local binding wins in F#'s
// own scoping, so the qualifier names the alias, not the module, and belongs in
// the same class as `System.Text.encode` and `svc.encode`: it names no project
// module, so it records bare and resolves unrestricted rather than being pinned
// to a module the source never meant.
//
// Each binding keeps its position because a file-wide set answers the question
// in the wrong place as well as the right one. A `let Json = ...` inside ONE
// function, or written BELOW the call, un-qualified every `Json.serialize` in
// the file; and since a bare qualifier resolves unrestricted, those calls did
// not merely lose a restriction, they bound whatever same-name definition sat
// nearest instead of the module the source named.
//
// Every comment and literal form is masked first, because a binding has to be
// WRITTEN to bind: only block comments were, so a `let Json = ...` line carried
// inside a triple-quoted or verbatim string -- the shapes that reach a whole
// line of their own, since a literal spanning newlines puts arbitrary text at
// the head of a line -- was collected as a real binder, and so was a
// `module Json = Newtonsoft.Json` there, which additionally REDIRECTED the
// qualifier. A `//` comment reaches the parameter pass the same way, because
// the region between a header's name and its `=` swallows a trailing comment
// when the `=` continues on the next line. A phantom shadow is the
// wrong-definition direction rather than a lost restriction: a shadowed
// qualifier records bare and resolves unrestricted, so the call binds whatever
// same-name definition sits nearest instead of the module the source wrote.
//
// The two maskers are length- and newline-preserving, which is what makes them
// usable here: shadow bindings carry LINE NUMBERS, and the offside-rule scope
// walk reads indentation, so blanking has to leave every line where it was.
//
// Bindings are per file because F# `let` and module abbreviations are lexically
// scoped to the file that writes them, unlike module declarations themselves,
// which are project-scoped.
func fsharpFileShadowBindings(content string) []fsharpShadowBinding {
	lines := strings.Split(maskFSharpLiteralsAndLineComments(maskFSharpBlockComments(content)), "
")
	var bindings []fsharpShadowBinding
	for index, line := range lines {
		if name, target, recursive := fsharpShadowBindingAt(line); name != "" {
			// F# `let` is not recursive: the name a binding introduces is not
			// in scope inside the initializer that defines it, so
			// `let Json = Json.serialize x` still names the project module on
			// its right-hand side and only rebinds the name below. Starting the
			// shadow on the binding line read that qualifier as the new value,
			// and a shadowed qualifier records bare and resolves unrestricted --
			// the wrong-definition direction, an edge into whatever `serialize`
			// sat nearest rather than the module the source wrote. `rec` asks
			// for exactly the opposite rule and keeps the binding line.
			fromLine, fromColumn := fsharpBindingScopeStart(lines, index, recursive)
			bindings = append(bindings, fsharpShadowBinding{
				name:        name,
				target:      target,
				fromLine:    fromLine,
				fromColumn:  fromColumn,
				throughLine: fsharpBindingScopeEnd(lines, index),
			})
			continue
		}
		// A `let` whose pattern is a TUPLE binds every name in it, and each one
		// shadows exactly as a single-name binding does: `let (Json, code) =
		// parse s` names the bound value below it, not the project module
		// `Json`. Only a single name was recognised, so the whole line bound
		// nothing and the qualifier was classified by the project's module
		// declarations alone -- the fabricated-edge direction, into an
		// unrelated project module named `Json`.
		//
		// Their scope is a `let`'s, not a parameter's: the same offside block,
		// and the same exclusion from the initializer, which is why they are
		// collected here rather than through the parameter pass. `let rec` does
		// not apply -- F# admits `rec` only on a binding that names a single
		// value or function -- so a destructured binding is never recursive.
		if names := fsharpDestructuringBindingNames(line); len(names) > 0 {
			fromLine, fromColumn := fsharpBindingScopeStart(lines, index, false)
			throughLine := fsharpBindingScopeEnd(lines, index)
			for _, name := range names {
				bindings = append(bindings, fsharpShadowBinding{
					name:        name,
					fromLine:    fromLine,
					fromColumn:  fromColumn,
					throughLine: throughLine,
				})
			}
			continue
		}
		// A function binding binds its PARAMETERS, and they shadow exactly as a
		// `let` does: `let run (Json: JsonConvert) x = Json.serialize x` names
		// the parameter, not the project module `Json`. Their scope is the body
		// the header opens rather than the block the header sits in, so it is
		// closed by the next line at the header's OWN indent -- the sibling
		// binding after the function -- not only by a dedent past it.
		//
		// A parameter is bound by the HEADER, not by an initializer, so unlike
		// a `let` it shadows from the header line itself: the body of
		// `let run (Json: JsonConvert) x = Json.serialize x` is written there.
		//
		// The header is read as a LOGICAL line, because F# lets one span
		// several physical ones. Parameter extraction ended at the `=` and
		// gave up on a line that had none, so `let run` followed by an
		// indented `(Json: JsonConvert) =` bound nothing at all and the
		// qualifier was classified by the project's module declarations alone
		// -- the fabricated-edge direction again, into an unrelated project
		// module `Json`.
		for _, name := range fsharpFunctionParameterNames(fsharpJoinedFunctionHeader(lines, index)) {
			bindings = append(bindings, fsharpShadowBinding{
				name:        name,
				fromLine:    index + 1,
				throughLine: fsharpParameterScopeEnd(lines, index),
			})
		}
	}
	return bindings
}

// fsharpShadowBindingAt returns the name this line binds lexically; when the
// binder is a module abbreviation, the module path it binds that name TO; and
// whether the binding is RECURSIVE, which decides whether it shadows inside its
// own initializer. A name bound to no module path -- a value, a parameter --
// comes back with an empty target. The name is empty if the line binds nothing.
//
// A module abbreviation is never recursive: `module Json = Newtonsoft.Json`
// resolves its right-hand side in the scope OUTSIDE itself, exactly as a
// non-recursive `let` does.
func fsharpShadowBindingAt(line string) (string, string, bool) {
	if match := fsharpModuleAbbreviationPattern.FindStringSubmatch(line); match != nil {
		// A module element on the same physical line still starts a nested module
		// BLOCK: `module M = let value = 1`. Its leading keyword is not a path
		// being aliased. Treating `let` as the target made M shadow the real nested
		// module and left `M.value` free to bind an unrelated same-named symbol.
		if fsharpModuleAbbreviationTargetIgnored(match[2]) {
			return "", "", false
		}
		return match[1], match[2], false
	}
	if match := fsharpValueBindingPattern.FindStringSubmatch(line); match != nil {
		return match[2], "", slices.Contains(strings.Fields(match[1]), "rec")
	}
	return "", "", false
}

// fsharpBindingScopeStart returns the first POINT -- line and 0-based byte
// column on it -- from which the binding written on lines[index] shadows its
// name.
//
// Three of the four answers are whole lines and were already settled: `rec`
// asks for the binding's own line, because the name is in scope inside its own
// body; without it the shadow starts on the line after the initializer ends,
// because the name is invisible in the right-hand side that defines it; and a
// PARAMETER, which does not pass through here, shadows from its header line.
//
// The fourth is `let name = initializer in body`, and it is why a column is
// needed at all. F# scope starts at a point in the token stream, not at a line
// boundary; the line was only ever a workable approximation of it, and the
// explicit `in` is the shape that breaks the approximation by writing the
// initializer and the body it governs on ONE line. Rounding the start up to
// the next line put the body outside the shadow, so `let Json = value in
// Json.serialize x` -- a call the binding plainly reaches -- was classified by
// the project's module declarations and pinned to an unrelated module `Json`.
// Rounding it down to the whole line instead would break the other direction
// that is already pinned: `let Json = Json.serialize x in Json` must keep its
// right-hand side OUT of the shadow. Only a column answers both, so the start
// is the column just past the `in`.
func fsharpBindingScopeStart(lines []string, index int, recursive bool) (int, int) {
	if recursive {
		return index + 1, 0
	}
	if column, explicit := fsharpLetInBodyColumn(lines[index]); explicit {
		return index + 1, column
	}
	return fsharpInitializerEnd(lines, index) + 1, 0
}

// fsharpLetInBodyColumn returns the column at which the body of an explicit
// `let ... = ... in <body>` begins on this line, and whether the line writes
// one. The `in` taken is the one this binding's own initializer reaches, and
// finding it needs a DEPTH count rather than a first-match: an initializer may
// itself open bindings, and each of those consumes an `in` of its own before
// this binding's arrives.
//
// Taking the first one instead read the wrong keyword whenever the initializer
// nested a binding of its own. In `let Json = let x = 1 in Json.serialize x`
// the only `in` on the line closes the INNER `let x`, so the whole line is
// still the outer binding's initializer and `Json` is unavailable across all of
// it; starting the shadow past that `in` moved it EARLIER than the binding and
// pinned the call to the local value instead of the project module `Json`.
// That is the fabricated-edge direction, not the narrow one. Counting `let`
// and `use` opened after the first `=` and spending one per `in` gives the
// outer binding its own keyword back: the line above now opens no body at all,
// and `let a = let x = 1 in x in a + 1` takes the SECOND `in`, not the first.
//
// Everything before the `in` that is taken belongs to an initializer, and
// everything after it is governed by this binding, so a shadow that starts
// there can only be too late, never too early -- which is what the count
// restores.
//
// A top-level `for` before the `in` means the `in` is a SEQUENCE iterator
// (`let total = for x in xs do count x`), not the keyword that opens a binding
// body, so the line is declined: the loop body is still the initializer, and
// the binding is not in scope there. `in` inside brackets is left alone for the
// same reason -- a `for` or a nested `let` written inside a comprehension,
// sequence expression or parenthesised group is not this binding's body.
//
// A nested binding that spends no `in` -- a computation expression's `let!`,
// which is closed by the line ending rather than by a keyword -- leaves the
// count one too high and the line is declined. That is the narrow answer: a
// missed shadow leaves the previous classification standing, while an invented
// one moves a call to a different definition.
//
// The line reaching here has already been through both maskers, so an `in`
// written inside a string or a comment is blanked and cannot be seen.
func fsharpLetInBodyColumn(line string) (int, bool) {
	depth, afterEquals, nested := 0, false, 0
	for index := 0; index < len(line); {
		if fsharpWordByte(line[index]) {
			end := index
			for end < len(line) && fsharpWordByte(line[end]) {
				end++
			}
			if depth == 0 {
				switch line[index:end] {
				case "for":
					return 0, false
				case "let", "use":
					if afterEquals {
						nested++
					}
				case "in":
					if afterEquals {
						if nested == 0 {
							return end, true
						}
						nested--
					}
				}
			}
			index = end
			continue
		}
		switch line[index] {
		case '(', '[', '{':
			depth++
		case ')', ']', '}':
			if depth > 0 {
				depth--
			}
		case '=':
			if depth == 0 {
				afterEquals = true
			}
		}
		index++
	}
	return 0, false
}

// fsharpWordByte reports whether the byte can stand inside an F# identifier.
// The apostrophe is one of them (`xs'`), which is what keeps a name ending in
// `in` or `for` from being read as the keyword.
func fsharpWordByte(character byte) bool {
	return character == ''' || isIdentifierByte(character)
}

// fsharpDestructuringBindingHeadPattern matches the keyword and modifiers that
// open a `let`/`use` binding, stopping at the pattern it binds. It is the same
// head fsharpValueBindingPattern reads, minus the single NAME that pattern
// requires next, so the shapes a name cannot describe are reachable.
var fsharpDestructuringBindingHeadPattern = regexp.MustCompile(`^[ 	]*(?:let|use)!?[ 
	]+(?:(?:rec|inline|mutable|private|internal|public)[ 	]+)*`)

// fsharpDestructuringBindingNames lists the names a `let`/`use` binding whose
// pattern is a TUPLE binds -- `let (Json, code) = parse s`, and the same
// pattern written without its parentheses, `let Json, code = parse s`.
//
// The pattern must be a single parenthesised group, or a top-level
// comma-separated list; a parenthesised one is then read by the same
// fsharpParameterGroupBinders that reads a group in PARAMETER position, and
// admits exactly what that function admits -- names, tuples and their
// nestings, `as`, and a union-case application (`let (Ok Json) = result`
// binds `Json`). A parameter and a `let` pattern are the same grammar
// production, so reading a shape as binders in one and not the other is an
// inconsistency, not a safety margin.
//
// Shapes the group reader declines are declined here too, for refinement 4's
// reason -- a name standing in a pattern position need not be a binder, and
// binding one that is really a union case un-qualifies calls that legitimately
// name a module of that name. Two more are declined by this function's own
// region test, which requires a SINGLE group and so never reaches the reader:
//
//   - A RECORD pattern (`let { Result = Json } = r`). The name stands after a
//     field's own `=`, which is a nested pattern position in the fullest sense:
//     `let { Result = Error } = r` matches the nullary case `Error` and binds
//     nothing at all, and nothing on the line tells the two apart. The braces
//     are shared with computation, object and anonymous-record expressions and
//     the field label may itself be dotted, so the form is not even closed by
//     its brackets.
//   - A LIST or ARRAY pattern (`let [a; Json] = xs`, `let [| a; Json |] = xs`).
//     Same nested pattern position, and the form is refutable by construction,
//     so it is never a plain destructuring of a known shape.
//   - A CONS pattern (`let head :: Json = xs`) -- refutable in the same way.
//   - An `as` pattern written outside the group (`let (a, b) as Json = pair`),
//     whose binder is unambiguous but whose region is a group followed by more
//     text, which is also how an operator definition and an active pattern are
//     told apart from a destructuring. Inside a group -- a parameter's
//     `(pair as Json)` -- `as` IS read.
//
// A pattern spread over several lines is declined too: with no `=` on the line
// there is no region to read, and the narrow answer keeps the previous
// classification rather than inventing a shadow.
func fsharpDestructuringBindingNames(line string) []string {
	head := fsharpDestructuringBindingHeadPattern.FindString(line)
	if head == "" {
		return nil
	}
	region, found := fsharpParameterRegion(line[len(head):])
	if !found {
		return nil
	}
	// A top-level comma is the tuple written without parentheses. Reading it
	// first keeps `let f (a, b) c = ...` out: that comma sits inside the
	// parameter's brackets, so the header falls through to the parameter pass
	// that owns it.
	if parts := fsharpSplitTopLevel(region, ','); len(parts) > 1 {
		var names []string
		for _, part := range parts {
			if name := fsharpParameterBinderName(part); name != "" {
				names = append(names, name)
			}
		}
		return names
	}
	// A parenthesised pattern binds only when the parentheses are the WHOLE
	// region: `let (a, Json) = ...` is a tuple binding, while `let f (a, b) =
	// ...` names a function and `let (|Even|Odd|) n = ...` an active pattern,
	// both of which carry text outside the group and belong to other passes.
	pattern := strings.TrimSpace(region)
	if !strings.HasPrefix(pattern, "(") || !strings.HasSuffix(pattern, ")") {
		return nil
	}
	return fsharpParameterGroupBinders(pattern)
}

// fsharpFunctionHeaderPattern matches the head of a `let`/`use` FUNCTION
// binding: the keyword, any modifiers, the name it binds, and the whitespace
// before its first parameter. A VALUE binding writes `=` or a type annotation
// straight after the name, so the two forms stay disjoint and a line is read as
// one or the other, never both.
var fsharpFunctionHeaderPattern = regexp.MustCompile(`^[ 	]*(?:let|use)!?[ 
	]+(?:(?:rec|inline|mutable|private|internal|public)[ 	]+)*[A-Za-z_][A-Za-z0-9_']*[ 	]+`)

// fsharpParameterBinderPattern matches a parameter that is a plain name,
// carrying an optional type annotation (`Json`, `Json: JsonConvert`). Only the
// NAME is captured: `let run (x: Json) = Json.serialize x` binds `x` and merely
// MENTIONS the type `Json`, so reading an annotation as a binder would shadow a
// qualifier nothing rebound -- and a shadowed qualifier resolves unrestricted,
// which binds whatever same-name definition sits nearest instead of the module
// the source wrote.
var fsharpParameterBinderPattern = regexp.MustCompile(`^[ 	]*([A-Za-z_][A-Za-z0-9_']*)[ 	]*(?::.*)?$`)

// fsharpFunctionParameterNames lists the names a function header binds through
// its parameters. A parameter shadows a module qualifier exactly as a `let`
// does -- `let run (Json: JsonConvert) x = Json.serialize x` names the
// parameter -- but only value bindings were recognised, so the qualifier was
// classified by the project's module declarations alone and the call was pinned
// to an unrelated project module named `Json`.
//
// Each whitespace-separated group is one parameter, and what a group binds is
// fsharpPatternComponentBinders' answer: a name, a tuple and its nestings, an
// `as` pattern, or the arguments of a union-case application. A list, record,
// cons, or/and pattern is left unbound, because a name standing there need not
// be a binding at all: `Some`, `None` and `Error` are union CASES, and binding
// them would un-qualify calls that legitimately name a module of that name.
// Missing a shadow leaves the previous answer; inventing one changes a call's
// target, so the unmodelled shapes stay out.
func fsharpFunctionParameterNames(line string) []string {
	header := fsharpFunctionHeaderPattern.FindString(line)
	if header == "" {
		return nil
	}
	region, found := fsharpParameterRegion(line[len(header):])
	if !found {
		return nil
	}
	var names []string
	for _, group := range fsharpSplitTopLevel(region, ' ', '	') {
		names = append(names, fsharpParameterGroupBinders(group)...)
	}
	return names
}

// fsharpParameterRegion returns the parameter text of a function header: what
// stands between the name and the `=` that opens the body. Brackets are counted
// so a `=` inside an attribute is not mistaken for the one ending the header,
// and a top-level `:` ends the region too because what follows it is the RETURN
// type, not a parameter. A header split across lines carries no `=` on this
// line and binds nothing here -- the narrow answer, which keeps the previous
// classification rather than inventing a shadow.
func fsharpParameterRegion(rest string) (string, bool) {
	depth := 0
	for index := 0; index < len(rest); index++ {
		switch rest[index] {
		case '(', '[', '{':
			depth++
		case ')', ']', '}':
			if depth > 0 {
				depth--
			}
		case ':', '=':
			if depth == 0 {
				return rest[:index], true
			}
		}
	}
	return "", false
}

// fsharpBindingKeywordPattern matches the keyword that can open a `let`/`use`
// header, with the whitespace that must follow it. It is deliberately weaker
// than fsharpFunctionHeaderPattern, which also demands whitespace AFTER the
// bound name and so declines the very line this bug is about: `let run`, whose
// parameters are written on the lines below it.
var fsharpBindingKeywordPattern = regexp.MustCompile(`^[ 	]*(?:let|use)!?[ 	]`)

// fsharpFunctionHeaderContinuationLines bounds how far a header is followed
// down the file. A parameter list that long does not exist; the bound is what
// stops a `let` whose `=` never arrives from swallowing the rest of the block.
const fsharpFunctionHeaderContinuationLines = 32

// fsharpJoinedFunctionHeader returns the LOGICAL header line that begins on
// lines[index]: the line itself when it already carries the `=` (or the
// top-level `:` introducing a return type) that ends a header, and otherwise
// that line joined with the lines below it up to the one that does.
//
// F# writes a long signature across several lines, and a parameter binds a
// qualifier from wherever it is written:
//
//	let run
//	    (Json: JsonConvert)
//	    (x: int) =
//	    Json.serialize x
//
// Read one physical line at a time, `let run` has no `=` and bound nothing, so
// `Json` was not recorded as shadowing and the call was pinned to whatever
// project module happened to be named `Json`.
//
// The join follows the offside rule, which is what makes it safe: a
// continuation of a header is indented PAST the `let` that opens it, so the
// first following line back at the header's own indent -- the sibling binding
// -- stops the join, and a blank line stops it too. Only a line that opens a
// binding is followed at all, and the join stops at the first `=` outside
// brackets, so it can never reach into a body. Where no such line is found the
// caller reads no parameter region and binds nothing, which is the narrow
// answer: a missed shadow leaves the previous classification standing, while an
// invented one moves a call to a different definition.
//
// Completeness is judged on the JOINED text rather than the line just added, so
// a header whose parenthesis opens on one line and closes on another is
// followed to its real end instead of stopping inside the brackets.
func fsharpJoinedFunctionHeader(lines []string, index int) string {
	joined := lines[index]
	if !fsharpBindingKeywordPattern.MatchString(joined) {
		return joined
	}
	if _, complete := fsharpParameterRegion(joined); complete {
		return joined
	}
	indent := fsharpIndentWidth(joined)
	for next := index + 1; next < len(lines) && next-index <= fsharpFunctionHeaderContinuationLines; next++ {
		if strings.TrimSpace(lines[next]) == "" || fsharpIndentWidth(lines[next]) <= indent {
			break
		}
		joined += " " + lines[next]
		if _, complete := fsharpParameterRegion(joined); complete {
			break
		}
	}
	return joined
}

// fsharpParameterGroupBinders returns the names one parameter group binds. A
// parenthesised group holds a PATTERN, which is read by fsharpPatternBinders;
// an unparenthesised group is a bare parameter and binds only when it is a
// plain name.
func fsharpParameterGroupBinders(group string) []string {
	trimmed := strings.TrimSpace(group)
	if strings.HasPrefix(trimmed, "(") && strings.HasSuffix(trimmed, ")") {
		return fsharpPatternBinders(trimmed[1 : len(trimmed)-1])
	}
	if name := fsharpParameterBinderName(trimmed); name != "" {
		return []string{name}
	}
	return nil
}

// fsharpPatternBinders returns the names the CONTENTS of a parenthesised
// pattern bind. A top-level comma makes it a tuple, and every component is a
// pattern in its own right.
func fsharpPatternBinders(pattern string) []string {
	if components := fsharpSplitTopLevel(pattern, ','); len(components) > 1 {
		var names []string
		for _, component := range components {
			names = append(names, fsharpPatternComponentBinders(component)...)
		}
		return names
	}
	return fsharpPatternComponentBinders(pattern)
}

// fsharpPatternComponentBinders returns the names one pattern component binds.
// Only names, tuples and their parenthesised nestings were read before, so
// every other shape bound nothing: `let run (Some Json) = Json.serialize x`
// left `Json` unbound and the qualifier resolution pinned the call to an
// unrelated project module named `Json` -- an edge into a definition the source
// never wrote, in place of the value the pattern leaves in scope.
//
// Four shapes are ADMITTED, each because the name it yields cannot be anything
// but a binder:
//
//   - A plain name, with at most a type annotation (`Json`, `Json: JsonConvert`).
//     Only the name is taken; the annotation is a MENTION.
//   - A parenthesised nesting (`(a, (b, Json))`). A tuple inside a tuple is
//     still a tuple, and reading the outer one but not the inner was an
//     omission rather than a margin.
//   - An `as` pattern (`(p as Json)`). F# grammar admits only an identifier
//     after `as`, and it always binds. The pattern to its LEFT is read as a
//     component too, which declines a type test (`(:? Stream as Json)` binds
//     `Json` and not the type `Stream`) without a rule of its own.
//   - A union-case application (`(Some Json)`, `(Response (code, Json))`). The
//     HEAD of an application in pattern position is a case, never a binder, so
//     it is dropped and the arguments are read. This is the one shape a
//     previous round declined that the PARAMETER position argues back: peeling
//     a single-case union in the header (`let handle (Request Json) = ...`) is
//     how F# code uses one, it is irrefutable, and it draws no warning.
//
// The shapes still declined are the ones where a name standing in the pattern
// need not be a binder at all -- `Some`, `None` and `Error` are union CASES,
// and binding one un-qualifies calls that legitimately name a module of that
// name. A shadowed qualifier records bare and resolves unrestricted, so
// inventing a binder does not merely lose a restriction, it binds whatever
// same-name definition sits nearest:
//
//   - The WILDCARD `_`, alone or annotated, which binds nothing by definition.
//   - A RECORD pattern (`{ Result = Json }`). The name stands after a field's
//     own `=`, where `{ Result = Error }` matches the nullary case and binds
//     nothing; the braces are shared with computation, object and
//     anonymous-record expressions, and the field label may be dotted.
//   - A LIST or ARRAY pattern (`[a; Json]`, `[| a; Json |]`) and a CONS
//     pattern (`head :: Json`), refutable by construction and never the plain
//     peeling of a known shape that the union-case form is.
//   - An OR or AND pattern (`Some Json | Other Json`, `a & Json`), whose
//     alternatives are cases as readily as binders.
//   - Anything carrying a top-level `:` the plain-name reader did not consume,
//     which is an annotation on a shape this function does not model, and
//     `?optional`, which exists only on members -- a form this pass never sees,
//     because it reads `let`/`use` headers alone.
func fsharpPatternComponentBinders(component string) []string {
	trimmed := strings.TrimSpace(component)
	if trimmed == "" {
		return nil
	}
	if name := fsharpParameterBinderName(trimmed); name != "" {
		return []string{name}
	}
	if strings.HasPrefix(trimmed, "(") && strings.HasSuffix(trimmed, ")") {
		return fsharpPatternBinders(trimmed[1 : len(trimmed)-1])
	}
	if left, bound, isAs := fsharpAsPatternSplit(trimmed); isAs {
		return append(fsharpPatternComponentBinders(left), bound)
	}
	if fsharpPatternComponentDeclined(trimmed) {
		return nil
	}
	// An application: the head is the union case being matched and every
	// argument after it is a pattern.
	arguments := fsharpSplitTopLevel(trimmed, ' ', '	')
	if len(arguments) < 2 {
		return nil
	}
	var names []string
	for _, argument := range arguments[1:] {
		names = append(names, fsharpPatternComponentBinders(argument)...)
	}
	return names
}

// fsharpAsPatternSplit splits `<pattern> as <name>` at its LAST top-level `as`,
// which is the one that binds outermost in `a as b as c`. The name it binds is
// reported only when it is a plain identifier, so a line that merely writes the
// word is not read as the keyword.
func fsharpAsPatternSplit(component string) (string, string, bool) {
	depth, keyword := 0, -1
	for index := 0; index < len(component); {
		if fsharpWordByte(component[index]) {
			end := index
			for end < len(component) && fsharpWordByte(component[end]) {
				end++
			}
			if depth == 0 && component[index:end] == "as" {
				keyword = index
			}
			index = end
			continue
		}
		switch component[index] {
		case '(', '[', '{':
			depth++
		case ')', ']', '}':
			if depth > 0 {
				depth--
			}
		}
		index++
	}
	if keyword < 0 {
		return "", "", false
	}
	bound := fsharpParameterBinderName(component[keyword+len("as"):])
	if bound == "" {
		return "", "", false
	}
	return component[:keyword], bound, true
}

// fsharpPatternComponentDeclined reports whether a component carries a
// top-level token that puts it in one of the shapes this reader does not model
// -- a list or record body, a cons, an or/and pattern, an annotation the
// plain-name reader did not consume, or an optional parameter. Brackets are
// counted, so the same token written inside a nested group is not read here.
func fsharpPatternComponentDeclined(component string) bool {
	if strings.HasPrefix(component, "[") || strings.HasPrefix(component, "{") {
		return true
	}
	depth := 0
	for index := 0; index < len(component); index++ {
		switch component[index] {
		case '(', '[', '{':
			depth++
		case ')', ']', '}':
			if depth > 0 {
				depth--
			}
		case ':', ';', '|', '&', '?':
			if depth == 0 {
				return true
			}
		}
	}
	return false
}

// fsharpParameterBinderName returns the name a parameter binds, or "" when it
// is not a plain name. The wildcard `_` binds nothing.
func fsharpParameterBinderName(text string) string {
	match := fsharpParameterBinderPattern.FindStringSubmatch(text)
	if match == nil || match[1] == "_" {
		return ""
	}
	return match[1]
}

// fsharpSplitTopLevel splits text on the separators, ignoring any that fall
// inside brackets, and drops empty fields.
func fsharpSplitTopLevel(text string, separators ...byte) []string {
	var fields []string
	depth, start := 0, -1
	for index := 0; index < len(text); index++ {
		character := text[index]
		switch character {
		case '(', '[', '{':
			depth++
		case ')', ']', '}':
			if depth > 0 {
				depth--
			}
		}
		if depth == 0 && slices.Contains(separators, character) {
			if start >= 0 {
				fields = append(fields, text[start:index])
				start = -1
			}
			continue
		}
		if start < 0 {
			start = index
		}
	}
	if start >= 0 {
		fields = append(fields, text[start:])
	}
	return fields
}

// fsharpBindingScopeEnd returns the last line the binding written on
// lines[index] is still in scope for. F#'s offside rule closes the block a
// binding lives in at the first following line indented less than the binding
// itself, so a function-local binding ends with its function; a binding at its
// module's own level is closed by nothing and reaches the end of the file.
// Blank and comment-only lines carry no indentation of their own, so they never
// close a block.
func fsharpBindingScopeEnd(lines []string, index int) int {
	return fsharpScopeEnd(lines, index, false)
}

// fsharpInitializerEnd returns the last line of the initializer belonging to the
// binding written on lines[index] -- the whole right-hand side, which the
// offside rule writes as the block that line opens and the first following line
// back at the binding's own indent closes. A single-line binding therefore ends
// on its own line, and a binding whose right-hand side runs on ends with the
// last continuation line.
//
// This is what a non-recursive binding is NOT in scope for. It is the same
// offside question a parameter's body asks, so it shares the rule, but it is a
// different question and is asked at the other end of the binding.
func fsharpInitializerEnd(lines []string, index int) int {
	return fsharpScopeEnd(lines, index, true)
}

// fsharpParameterScopeEnd returns the last line the parameters declared by the
// header on lines[index] are still in scope for. A parameter lives in the body
// the header OPENS, and that body is written indented past the header, so the
// next line back at the header's own indent -- the sibling `let` after the
// function -- already ends it. Reusing the `let` rule instead would carry a
// top-level function's parameters to the end of the file and un-qualify every
// call below it, which is the wrong-definition direction of this same bug.
func fsharpParameterScopeEnd(lines []string, index int) int {
	return fsharpScopeEnd(lines, index, true)
}

func fsharpScopeEnd(lines []string, index int, closedByOwnIndent bool) int {
	indent := fsharpIndentWidth(lines[index])
	for i := index + 1; i < len(lines); i++ {
		trimmed := strings.TrimSpace(lines[i])
		if trimmed == "" || strings.HasPrefix(trimmed, "//") {
			continue
		}
		width := fsharpIndentWidth(lines[i])
		if width < indent || (closedByOwnIndent && width == indent) {
			return i
		}
	}
	return len(lines)
}

func fsharpIndentWidth(line string) int {
	return len(line) - len(strings.TrimLeft(line, " 	"))
}

// fsharpShadowsAt returns a lookup from a byte offset inside one call block --
// which starts at startLine in the file -- to the names shadowed on the LINE
// that offset falls on.
//
// The shadow set used to be computed once for a whole block. F# scoping is
// ordered, so that answered the question in the wrong place as well as the
// right one: a `let Json = ...` written partway down a function was applied to
// the `Json.serialize` calls ABOVE it too, and because a shadowed qualifier
// records bare and resolves unrestricted, the earlier call did not merely lose
// its restriction -- it bound whatever same-name definition sat nearest instead
// of the module the source named. Both sightings then collapsed onto the bare
// one and the module-qualified edge disappeared. Deciding per call SITE is the
// same rule applied at the granularity F# actually scopes at.
//
// Blank lines need no special case any more: a call site is never on one. The
// lookup is memoised per line because a block commonly holds many call sites on
// few distinct lines.
//
// Each name maps to the module path it was bound to, empty for a binder that
// binds no module. Bindings are visited in source order, so where two of them
// reach the same line the LATER one is left standing -- the inner or nearer
// binding, which is the one F# resolves the name to.
func fsharpShadowsAt(bindings []fsharpShadowBinding, block string, startLine int) func(offset int) map[string]string {
	if len(bindings) == 0 {
		return func(int) map[string]string { return nil }
	}
	if startLine < 1 {
		startLine = 1
	}
	newlines := newlineOffsets(block)
	byLine := map[int][]fsharpShadowBinding{}
	return func(offset int) map[string]string {
		lineInBlock := lineAtOffset(newlines, offset)
		at := startLine + lineInBlock - 1
		reaching, known := byLine[at]
		if !known {
			for _, binding := range bindings {
				if binding.fromLine <= at && at <= binding.throughLine {
					reaching = append(reaching, binding)
				}
			}
			byLine[at] = reaching
		}
		if len(reaching) == 0 {
			return nil
		}
		// Only the line is memoised, because the column matters for at most
		// the one binding whose scope STARTS on this line -- an explicit
		// `let ... in ...`, whose initializer and body share it. Every other
		// binding carries column 0 and is admitted by the same comparison.
		//
		// The column is the call site's offset within its line, and it is a
		// FILE column because every F# block handed to this lookup begins at
		// the start of startLine and holds whole lines from there.
		column := offset - fsharpLineStartOffset(newlines, lineInBlock)
		var shadows map[string]string
		for _, binding := range reaching {
			if at == binding.fromLine && column < binding.fromColumn {
				continue
			}
			if shadows == nil {
				shadows = map[string]string{}
			}
			shadows[binding.name] = binding.target
		}
		return shadows
	}
}

// fsharpLineStartOffset returns the byte offset the 1-based line begins at,
// given the newline offsets of the same text.
func fsharpLineStartOffset(newlines []int, line int) int {
	if line <= 1 {
		return 0
	}
	if line-2 >= len(newlines) {
		return 0
	}
	return newlines[line-2] + 1
}

// newlineOffsets lists the byte offset of every newline in text, so a byte
// offset can be turned into a line number by a binary search instead of by
// re-counting the text once per call site.
func newlineOffsets(text string) []int {
	var offsets []int
	for start := 0; start < len(text); {
		index := strings.IndexByte(text[start:], '
')
		if index < 0 {
			break
		}
		offsets = append(offsets, start+index)
		start += index + 1
	}
	return offsets
}

// lineAtOffset returns the 1-based line offset falls on, given the newline
// offsets of the same text.
func lineAtOffset(newlines []int, offset int) int {
	return sort.SearchInts(newlines, offset) + 1
}

// fsharpShadowedQualifierAlias reports whether the shadows in scope at the call
// site rebind the name the qualifier leads with, and if that binding was a
// module abbreviation, returns the qualifier REWRITTEN through it. Only the
// FIRST segment can be shadowed: a local `module Json = ...` rebinds `Json` and
// therefore `Json.Linq`, but says nothing about `Newtonsoft.Json`.
//
// The rewrite is the point of keeping the abbreviation's target. `module Json =
// Serde` does not make `Json.serialize` unqualified -- it makes it
// `Serde.serialize`. Only the head is substituted, so `Json.Linq.parse` under
// that binding reads `Serde.Linq.parse`, which is what the abbreviation means.
func fsharpShadowedQualifierAlias(shadows map[string]string, qualifier string) (string, bool) {
	if len(shadows) == 0 {
		return "", false
	}
	head, rest := qualifier, ""
	if cut := strings.Index(qualifier, "."); cut >= 0 {
		head, rest = qualifier[:cut], qualifier[cut:]
	}
	target, shadowed := shadows[head]
	if !shadowed || target == "" {
		return "", shadowed
	}
	return target + rest, true
}

// recordFSharpCallQualifier remembers which module a qualified call named, so
// resolution can keep `A.convert` off `B.convert`. EVERY distinct qualifier is
// kept, because each one is its own call site: a caller writing
// `x |> A.convert |> B.convert` calls two different functions, and collapsing
// them onto one entry for the name loses one of the two edges. A call written
// without a qualifier the project declares -- or spelling a name the FILE
// rebinds, which is the same thing once F#'s own scoping is applied -- records
// the empty string: that spelling names no module, so it means "the definition
// in scope" and is resolved unrestricted -- alongside, not instead of, the
// qualified sightings.
func recordFSharpCallQualifier(qualifiers map[string]map[string]struct{}, declared map[string]bool, shadows 
map[string]string, name, target string) {
	qualifier := ""
	if cut := strings.LastIndex(target, "."); cut > 0 {
		candidate := target[:cut]
		alias, shadowed := fsharpShadowedQualifierAlias(shadows, candidate)
		switch {
		case !shadowed:
			if fsharpModulePathDeclared(declared, candidate) {
				qualifier = candidate
			}
		case alias != "" && fsharpModulePathDeclared(declared, alias):
			// A module ABBREVIATION is the one shadow that still names a
			// module. Treating it like any other rebinding recorded bare, and a
			// bare spelling resolves unrestricted -- so `Json.serialize` under
			// `module Json = Serde` bound whatever `serialize` sat nearest
			// instead of Serde's, which is the wrong-definition direction of
			// this same bug rather than a lost restriction. Follow the alias
			// instead: the call names the module the abbreviation points at.
			//
			// Only when that target is a module the PROJECT declares. An
			// abbreviation of an external path (`module Json =
			// Newtonsoft.Json`) names nothing this index can hold the call to,
			// so it stays bare exactly as before -- the same test
			// `fsharpModulePathDeclared` already applies to an unshadowed
			// qualifier, asked of the aliased spelling.
			qualifier = alias
		}
	}
	if qualifiers[name] == nil {
		qualifiers[name] = map[string]struct{}{}
	}
	qualifiers[name][qualifier] = struct{}{}
}

// fsharpResolvableQualifiers lists the spellings a name was called with, one
// resolution per spelling.
//
// The two spellings MEAN different things and are different call sites. A bare
// `convert(x)` names no module: F# resolves it by scope, to whatever `convert`
// is in scope at that point. A qualified `A.convert(x)` names module A
// explicitly and can only be A's. A caller writing both therefore makes two
// calls, and both edges exist.
//
// The empty string is one of those spellings, not a veto over the others.
// Treating it as a veto -- reporting nothing, so the whole name fell back to
// unrestricted resolution -- resolved `A.convert(x)` as if it had been written
// bare, and unrestricted resolution emits only the same-name definition nearest
// the call site, so A's edge was dropped outright.
func fsharpResolvableQualifiers(qualifiers map[string]struct{}) []string {
	return sortedKeysOf(qualifiers)
}

// fsharpRelativeQualifierPaths lists the module paths a relative qualifier may
// name from inside callerPath, innermost enclosing scope first.
//
// A qualifier is read from the caller OUTWARDS, so every enclosing scope is a
// reading, not just the caller's own module: inside `Root.Caller`, `A.f` means
// the sibling `Root.A`. Trying only `callerPath + "." + qualifier` matched
// nothing there and dropped to the plain suffix, which admits `Root.A` AND an
// unrelated top-level `A` -- and `resolveCallTargets` then picked whichever sat
// nearer the call site.
//
// The walk subsumes the caller's own path as a reading in its own right: from
// inside `LoadingScripts.ScriptGeneration`, the scope `LoadingScripts` yields
// `LoadingScripts.ScriptGeneration`, which is where `ScriptGeneration.build`
// really points. The outermost scope is the empty one, so a qualifier naming a
// top-level module resolves exactly rather than by suffix.
//
// A caller in no module at all -- a statement at file level, the normal shape
// of an .fsx script -- has exactly one reading: the qualifier spelled from the
// project root. It is the outermost step of the same walk with nothing above
// it, so it is returned alone; concatenating it onto an empty caller path would
// produce the leading-dot `.A`, which names nothing.
func fsharpRelativeQualifierPaths(callerPath, qualifier string) []string {
	if callerPath == "" {
		return []string{qualifier}
	}
	paths := []string{callerPath + "." + qualifier}
	for scope := callerPath; scope != ""; {
		cut := strings.LastIndex(scope, ".")
		if cut < 0 {
			scope = ""
		} else {
			scope = scope[:cut]
		}
		if scope == "" {
			paths = append(paths, qualifier)
			break
		}
		paths = append(paths, scope+"."+qualifier)
	}
	return paths
}

// fsharpQualifiedScope drops the symbols that the qualifier rules out. F#
// modules are project-scoped, so this reaches other files too: `A.convert`
// written in C.fs is module A's, wherever A is declared. Symbols of another
// language have no module path and are left alone.
func fsharpQualifiedScope(symbols []SymbolRecord, qualifier, callerPath string, pathBySymbolID map[string]string, 
declared map[string]bool) []SymbolRecord {
	if qualifier == "" {
		// The BARE spelling restricts nothing: it names no module, so it means
		// the definition in scope and resolves over every candidate, exactly as
		// the unrestricted path does.
		return symbols
	}
	// A ROOT-ANCHORED qualifier (`global.Serde.serialize`) has exactly one
	// reading and it is absolute, so the relative walk and the suffix fallback
	// below are both skipped: they are how a qualifier written relative to an
	// enclosing scope is resolved, and `global.` is the spelling that says the
	// qualifier is NOT relative. Letting them run on the stripped path would
	// undo the anchor -- from inside `Use`, a nested `Use.Serde` is the first
	// reading tried and would win the call that named the root `Serde`.
	if root, anchored := fsharpRootAnchoredPath(qualifier); anchored {
		return fsharpNarrowToModule(symbols, pathBySymbolID, func(path string) bool { return path == root })
	}
	// A relative qualifier is read from the caller outwards, so resolve it
	// against the caller's own module before falling back to a suffix. With both
	// `ScriptGeneration` and `LoadingScripts.ScriptGeneration` declaring `f`, a
	// plain suffix admits BOTH and the winner then depends on caller scope and
	// source order. From inside `LoadingScripts`, `ScriptGeneration.f` names the
	// nested one, and that reading is exact rather than ambiguous.
	//
	// A file-level caller passes "" and has exactly one reading, the qualifier
	// itself -- and it was skipped entirely, so those calls went straight to the
	// suffix. That is too loose: at file level `A.build` names the top-level
	// module A, while the suffix admits a nested `Outer.A` as well, and the
	// nearest-definition tie-break then bound the call to a module the source
	// never named. Trying the exact reading first fixes that without touching
	// the case the suffix exists for -- a qualifier naming a module only ever
	// declared inside another one, reached through an `open` this does not
	// model, still finds no exact reading and still falls through.
	//
	// Innermost reading first: a module the caller's own module declares
	// shadows the outer binding of the same name. Concatenating
	// unconditionally repeated the segment
	// (`...ScriptGeneration.ScriptGeneration`), matched nothing, and
	// dropped to the plain suffix, which admits the nested module AND an
	// unrelated top-level `ScriptGeneration`; the winner was then the
	// definition nearest the call site rather than the one written.
	// Which reading applies is a property of the PROJECT's declarations, not
	// of the symbol set being filtered. F# modules are project-scoped and the
	// usual layout is one module per file, so the sibling a relative
	// qualifier names is normally declared somewhere ELSE: with `Outer.A` in
	// one file and `Outer.Caller` in another, picking the reading by which
	// candidate sat in the caller's own file made `Outer.A` unmatchable, and
	// the call fell through to the plain suffix -- which admits `Outer.A` AND
	// an unrelated top-level `A`. That lost the call both ways: ambiguous
	// candidates dropped the edge outright, and where the top-level `A` was
	// declared in the caller's own file it matched the OUTERMOST reading and
	// won, so the nearer scope the caller actually meant was shadowed by the
	// farther one. Reading against `declared` also keeps the two scopes this
	// is called on -- the project-wide candidates and the caller file's own
	// symbols -- agreeing on ONE reading; choosing per set let the narrower
	// one settle on an outer reading the wider one had already rejected, and
	// the same-file branch of resolveCallTargets then won with it.
	for _, exact := range fsharpRelativeQualifierPaths(callerPath, qualifier) {
		if !declared[exact] {
			continue
		}
		return fsharpNarrowToModule(symbols, pathBySymbolID, func(path string) bool { return path == exact })
	}
	// Every F# symbol in the project has a known module path, so a qualified
	// call is held to the module it names WHEREVER that module is declared.
	// Exempting other files -- correct only while the qualifier's meaning was
	// read from this file alone -- meant a cross-file `A.convert` never narrowed
	// anything, so `B.convert` stayed a candidate and the ambiguity dropped the
	// edge.
	return fsharpNarrowToModule(symbols, pathBySymbolID, func(path string) bool {
		return fsharpQualifierMatchesModulePath(path, qualifier)
	})
}

// fsharpNarrowToModule keeps the candidates an F# module qualifier admits.
// The qualifier has already been checked against the project's declared F#
// modules before this helper runs. It therefore names that F# module, not an
// arbitrary same-named symbol from another language. If the module lacks the
// terminal member, the call is unresolved; falling back to a Python or other
// pathless homonym fabricates an edge the source never named.
func fsharpNarrowToModule(symbols []SymbolRecord, pathBySymbolID map[string]string, admits func(path string) bool) 
[]SymbolRecord {
	scoped := make([]SymbolRecord, 0, len(symbols))
	for _, symbol := range symbols {
		path, known := pathBySymbolID[symbol.ID]
		if known && admits(path) {
			scoped = append(scoped, symbol)
		}
	}
	return scoped
}

// fsharpModuleInitBlock returns an F# module's own source with every binding
// nested under it blanked out, so what is left is the module's
// initialisation code.
//
// A `module` block spans every binding declared under it, so a scan of the
// module's whole text sees the pipelines and calls written inside its
// FUNCTIONS; crediting the module too produced a second edge from a symbol
// that never made the call -- `B.run |> helper` appeared as both
// `run -> helper` and `B -> helper`. Withdrawing every module-attributed call
// cured that but also dropped the calls the module really does make: a
// statement-position expression or a `do` binding runs when the module
// initialises, belongs to no nested symbol, and cannot be recovered by the
// file-level pass, which masks the module's whole line range. Blanking the
// nested symbols separates the two: the members' bodies -- and their
// definition heads, which read as calls to the generic scanner -- go, the
// module's own statements stay.
//
// Only symbols strictly inside the module are blanked: an enclosing module
// spans this one entirely and would blank all of it, and a symbol sharing the
// module's exact range would do the same.
//
// Line numbering is preserved (nested lines become empty, they are not
// removed) so the block stays comparable to the unmasked one.
func fsharpModuleInitBlock(lines []string, symbol SymbolRecord, fileSymbols []SymbolRecord) string {
	start := maxInt(1, symbol.StartLine)
	if start > len(lines) {
		return ""
	}
	end := maxInt(start, symbol.EndLine)
	if end > len(lines) {
		end = len(lines)
	}
	own := append([]string(nil), lines[start-1:end]...)
	for _, other := range fileSymbols {
		if other.ID == symbol.ID {
			continue
		}
		otherStart := maxInt(1, other.StartLine)
		otherEnd := maxInt(otherStart, other.EndLine)
		if otherStart < start || otherEnd > end || (otherStart == start && otherEnd == end) {
			continue
		}
		for i := otherStart; i <= otherEnd; i++ {
			own[i-start] = ""
		}
	}
	return strings.Join(own, "
")
}

// resolveJuliaSameContainerMethodCallTargets is a conservative fallback for
// module-scoped Julia definitions, which the parser represents as methods.
// found distinguishes "no module candidate" from ambiguous overloads, while
// blocked prevents a shadowed name from falling through to an external edge.
func resolveJuliaSameContainerMethodCallTargets(name string, from SymbolRecord, sameFile []SymbolRecord, localBindings 
map[string]struct{}) (targets []resolvedCallTarget, found, blocked bool) {
	if from.Language != "Julia" || from.Kind != "method" || from.Local || from.ContainerID == "" {
		return nil, false, false
	}
	if localBindings == nil {
		return nil, false, false
	}
	parameters := symbolFlowParameterNames(from)
	if !from.parameterNamesKnown {
		// A short-form signature includes its RHS; stop at the first balanced
		// argument list so calls on the RHS are not mistaken for parameters.
		if open := strings.Index(from.Signature, "("); open >= 0 {
			if close := matchingParen(from.Signature, open); close > open {
				parameters = parameterNames(from.Signature[:close+1])
			}
		}
	}
	if parameters[name] {
		return nil, true, true
	}
	if _, shadowed := localBindings[name]; shadowed {
		// Decline only this additive Julia-method fallback. Existing generic
		// targets and external resolution must retain their pre-PR behavior.
		return nil, false, false
	}
	hasNestedCallable := false
	for _, to := range sameFile {
		if to.ID != from.ID && to.FilePath == from.FilePath && to.Local && callableTargetKind(to.Kind) &&
			from.StartLine <= to.StartLine && to.EndLine <= from.EndLine {
			hasNestedCallable = true
		}
		if to.ID == from.ID || to.FilePath != from.FilePath || to.Language != from.Language || to.Name != name ||
			to.Kind != "method" || to.ContainerID != from.ContainerID || !localReachable(from, to) {
			continue
		}
		found = true
		if to.Local {
			return nil, true, true
		}
		targets = append(targets, resolvedCallTarget{
			SymbolRecord: to,
			Confidence:   0.92,
			Reason:       "direct Julia call expression resolved to same-container symbol",
			Resolution:   "exact",
			Scope:        "file",
		})
	}
	if hasNestedCallable {
		return nil, false, false
	}
	if len(targets) != 1 {
		return nil, found, false
	}
	return targets, true, false
}

func resolveCallTargets(name string, from SymbolRecord, candidates, sameFile []SymbolRecord, importsByName 
map[string][]string, allowMethodTargets bool) []resolvedCallTarget {
	return resolveCallTargetsWithRawImport(name, from, candidates, nil, nil, sameFile, importsByName, allowMethodTargets)
}

type pythonCallImportInputs struct {
	rawCandidates       []SymbolRecord
	rawImportModuleSets [][]string
	imports             map[string][]string
	genericAllowed      bool
}

func pythonCallImportBinding(name string, from SymbolRecord, language string, scopes *pythonBareImportScopes, 
symbolsByShortName map[string][]SymbolRecord, importsByName map[string][]string, importingPath string, manifestImports 
manifestImportResolver, knownFiles map[string]bool, readContent contentReader) pythonCallImportInputs {
	inputs := pythonCallImportInputs{rawCandidates: symbolsByShortName[name], imports: importsByName, genericAllowed: 
true}
	if modules := importsByName[name]; len(modules) > 0 {
		inputs.rawImportModuleSets = [][]string{modules}
	}
	if language != "Python" {
		return inputs
	}
	if scopes != nil && scopes.complete {
		inputs.rawImportModuleSets = scopes.genericImportModuleSets(from, name)
		inputs.imports = importsWithName(importsByName, name, scopes.genericImportModules(from, name), importingPath, 
manifestImports, knownFiles, readContent)
		inputs.genericAllowed = scopes.genericCallAllowed(from, name)
	} else {
		// An incomplete or unavailable AST cannot license raw cross-language
		// widening. Keep the ordinary import map for filtered resolution.
		inputs.rawCandidates = nil
		inputs.rawImportModuleSets = nil
	}
	if len(inputs.rawImportModuleSets) == 0 {
		inputs.rawCandidates = nil
	}
	return inputs
}

// importsWithName replaces one binding in the normal import map with the
// modules visible at a particular Python call site. The normal map contains
// tagged repository-local paths beside authored specifiers; rebuild those tags
// for the selected scope bindings so ordinary same-language import resolution
// retains its exact-file match without restoring hidden/rebound imports.
func importsWithName(imports map[string][]string, name string, modules []string, importingPath string, manifestImports 
manifestImportResolver, knownFiles map[string]bool, readContent contentReader) map[string][]string {
	copy := make(map[string][]string, len(imports))
	for key, value := range imports {
		copy[key] = value
	}
	if len(modules) == 0 {
		delete(copy, name)
	} else {
		resolved := append([]string(nil), modules...)
		for _, module := range modules {
			if path, ok := resolveImportSpecPath(importingPath, module, manifestImports, knownFiles, readContent); ok && path 
!= "" {
				resolved = append(resolved, resolvedImportPathPrefix+path)
			}
		}
		copy[name] = uniqueStrings(resolved)
	}
	return copy
}

// resolvePythonAliasImportTargets keeps an AST-visible `from module import
// member as local` binding tied to its original member name. Module-only
// aliases intentionally return handled without a target: a module object is
// not a bare callable and must not fall through to a same-spelled workspace
// symbol or an invented `module.local` external edge.
func resolvePythonAliasImportTargets(local string, from SymbolRecord, contexts []pythonImportContext, 
symbolsByShortName map[string][]SymbolRecord, importingPath string, manifestImports manifestImportResolver, knownFiles 
map[string]bool, readContent contentReader) (targets []resolvedCallTarget, external []RelationRecord, handled bool) {
	seen := map[string]bool{}
	for _, context := range contexts {
		if context.member == "" {
			handled = true
			continue
		}
		if context.member == local {
			continue
		}
		handled = true
		imports := importsWithName(nil, context.member, context.modules, importingPath, manifestImports, knownFiles, 
readContent)
		candidates := sharedTypeCandidates(from, symbolsByShortName[context.member])
		resolved := resolveImportedCallTargets(context.member, from, candidates, imports, false)
		if len(resolved) == 0 {
			resolved, _ = resolveUniqueRawImportedCallTarget(context.member, from, symbolsByShortName[context.member], 
[][]string{imports[context.member]}, false)
		}
		if len(resolved) == 0 {
			external = append(external, importedExternalCallRelationsForName(from, context.member, context.modules)...)
			continue
		}
		for _, target := range resolved {
			if !seen[target.ID] {
				seen[target.ID] = true
				targets = append(targets, target)
			}
		}
	}
	return targets, external, handled
}

// pythonIncompleteAliasContexts is deliberately a fallback for malformed or
// depth-limited ASTs only. It preserves the original imported member for an
// external relation, but is never used to recover a local target: incomplete
// scope analysis must remain fail-closed for local resolution.
func pythonIncompleteAliasContexts(bindings map[string][]pythonImportBinding) map[string][]pythonImportContext {
	contexts := map[string][]pythonImportContext{}
	for local, entries := range bindings {
		for _, binding := range entries {
			if binding.Imported == local {
				continue // ordinary `from module import local` keeps normal fallback
			}
			module := binding.Module
			if binding.Imported != "" {
				module = pythonFromImportModuleSpec(module, binding.Imported)
			}
			contexts[local] = appendPythonImportContext(contexts[local], pythonImportContext{modules: []string{module}, member: 
binding.Imported})
		}
	}
	return contexts
}

func pythonAliasExternalCallRelations(from SymbolRecord, contexts []pythonImportContext) []RelationRecord {
	var relations []RelationRecord
	for _, context := range contexts {
		if context.member != "" {
			relations = append(relations, importedExternalCallRelationsForName(from, context.member, context.modules)...)
		}
	}
	return relations
}

func unionResolvedCallTargets(groups ...[]resolvedCallTarget) []resolvedCallTarget {
	seen := map[string]bool{}
	var targets []resolvedCallTarget
	for _, group := range groups {
		for _, target := range group {
			if !seen[target.ID] {
				seen[target.ID] = true
				targets = append(targets, target)
			}
		}
	}
	return targets
}

// resolveCallTargetsWithRawImport keeps the normal language-filtered candidate
// set for every ordinary resolution tier. A bare imported call may additionally
// retain the raw workspace candidates so an explicit, unique import path can
// bind a local FFI target that the type-sharing policy deliberately excludes.
func resolveCallTargetsWithRawImport(name string, from SymbolRecord, candidates, rawCandidates []SymbolRecord, 
rawImportModuleSets [][]string, sameFile []SymbolRecord, importsByName map[string][]string, allowMethodTargets bool) 
[]resolvedCallTarget {
	// candidates arrive ALREADY filtered to languages the caller can name: every
	// call site wraps its symbolsByShortName lookup in sharedTypeCandidates,
	// because that is where the referring symbol is known. Re-filtering here
	// would be a second application of an idempotent function and, worse, would
	// look like the guard when the call sites are the guard.
	var local []resolvedCallTarget
	for _, to := range sameFile {
		// A bare `name()` call resolves to a function, not a class method (methods
		// require a receiver and are resolved by receiverCallRelations) — matching
		// a same-named method here is a false edge.
		if to.ID == from.ID || to.Name != name || !callableTargetKind(to.Kind) || (to.Kind == "method" && 
!nameCallMayTargetMethod(from.Language) && !allowMethodTargets) || !localReachable(from, to) {
			continue
		}
		local = append(local, resolvedCallTarget{
			SymbolRecord: to,
			Confidence:   0.92,
			Reason:       "direct call expression resolved to same-file symbol",
			Resolution:   "exact",
			Scope:        "file",
		})
	}
	if len(local) == 1 {
		return appendSQLDerivedDuplicateTargets(local, from, candidates)
	}
	if len(local) > 1 {
		// Ambiguous bare name with multiple same-file definitions: emit the
		// lexically nearest one (closest declaration line to the call site) rather
		// than fanning out an edge to every candidate. A single best guess keeps
		// recall while cutting the over-emission that dominates the false edges.
		best := local[0]
		for _, c := range local[1:] {
			if absInt(c.StartLine-from.StartLine) < absInt(best.StartLine-from.StartLine) {
				best = c
			}
		}
		return []resolvedCallTarget{best}
	}

	if imported := resolveImportedCallTargets(name, from, candidates, importsByName, allowMethodTargets); len(imported) > 
0 {
		return imported
	}
	if rawCandidates != nil {
		if imported, bound := resolveUniqueRawImportedCallTarget(name, from, rawCandidates, rawImportModuleSets, 
allowMethodTargets); bound {
			return imported
		}
	}

	// Same-package resolution: in Go every file in a directory is the same
	// package, so a bare call resolves within that package even when the name is
	// not globally unique. Strict uniqueness-within-directory for functions and
	// type-like symbols keeps this high-precision while recovering cross-file
	// same-package calls and constructions that the globally-unique gate below
	// would otherwise drop.
	if from.Language == "Go" {
		fromDir := filepath.ToSlash(filepath.Dir(from.FilePath))
		var samePkg []SymbolRecord
		for _, to := range candidates {
			if to.ID == from.ID || (to.Kind != "function" && !typeLikeKind(to.Kind)) || !localReachable(from, to) {
				continue
			}
			if filepath.ToSlash(filepath.Dir(to.FilePath)) == fromDir {
				samePkg = append(samePkg, to)
			}
		}
		if len(samePkg) == 1 {
			return []resolvedCallTarget{{
				SymbolRecord: samePkg[0],
				Confidence:   0.80,
				Reason:       "direct call expression resolved to same-package symbol",
				Resolution:   "package",
				Scope:        "module",
			}}
		}
	}

	// Same-directory resolution for Dart: a Dart file imports siblings by bare
	// relative path (`import 'request.dart';`) without binding a local name, so
	// the import-map branch above can never disambiguate. A unique function or
	// type (constructor call) in the caller's directory wins over the
	// globally-unique gate below, which drops the call whenever another package
	// in a monorepo reuses the name (e.g. two `Request` classes in dart-lang/http).
	// Methods stay excluded: a Dart class is single-file, so an implicit-receiver
	// method call is already resolved by the same-file branch.
	if from.Language == "Dart" {
		fromDir := filepath.ToSlash(filepath.Dir(from.FilePath))
		var sameDir []SymbolRecord
		for _, to := range candidates {
			if to.ID == from.ID || (to.Kind != "function" && !typeLikeKind(to.Kind)) || !localReachable(from, to) {
				continue
			}
			if filepath.ToSlash(filepath.Dir(to.FilePath)) == fromDir {
				sameDir = append(sameDir, to)
			}
		}
		if len(sameDir) == 1 {
			return []resolvedCallTarget{{
				SymbolRecord: sameDir[0],
				Confidence:   0.80,
				Reason:       "direct call expression resolved to same-directory symbol",
				Resolution:   "package",
				Scope:        "module",
			}}
		}
	}

	var remaining []SymbolRecord
	for _, to := range candidates {
		if to.ID != from.ID && callableTargetKind(to.Kind) && (to.Kind != "method" || nameCallMayTargetMethod(from.Language) 
|| allowMethodTargets) && localReachable(from, to) {
			remaining = append(remaining, to)
		}
	}
	if len(remaining) == 1 {
		return []resolvedCallTarget{{
			SymbolRecord: remaining[0],
			Confidence:   0.68,
			Reason:       "direct call expression matched globally unique symbol name",
			Resolution:   "name_only",
			Scope:        "workspace",
		}}
	}
	if from.Language == "PHP" && len(remaining) > 1 {
		// PHP repos commonly re-declare bare functions (WordPress ships
		// apply_filters in plugin.php plus compat/noop stubs), and PHP has
		// no import statements for functions to disambiguate through.
		// Ambiguity must not mean silence: emit candidate edges to the
		// same-name declarations, largest declaration first (the canonical
		// implementation dwarfs its stubs), capped to keep noise bounded.
		ranked := append([]SymbolRecord(nil), remaining...)
		sort.SliceStable(ranked, func(i, j int) bool {
			return ranked[i].EndLine-ranked[i].StartLine > ranked[j].EndLine-ranked[j].StartLine
		})
		if len(ranked) > 4 {
			ranked = ranked[:4]
		}
		out := make([]resolvedCallTarget, 0, len(ranked))
		for _, cand := range ranked {
			out = append(out, resolvedCallTarget{
				SymbolRecord: cand,
				Confidence:   0.55,
				Reason:       fmt.Sprintf("ambiguous bare call: candidate among %d same-name declarations", len(remaining)),
				Resolution:   "name_only",
				Scope:        "workspace",
			})
		}
		return out
	}
	if cFamilyOverloadResolutionEnabled(from.Language) {
		if overloads, ok := sameFileOverloadSet(remaining); ok {
			out := make([]resolvedCallTarget, 0, len(overloads))
			for _, overload := range overloads {
				out = append(out, resolvedCallTarget{
					SymbolRecord: overload,
					Confidence:   0.62,
					Reason:       "direct call expression matched C/C++ overload set in one file",
					Resolution:   "name_only",
					Scope:        "workspace",
				})
			}
			return out
		}
	}
	return nil
}

// resolveUniqueRawImportedCallTarget is the narrow FFI exception to the
// language-filtered short-name index. The imported binding is authoritative
// only when its module path names exactly one callable workspace target. A
// missing or ambiguous raw match blocks same-package/global-name fallback for
// this imported name, leaving the ordinary external edge in place instead of
// guessing from an unrelated declaration with the same spelling.
func resolveUniqueRawImportedCallTarget(name string, from SymbolRecord, candidates []SymbolRecord, moduleSets 
[][]string, allowMethodTargets bool) ([]resolvedCallTarget, bool) {
	if len(moduleSets) == 0 {
		return nil, false
	}
	seen := map[string]bool{}
	var targets []resolvedCallTarget
	bound := false
	for _, modules := range moduleSets {
		var matched []SymbolRecord
		for _, to := range candidates {
			if to.ID == from.ID || to.Name != name || !callableTargetKind(to.Kind) || (to.Kind == "method" && 
!nameCallMayTargetMethod(from.Language) && !allowMethodTargets) || !localReachable(from, to) {
				continue
			}
			if importedNameMatchesFile(modules, from.FilePath, to.FilePath) {
				matched = append(matched, to)
			}
		}
		bound = true
		if len(matched) == 1 && !seen[matched[0].ID] {
			seen[matched[0].ID] = true
			targets = append(targets, resolvedCallTarget{
				SymbolRecord: matched[0],
				Confidence:   0.84,
				Reason:       "direct call expression resolved through imported module path",
				Resolution:   "import_resolved",
				Scope:        "module",
			})
		}
	}
	return targets, bound
}

// resolveJSNamespaceCallTargets resolves a namespace-qualified call against
// same-file namespace members. The second result reports whether any member
// matched at all: a false lets the caller fall back to generic terminal-name
// resolution for namespaces merged across files, while an ambiguous multi-match
// (true, nil) stays unresolved rather than guessing.
func resolveJSNamespaceCallTargets(qualifiedName string, from SymbolRecord, sameFile []SymbolRecord, 
namespacesBySymbolID map[string]string) ([]resolvedCallTarget, bool) {
	separator := strings.LastIndex(qualifiedName, ".")
	if separator <= 0 || separator == len(qualifiedName)-1 {
		return nil, false
	}
	namespace := qualifiedName[:separator]
	name := qualifiedName[separator+1:]
	var matches []resolvedCallTarget
	for _, to := range sameFile {
		if to.ID == from.ID || to.Name != name || !callableTargetKind(to.Kind) || !localReachable(from, to) {
			continue
		}
		// A class method declared inside the namespace's source range is not a
		// namespace-level callable. If a future parser version qualifies namespace
		// members as methods, its qualified name still makes that case exact.
		if to.Kind == "method" && to.QualifiedName != qualifiedName {
			continue
		}
		if namespacesBySymbolID[to.ID] != namespace {
			continue
		}
		matches = append(matches, resolvedCallTarget{
			SymbolRecord: to,
			Confidence:   0.92,
			Reason:       "namespace-qualified call resolved to same-file declaration",
			Resolution:   "exact",
			Scope:        "file",
		})
	}
	if len(matches) == 1 {
		return matches, true
	}
	return nil, len(matches) > 0
}

// resolveJSMergedDeclarationMemberTargets handles the namespace-call fallback
// when the receiver path also names a same-file class/enum/object declaration
// (TypeScript declaration merging, `class A { static create() {} }` next to
// `namespace A { ... }`): the call resolves against the merged declaration's
// members. The second result reports whether a member actually matched (an
// ambiguous multi-match counts: it stays unresolved rather than guessing);
// the third reports whether the receiver names such a merged declaration at
// all, which the terminal-name fallback uses to stay confined to the
// receiver's namespace instead of resolving the bare name workspace-wide.
func resolveJSMergedDeclarationMemberTargets(qualifiedName string, from SymbolRecord, sameFile []SymbolRecord, 
namespacesBySymbolID map[string]string) ([]resolvedCallTarget, bool, bool) {
	separator := strings.LastIndex(qualifiedName, ".")
	if separator <= 0 || separator == len(qualifiedName)-1 {
		return nil, false, false
	}
	receiver := qualifiedName[:separator]
	member := qualifiedName[separator+1:]
	mergedContainers := map[string]bool{}
	for _, symbol := range sameFile {
		if !jsMergeableValueDeclarationKind(symbol.Kind) {
			continue
		}
		qualified := symbol.Name
		if namespace := namespacesBySymbolID[symbol.ID]; namespace != "" {
			qualified = namespace + "." + symbol.Name
		}
		if qualified == receiver {
			mergedContainers[symbol.ID] = true
		}
	}
	if len(mergedContainers) == 0 {
		return nil, false, false
	}
	var matches []resolvedCallTarget
	for _, to := range sameFile {
		if to.ID == from.ID || to.Name != member || !mergedContainers[to.ContainerID] || !localReachable(from, to) {
			continue
		}
		if to.Kind != "method" && to.Kind != "function" {
			continue
		}
		matches = append(matches, resolvedCallTarget{
			SymbolRecord: to,
			Confidence:   0.9,
			Reason:       "namespace-qualified call resolved to merged same-file declaration member",
			Resolution:   "exact",
			Scope:        "file",
		})
	}
	if len(matches) == 1 {
		return matches, true, true
	}
	return nil, len(matches) > 0, true
}

// resolveJSNamespaceCallChain resolves one canonical namespace-qualified call
// (an entry of jsNamespaceCalls) through the chain shared by the per-symbol
// and top-level call paths:
//
//  1. same-file namespace members (resolveJSNamespaceCallTargets);
//  2. members of a same-file value declaration merged with the receiver
//     (resolveJSMergedDeclarationMemberTargets);
//  3. namespace-confined fallback for namespaces reopened in other files —
//     declaration merging leaves no same-file member to match.
//
// Step 3 always stays confined to symbols that actually sit in a namespace
// matching the receiver path in their own file (foreignNamespaceOf). This
// function is called only for entries recognized as namespace calls, so
// dropping the receiver and resolving a globally unique bare terminal would
// fabricate an edge to an unrelated declaration.
// skipTerminal, when non-nil, suppresses step 3 for terminals the call site
// already excludes from bare-name resolution (self-calls, member names).
func resolveJSNamespaceCallChain(name string, from SymbolRecord, sameFile []SymbolRecord, namespacesBySymbolID 
map[string]string, symbolsByShortName map[string][]SymbolRecord, foreignNamespaceOf func(SymbolRecord) string, 
skipTerminal func(string) bool) []resolvedCallTarget {
	targets, matched := resolveJSNamespaceCallTargets(name, from, sameFile, namespacesBySymbolID)
	if matched {
		return targets
	}
	targets, matched, _ = resolveJSMergedDeclarationMemberTargets(name, from, sameFile, namespacesBySymbolID)
	if matched {
		return targets
	}
	terminal := name[strings.LastIndex(name, ".")+1:]
	if skipTerminal != nil && skipTerminal(terminal) {
		return nil
	}
	receiver := name[:strings.LastIndex(name, ".")]
	var related []resolvedCallTarget
	for _, to := range sharedTypeCandidates(from, symbolsByShortName[terminal]) {
		if to.ID == from.ID || to.FilePath == from.FilePath || !callableTargetKind(to.Kind) || to.Kind == "method" || 
!localReachable(from, to) {
			continue
		}
		if foreignNamespaceOf == nil || foreignNamespaceOf(to) != receiver {
			continue
		}
		related = append(related, resolvedCallTarget{
			SymbolRecord: to,
			Confidence:   0.8,
			Reason:       "namespace-qualified call resolved to namespace member reopened in another file",
			Resolution:   "name_only",
			Scope:        "workspace",
		})
	}
	if len(related) == 1 {
		return related
	}
	return nil
}

// jsCrossFileNamespaceLookup returns a lazy, memoizing lookup of the
// canonical namespace path lexically containing a JS/TS symbol in its own
// file. The merged-declaration terminal fallback uses it to verify that a
// cross-file candidate actually reopens the receiver's namespace before
// emitting an edge. Files without namespaces — or whose scope parse fails —
// yield "" for every symbol; each file is read and scanned at most once.
func jsCrossFileNamespaceLookup(readContent contentReader, recordsByFile map[string][]SymbolRecord) func(SymbolRecord) 
string {
	// The relation phase resolves files across workers, so the memo is shared.
	// The lock is held across the scan rather than only across the map access:
	// this fires for TypeScript namespaces alone, which is rare enough that
	// serializing it costs less than letting two workers scan the same file.
	var mu sync.Mutex
	cache := map[string]map[string]string{}
	return func(symbol SymbolRecord) string {
		if symbol.Language != "JavaScript" && symbol.Language != "TypeScript" {
			return ""
		}
		mu.Lock()
		defer mu.Unlock()
		byID, ok := cache[symbol.FilePath]
		if !ok {
			if content, okRead := readContent(symbol.FilePath); okRead {
				if scan, err := newJSScanState(symbol.FilePath, content); err == nil && len(scan.namespaces) > 0 {
					byID = jsNamespaceBySymbolID(content, recordsByFile[symbol.FilePath], scan.namespaces)
				}
			}
			cache[symbol.FilePath] = byID
		}
		return byID[symbol.ID]
	}
}

// jsMergeableValueDeclarationKind reports the symbol kinds that can merge
// with a TypeScript namespace of the same name and carry callable members.
func jsMergeableValueDeclarationKind(kind string) bool {
	return kind == "class" || kind == "enum" || kind == "object"
}

func resolveImportedCallTargets(name string, from SymbolRecord, candidates []SymbolRecord, importsByName 
map[string][]string, allowMethodTargets bool) []resolvedCallTarget {
	var imported []resolvedCallTarget
	for _, to := range candidates {
		if to.ID == from.ID || !callableTargetKind(to.Kind) || (to.Kind == "method" && 
!nameCallMayTargetMethod(from.Language) && !allowMethodTargets) || !localReachable(from, to) {
			continue
		}
		if importedNameMatchesFile(importsByName[name], from.FilePath, to.FilePath) {
			imported = append(imported, resolvedCallTarget{
				SymbolRecord: to,
				Confidence:   0.86,
				Reason:       "direct call expression resolved through import path",
				Resolution:   "import_resolved",
				Scope:        "module",
			})
		}
	}
	if len(imported) == 0 {
		imported = jsExportedImportFallbackTargets(name, from, candidates, importsByName[name], allowMethodTargets)
	}
	if len(imported) > 1 {
		// An overload set is not ambiguity. `import { renderList }` followed by
		// `renderList(...)` has exactly one call target — the implementation —
		// even though the file also declares bodyless signatures for it. Without
		// this the fanout below downgrades every candidate to "name_only", which
		// the fast profile then discards wholesale (shallowCallRelationRetained),
		// so `impact` reports a function with real callers as having none.
		if implementation, ok := bodylessOverloadImplementation(imported); ok {
			return []resolvedCallTarget{implementation}
		}
	}
	if len(imported) > 1 {
		for index := range imported {
			imported[index].Confidence = minFloat(imported[index].Confidence, 0.62)
			imported[index].Reason = fmt.Sprintf("ambiguous imported call: candidate among %d same-name declarations", 
len(imported))
			// Fast-profile shallow resolution retains only single-target
			// import_resolved edges. Keep the candidates in full snapshots,
			// but classify this fanout with the existing broad-resolution value
			// so it cannot inflate caller-degree ranking in fast search graphs.
			imported[index].Resolution = "name_only"
		}
	}
	return imported
}

func jsExportedImportFallbackTargets(name string, from SymbolRecord, candidates []SymbolRecord, modules []string, 
allowMethodTargets bool) []resolvedCallTarget {
	if len(modules) == 0 || (from.Language != "JavaScript" && from.Language != "TypeScript") {
		return nil
	}
	var exported []SymbolRecord
	var imported []SymbolRecord
	for _, to := range candidates {
		if to.ID == from.ID || !callableTargetKind(to.Kind) || (to.Kind == "method" && 
!nameCallMayTargetMethod(from.Language) && !allowMethodTargets) || !localReachable(from, to) {
			continue
		}
		if importedNameMatchesFile(modules, from.FilePath, to.FilePath) {
			imported = append(imported, to)
		}
		if jsExportedSymbol(name, to) {
			exported = append(exported, to)
		}
	}
	if len(exported) != 1 {
		exported = preferExportedSymbols(name, imported)
		if len(exported) != 1 {
			return nil
		}
	}
	return []resolvedCallTarget{{
		SymbolRecord: exported[0],
		Confidence:   0.64,
		Reason:       "JS/TS imported name matched unique exported workspace symbol",
		Resolution:   "import_resolved",
		Scope:        "module",
	}}
}

func preferExportedSymbols(name string, candidates []SymbolRecord) []SymbolRecord {
	var exported []SymbolRecord
	for _, candidate := range candidates {
		if jsExportedSymbol(name, candidate) {
			exported = append(exported, candidate)
		}
	}
	if len(exported) == 1 {
		return exported
	}
	if len(candidates) == 1 {
		return candidates
	}
	return nil
}

func jsExportedSymbol(name string, symbol SymbolRecord) bool {
	signature := strings.TrimSpace(symbol.Signature)
	for _, prefix := range []string{
		"export function " + name,
		"export async function " + name,
		"export const " + name,
		"export let " + name,
		"export var " + name,
		"export class " + name,
	} {
		if strings.HasPrefix(signature, prefix) {
			return true
		}
	}
	return false
}

func appendSQLDerivedDuplicateTargets(targets []resolvedCallTarget, from SymbolRecord, candidates []SymbolRecord) 
[]resolvedCallTarget {
	if from.Language != "SQL" || len(targets) == 0 {
		return targets
	}
	seen := map[string]bool{}
	for _, target := range targets {
		seen[target.ID] = true
	}
	var extras []resolvedCallTarget
	for _, target := range targets {
		if !sqlDerivedScriptPath(target.FilePath) {
			continue
		}
		for _, candidate := range candidates {
			if candidate.ID == from.ID || seen[candidate.ID] || candidate.QualifiedName != target.QualifiedName || 
candidate.Kind != target.Kind || sqlDerivedScriptPath(candidate.FilePath) || !localReachable(from, candidate) {
				continue
			}
			seen[candidate.ID] = true
			extras = append(extras, resolvedCallTarget{
				SymbolRecord: candidate,
				Confidence:   0.54,
				Reason:       "SQL migration-script call also linked to canonical same-qualified routine",
				Resolution:   "name_only",
				Scope:        "workspace",
			})
		}
	}
	if len(extras) == 0 {
		return targets
	}
	out := append([]resolvedCallTarget(nil), targets...)
	out = append(out, extras...)
	return out
}

func sqlDerivedScriptPath(path string) bool {
	path = strings.ToLower(filepath.ToSlash(path))
	base := filepath.Base(path)
	if strings.Contains(base, "--") {
		return true
	}
	for _, part := range strings.Split(path, "/") {
		switch part {
		case "migration", "migrations", "update", "updates", "upgrade", "upgrades", "downgrade", "downgrades":
			return true
		}
	}
	return false
}

func cFamilyOverloadResolutionEnabled(language string) bool {
	return language == "C" || language == "C++"
}

// bodylessOverloadImplementation collapses a multi-candidate call fanout that
// is really ONE overloaded function: several bodyless declarations (TypeScript
// overload signatures / ambients) plus the single implementation they belong
// to, all in the same file under the same qualified name. It returns that
// implementation, so the call keeps the confidence and reason it resolved with
// instead of being downgraded as ambiguous.
//
// It refuses whenever the set could be genuine ambiguity: two real definitions
// of the name, candidates spread across files or qualified names, or a set with
// no implementation at all (a pure ambient declaration file, where nothing says
// which declaration the call runs).
func bodylessOverloadImplementation(targets []resolvedCallTarget) (resolvedCallTarget, bool) {
	if len(targets) < 2 {
		return resolvedCallTarget{}, false
	}
	first := targets[0].SymbolRecord
	if first.FilePath == "" || first.QualifiedName == "" {
		return resolvedCallTarget{}, false
	}
	implementation := -1
	for index, target := range targets {
		if target.FilePath != first.FilePath || target.Language != first.Language ||
			target.QualifiedName != first.QualifiedName || target.Kind != first.Kind {
			return resolvedCallTarget{}, false
		}
		if target.bodyless {
			continue
		}
		if implementation >= 0 {
			return resolvedCallTarget{}, false
		}
		implementation = index
	}
	if implementation < 0 {
		return resolvedCallTarget{}, false
	}
	return targets[implementation], true
}

func sameFileOverloadSet(candidates []SymbolRecord) ([]SymbolRecord, bool) {
	if len(candidates) < 2 {
		return nil, false
	}
	filePath := candidates[0].FilePath
	language := candidates[0].Language
	name := candidates[0].Name
	if filePath == "" || name == "" {
		return nil, false
	}
	for _, candidate := range candidates {
		if candidate.FilePath != filePath || candidate.Language != language || candidate.Name != name {
			return nil, false
		}
	}
	return candidates, true
}

// buildRelations collects every relation, deduplicates (first occurrence wins,
// in emission order), and sorts for stable output. Used by the in-memory
// snapshot path; the streaming path uses forEachRelation directly.
func buildRelations(repoKey string, files []FileRecord, recordsByFile map[string][]SymbolRecord, readContent 
contentReader) []RelationRecord {
	var relations []RelationRecord
	forEachRelation(context.Background(), repoKey, files, recordsByFile, readContent, nil, resolveProfile(ProfileFull), 
defaultProviderWorkerCount(), nil, func(r RelationRecord) {
		relations = append(relations, r)
	}, nil)
	relations = dedupeRelations(relations)
	sort.Slice(relations, func(i, j int) bool {
		left := relations[i].Type + relations[i].FromID + relations[i].ToID
		right := relations[j].Type + relations[j].FromID + relations[j].ToID
		return left < right
	})
	return relations
}

type structuralSymbol struct {
	ID          string
	FilePath    string
	ContainerID string
}

func compactStructuralSymbols(records []SymbolRecord) []structuralSymbol {
	out := make([]structuralSymbol, 0, len(records))
	for _, record := range records {
		out = append(out, structuralSymbol{
			ID:          record.ID,
			FilePath:    record.FilePath,
			ContainerID: record.ContainerID,
		})
	}
	return out
}

func retainedSymbolsForProfile(records []SymbolRecord, spec profileSpec) []SymbolRecord {
	if spec.name == ProfileFull {
		return records
	}
	out := make([]SymbolRecord, 0, len(records))
	for _, record := range records {
		record.StableIDVersion = ""
		record.Signature = ""
		record.BodyHash = ""
		out = append(out, record)
	}
	return out
}

func emitStructuralRelations(repoKey string, files []FileRecord, recordsByFile map[string][]SymbolRecord, emit 
func(RelationRecord)) {
	for _, file := range files {
		for _, symbol := range recordsByFile[file.Path] {
			emit(RelationRecord{
				RecordType:    "relation",
				FromID:        fileID(repoKey, symbol.FilePath),
				ToID:          symbol.ID,
				Type:          "DEFINES",
				Confidence:    1,
				Reason:        "symbol parsed from file",
				RelationScope: "file",
				Resolution:    "exact",
				TargetKind:    "symbol",
				WarningCodes:  []string{},
			})
			if symbol.ContainerID != "" {
				emit(RelationRecord{
					RecordType:    "relation",
					FromID:        symbol.ContainerID,
					ToID:          symbol.ID,
					Type:          "CONTAINS",
					Confidence:    1,
					Reason:        "symbol qualified name is nested in container",
					RelationScope: "file",
					Resolution:    "exact",
					TargetKind:    "symbol",
					WarningCodes:  []string{},
				})
			}
		}
	}
}

func emitStructuralRelationsCompact(repoKey string, files []FileRecord, recordsByFile map[string][]structuralSymbol, 
emit func(RelationRecord)) {
	for _, file := range files {
		for _, symbol := range recordsByFile[file.Path] {
			emit(RelationRecord{
				RecordType:    "relation",
				FromID:        fileID(repoKey, symbol.FilePath),
				ToID:          symbol.ID,
				Type:          "DEFINES",
				Confidence:    1,
				Reason:        "symbol parsed from file",
				RelationScope: "file",
				Resolution:    "exact",
				TargetKind:    "symbol",
				WarningCodes:  []string{},
			})
			if symbol.ContainerID != "" {
				emit(RelationRecord{
					RecordType:    "relation",
					FromID:        symbol.ContainerID,
					ToID:          symbol.ID,
					Type:          "CONTAINS",
					Confidence:    1,
					Reason:        "symbol qualified name is nested in container",
					RelationScope: "file",
					Resolution:    "exact",
					TargetKind:    "symbol",
					WarningCodes:  []string{},
				})
			}
		}
	}
}

// forEachRelation drives all relation extraction, passing each relation to emit
// as it is produced. It never accumulates the full relation set, so a streaming
// caller can write records out with bounded memory. Callers deduplicate:
// buildRelations collects-then-dedupes; the streaming path dedupes on emit.
// jsScanPartialFailure maps a relation-phase JS/TS scope-parse error to the
// partial-failure record the summary reports, mirroring the entity-phase
// codes (E_PARSE_TIMEOUT for a blown parse budget, E_PARSE_ERROR otherwise).
func jsScanPartialFailure(path string, err error) PartialFailure {
	code := "E_PARSE_ERROR"
	if errors.Is(err, context.DeadlineExceeded) {
		code = "E_PARSE_TIMEOUT"
	}
	return PartialFailure{
		Code:                 code,
		Severity:             "warning",
		FilePath:             path,
		EffectOnCompleteness: "relation-phase scope parse failed; namespace-qualified call classification skipped for this 
file",
		Detail:               err.Error(),
	}
}

// jsScanDepthPartialFailure reports a relation-phase scope walk truncated at
// maxParseWalkDepth. It reuses the entity phase's code so both phases describe
// the same condition identically, and it is a warning rather than an error for
// the same reason: the relations above the limit are emitted. Its effect and
// detail text stand on their own because mergePartialFailures folds them into the
// entity-phase record for the same file rather than discarding them.
func jsScanDepthPartialFailure(path string) PartialFailure {
	return PartialFailure{
		Code:                 "E_PARSE_DEPTH_EXCEEDED",
		Severity:             "warning",
		FilePath:             path,
		EffectOnCompleteness: "relation-phase scope walk truncated at the parser depth limit; calls nested deeper than that 
were not classified",
		Detail:               fmt.Sprintf("AST nesting exceeded the %d-level walk limit during relation construction", 
maxParseWalkDepth),
	}
}

// fileRelationScan is one file's share of the relation phase: what its scan
// accumulates for later cross-file passes, replayed by the reducer in file order.
//
// The three entry slices are the accumulator writes the scan used to make
// directly. They are kept as ordered entries rather than merged maps so the
// reducer reproduces the exact append order the sequential loop produced, which
// is what routeBridgeRelations and the OVERRIDES derivation read.
type fileRelationScan struct {
	failures        []PartialFailure
	resolvedImports map[string][]string
	routeHandlers   []routeHandlerEntry
	httpCalls       []httpCallEntry
	inheritance     []RelationRecord
}

type routeHandlerEntry struct {
	route   string
	handler SymbolRecord
}

type httpCallEntry struct {
	route    string
	relation RelationRecord
}

// errRelationScanStopped unwinds the pipeline when the consumer has errored or
// the context is done. It never reaches a caller: forEachRelation reports a stop
// by returning, exactly as the sequential loop did.
var errRelationScanStopped = errors.New("relation scan stopped")

func forEachRelation(ctx context.Context, repoKey string, files []FileRecord, recordsByFile map[string][]SymbolRecord, 
readContent contentReader, precomputedImports map[string][]string, spec profileSpec, workers int, shouldStop func() 
bool, emit func(RelationRecord), recordFailure func(PartialFailure)) {
	if spec.name == ProfileSyntaxOnly {
		emitStructuralRelations(repoKey, files, recordsByFile, emit)
		return
	}
	needsTool := spec.emits("HANDLES_TOOL")
	needsCallScan := spec.emits("CALLS") && spec.callResolution != "none"
	needsReceiverCalls := spec.emits("CALLS") && spec.callResolution == "full"
	needsFields := spec.emits("READS_FIELD") || spec.emits("WRITES_FIELD") || spec.emits("ACCESSES")
	needsTypes := spec.emits("EXTENDS") || spec.emits("INHERITS") || spec.emits("IMPLEMENTS") || spec.emits("OVERRIDES")
	needsOverrides := spec.emits("OVERRIDES")
	// C# extension methods and Kotlin extension functions/properties are members
	// of the type they extend for every purpose except where they are written.
	// The extra CONTAINS edge is what makes them answer "what can I do with an
	// Edit?". It resolves same-file first, so it still works at profiles that
	// build no cross-file type index.
	needsExtensionMembers := spec.emits("CONTAINS")
	needsAsyncCalls := spec.emits("ASYNC_CALLS")
	needsDataFlow := spec.emits("DATA_FLOWS")
	needsServiceRelations := spec.emits("HANDLES_GRPC") || spec.emits("HANDLES_GRAPHQL") || spec.emits("HANDLES_TRPC")
	// Shallow call resolution needs the global short-name index too: without
	// it, cross-file targets are invisible and shallow degenerates to
	// same-file calls only, leaving the fast profile with no caller edges for
	// graph-aware ranking. The emit-time shallowCallRelationRetained filter
	// still drops the low-precision resolutions the index makes reachable.
	needsSignatureTypeImports := spec.emits("USES_TYPE") || spec.emits("PARAM_TYPE") || spec.emits("RETURNS_TYPE") || 
spec.emits("TESTS")
	needsGlobalSymbolsByShortName := spec.callResolution == "full" || spec.callResolution == "shallow" ||
		needsReceiverCalls || needsFields || needsTypes || needsOverrides || needsAsyncCalls ||
		needsDataFlow || needsSignatureTypeImports
	needsGlobalSymbolsByFile := needsGlobalSymbolsByShortName
	symbolsByShortName := map[string][]SymbolRecord{}
	symbolsByFile := map[string][]SymbolRecord{}
	childNamesByContainer := map[string]map[string]bool{}
	methodsByContainer := map[string]map[string]SymbolRecord{}
	fieldsByContainer := map[string]map[string]SymbolRecord{}
	returnTypesBySymbolNameAndFile := map[string]map[string][]string{}
	returnTypesBySymbolNameAndDir := map[string]map[string][]string{}
	var inheritanceEdges []RelationRecord // captured for OVERRIDES derivation
	routeHandlers := map[string][]SymbolRecord{}
	httpCallsByRoute := map[string][]RelationRecord{}
	graphqlSchemaFields := map[string][]SymbolRecord{}
	graphqlResolvers := map[string][]SymbolRecord{}
	graphqlOperationRootAliases := map[string]string{}
	for _, file := range files {
		for _, symbol := range recordsByFile[file.Path] {
			if symbol.Kind != "graphql_schema_field" {
				continue
			}
			rootName := graphqlRootNameFromSignature(symbol)
			if rootName == "" || !graphqlOperationRoot(rootName) {
				continue
			}
			if typeName, _, ok := strings.Cut(symbol.QualifiedName, "."); ok {
				graphqlOperationRootAliases[strings.ToLower(typeName)] = rootName
			}
		}
	}
	// Cross-file container index: entitySymbols links a member to its container
	// only within one file, but some containers span files — a Go receiver type
	// commonly lives in a different file of the same package than its methods
	// (C# partial classes and reopened Ruby classes behave the same) — leaving
	// such members with an empty ContainerID and therefore invisible to
	// receiver-typed call resolution. Resolve those containers from the
	// member's qualified-name prefix against the workspace's type-like symbols.
	crossFileContainers := needsCallScan || needsReceiverCalls || needsFields || needsOverrides
	// Cross-file namespace membership is only consulted by the JS/TS
	// merged-declaration fallback (rare), and the lookup memoizes per file, so
	// building the closure up front costs nothing for repositories without
	// TypeScript namespaces.
	foreignJSNamespaceOf := jsCrossFileNamespaceLookup(readContent, recordsByFile)
	typeLikeByShortName := map[string][]SymbolRecord{}
	if crossFileContainers {
		for _, file := range files {
			for _, symbol := range recordsByFile[file.Path] {
				if typeLikeKind(symbol.Kind) {
					typeLikeByShortName[symbol.Name] = append(typeLikeByShortName[symbol.Name], symbol)
				}
			}
		}
	}
	partialContainerCanonical, partialContainerFile := partialTypeCanonicalIDs(files, recordsByFile)
	// Iterate files in their (stable) slice order, not the recordsByFile map, so
	// structural relations stream deterministically.
	for _, file := range files {
		if shouldStop != nil && shouldStop() {
			return
		}
		records := recordsByFile[file.Path]
		for si, symbol := range records {
			if shouldStop != nil && shouldStop() {
				return
			}
			containsScope := "file"
			// A partial type is ONE type written in several declarations. Each
			// part owned only the members it happened to declare, so the type's
			// member set was split and "what does this type have?" returned a
			// slice of it. Point every part's members at the canonical part.
			if canonical, ok := partialContainerCanonical[symbol.ContainerID]; ok && canonical != symbol.ContainerID {
				symbol.ContainerID = canonical
				records[si].ContainerID = canonical
				if partialContainerFile[canonical] != symbol.FilePath {
					containsScope = "module"
				}
			}
			if crossFileContainers && symbol.ContainerID == "" && (symbol.Kind == "method" || symbol.Kind == "field") {
				if parent := containerName(symbol.QualifiedName); parent != "" {
					if container, ok := resolveContainerAcrossFiles(parent, symbol.FilePath, typeLikeByShortName); ok && container.ID 
!= symbol.ID {
						symbol.ContainerID = container.ID
						// Write through so later passes (receiver-call scans read
						// recordsByFile again) see the resolved container too.
						records[si].ContainerID = container.ID
						if container.FilePath != symbol.FilePath {
							containsScope = "module"
						}
					}
				}
			}
			if symbol.Kind == "route" {
				routeHandlers[symbol.Name] = append(routeHandlers[symbol.Name], symbol)
			}
			if endpoint := graphqlBoundaryEndpoint(symbol, graphqlOperationRootAliases); endpoint != "" {
				switch symbol.Kind {
				case "graphql_schema_field":
					graphqlSchemaFields[endpoint] = append(graphqlSchemaFields[endpoint], symbol)
				case "graphql_resolver":
					graphqlResolvers[endpoint] = append(graphqlResolvers[endpoint], symbol)
				}
			}
			emit(RelationRecord{
				RecordType:    "relation",
				FromID:        fileID(repoKey, symbol.FilePath),
				ToID:          symbol.ID,
				Type:          "DEFINES",
				Confidence:    1,
				Reason:        "symbol parsed from file",
				RelationScope: "file",
				Resolution:    "exact",
				TargetKind:    "symbol",
				WarningCodes:  []string{},
			})
			if symbol.ContainerID != "" {
				emit(RelationRecord{
					RecordType:    "relation",
					FromID:        symbol.ContainerID,
					ToID:          symbol.ID,
					Type:          "CONTAINS",
					Confidence:    1,
					Reason:        containmentReason(symbol),
					RelationScope: containsScope,
					Resolution:    "exact",
					TargetKind:    "symbol",
					WarningCodes:  []string{},
				})
			}
			if needsTool && symbol.Kind == "tool" && symbol.ContainerID != "" {
				emit(RelationRecord{
					RecordType:    "relation",
					FromID:        symbol.ContainerID,
					ToID:          symbol.ID,
					Type:          "HANDLES_TOOL",
					Confidence:    0.85,
					Reason:        "tool boundary inferred from handler symbol body",
					RelationScope: "file",
					Resolution:    "pattern",
					TargetKind:    "symbol",
					Evidence: []Evidence{{
						Kind:      "symbol_body",
						FilePath:  symbol.FilePath,
						StartLine: symbol.StartLine,
						EndLine:   symbol.EndLine,
						Detail:    symbol.QualifiedName,
					}},
					WarningCodes: []string{},
				})
			}
			if needsGlobalSymbolsByShortName {
				symbolsByShortName[symbol.Name] = append(symbolsByShortName[symbol.Name], symbol)
			}
			if needsGlobalSymbolsByFile {
				symbolsByFile[symbol.FilePath] = append(symbolsByFile[symbol.FilePath], symbol)
			}
			if symbol.ContainerID != "" && (needsCallScan || needsReceiverCalls || needsFields || needsOverrides) {
				if childNamesByContainer[symbol.ContainerID] == nil {
					childNamesByContainer[symbol.ContainerID] = map[string]bool{}
				}
				childNamesByContainer[symbol.ContainerID][symbol.Name] = true
				if (needsReceiverCalls || needsOverrides) && symbol.Kind == "method" {
					if methodsByContainer[symbol.ContainerID] == nil {
						methodsByContainer[symbol.ContainerID] = map[string]SymbolRecord{}
					}
					methodsByContainer[symbol.ContainerID][symbol.Name] = symbol
				}
				// C# receiver-call resolution also reads the field index:
				// class-level `Type Name { get; }` members type `Name.Method()`
				// receivers (csharpMemberType), so the map is built whenever
				// receiver calls are resolved, not only for field relations.
				if (needsFields || (needsReceiverCalls && symbol.Language == "C#")) && symbol.Kind == "field" {
					if fieldsByContainer[symbol.ContainerID] == nil {
						fieldsByContainer[symbol.ContainerID] = map[string]SymbolRecord{}
					}
					fieldsByContainer[symbol.ContainerID][symbol.Name] = symbol
				}
			}
			if needsReceiverCalls && !typeLikeKind(symbol.Kind) {
				for _, typeName := range symbolTypeReferences(symbol)["RETURNS_TYPE"] {
					if returnTypesBySymbolNameAndFile[symbol.Name] == nil {
						returnTypesBySymbolNameAndFile[symbol.Name] = map[string][]string{}
					}
					returnTypesBySymbolNameAndFile[symbol.Name][symbol.FilePath] = 
append(returnTypesBySymbolNameAndFile[symbol.Name][symbol.FilePath], typeName)
					if symbol.Language == "Go" {
						// A Go package spans every file in a directory, so a factory
						// is commonly declared in a sibling file of its callers; key
						// return types by directory too for the package-level lookup.
						dir := filepath.ToSlash(filepath.Dir(symbol.FilePath))
						if returnTypesBySymbolNameAndDir[symbol.Name] == nil {
							returnTypesBySymbolNameAndDir[symbol.Name] = map[string][]string{}
						}
						returnTypesBySymbolNameAndDir[symbol.Name][dir] = append(returnTypesBySymbolNameAndDir[symbol.Name][dir], 
typeName)
					}
				}
			}
		}
	}
	// PHP declares return types in docblocks far more often than in native
	// hints (WordPress uses docblocks exclusively), and the signature pass
	// above cannot see them. Harvest '@return Type' from the docblock
	// directly above each PHP function/method so factory-return and
	// chained-call receiver inference work (rest_get_server()->dispatch()
	// must resolve through '@return WP_REST_Server').
	if needsReceiverCalls {
		for _, file := range files {
			if file.Language != "PHP" {
				continue
			}
			content, ok := readContent(file.Path)
			if !ok {
				continue
			}
			for name, typeName := range phpDocblockReturnTypes(content) {
				if returnTypesBySymbolNameAndFile[name] == nil {
					returnTypesBySymbolNameAndFile[name] = map[string][]string{}
				}
				returnTypesBySymbolNameAndFile[name][file.Path] = append(returnTypesBySymbolNameAndFile[name][file.Path], typeName)
			}
		}
	}
	// superContainerByID maps a class container to its (direct) superclass
	// container, so receiver-call resolution can follow inheritance: a
	// `this.method()` whose method is declared on a base class resolves up the
	// chain. Built after the symbol pass so the global short-name index is
	// complete; same-file resolution is preferred (a subclass and its base
	// usually share a file — e.g. zod's ZodType hierarchy), falling back to the
	// global index. Single-inheritance only (first EXTENDS edge), which matches
	// class semantics in every language that reaches here.
	superContainerByID := map[string]string{}
	implementersByContainer := map[string][]string{}
	if needsReceiverCalls {
		for _, file := range files {
			for _, symbol := range recordsByFile[file.Path] {
				if !typeLikeKind(symbol.Kind) {
					continue
				}
				for _, edge := range supertypesFromSignature(symbol.Language, symbol.Signature) {
					sup, ok := firstTypeLikeNamed(symbolsByFile[symbol.FilePath], edge.Super)
					if !ok || sup.ID == symbol.ID {
						sup, ok = firstTypeLikeNamed(sharedTypeCandidates(symbol, symbolsByShortName[edge.Super]), edge.Super)
					}
					if !ok || sup.ID == symbol.ID {
						continue
					}
					implementersByContainer[sup.ID] = append(implementersByContainer[sup.ID], symbol.ID)
					if edge.Relation == "EXTENDS" {
						if _, exists := superContainerByID[symbol.ID]; !exists {
							superContainerByID[symbol.ID] = sup.ID
						}
					}
				}
			}
		}
	}
	handledRoutes := map[string]struct{}{}
	// Shared by the route pass below and the per-file loop further down, which
	// both resolve routes spelled as constants out of the same files.
	constantsByFile := newFileStringConstants()
	knownFiles := map[string]bool{}
	for _, file := range files {
		if shouldStop != nil && shouldStop() {
			return
		}
		knownFiles[file.Path] = true
		if route := webRouteBoundary(file.Path); route != "" {
			handledRoutes[route] = struct{}{}
		}
	}
	if spec.emits("HANDLES_ROUTE") {
		for _, r := range goHTTPRouteRelations(files, recordsByFile, readContent, constantsByFile) {
			if shouldStop != nil && shouldStop() {
				return
			}
			emit(r.Relation)
			routeHandlers[r.Route] = append(routeHandlers[r.Route], r.Handler)
			handledRoutes[r.Route] = struct{}{}
		}
		for _, r := range djangoRouteRelations(files, recordsByFile, readContent) {
			if shouldStop != nil && shouldStop() {
				return
			}
			emit(r.Relation)
			routeHandlers[r.Route] = append(routeHandlers[r.Route], r.Handler)
			handledRoutes[r.Route] = struct{}{}
		}
		for _, r := range pythonTornadoRouteRelations(files, recordsByFile, readContent) {
			if shouldStop != nil && shouldStop() {
				return
			}
			emit(r.Relation)
			routeHandlers[r.Route] = append(routeHandlers[r.Route], r.Handler)
			handledRoutes[r.Route] = struct{}{}
		}
		for _, r := range pythonDirectRouteRelations(files, recordsByFile, readContent) {
			if shouldStop != nil && shouldStop() {
				return
			}
			emit(r.Relation)
			routeHandlers[r.Route] = append(routeHandlers[r.Route], r.Handler)
			handledRoutes[r.Route] = struct{}{}
		}
		for _, r := range csharpMinimalAPIRouteRelations(files, recordsByFile, readContent) {
			if shouldStop != nil && shouldStop() {
				return
			}
			emit(r.Relation)
			routeHandlers[r.Route] = append(routeHandlers[r.Route], r.Handler)
			handledRoutes[r.Route] = struct{}{}
		}
		for _, r := range laravelRouteRelations(files, recordsByFile, readContent) {
			if shouldStop != nil && shouldStop() {
				return
			}
			emit(r.Relation)
			routeHandlers[r.Route] = append(routeHandlers[r.Route], r.Handler)
			handledRoutes[r.Route] = struct{}{}
		}
		for _, r := range railsRouteRelations(files, recordsByFile, readContent) {
			if shouldStop != nil && shouldStop() {
				return
			}
			emit(r.Relation)
			routeHandlers[r.Route] = append(routeHandlers[r.Route], r.Handler)
			handledRoutes[r.Route] = struct{}{}
		}
		for _, r := range jsDirectRouteRelations(files, recordsByFile, readContent) {
			if shouldStop != nil && shouldStop() {
				return
			}
			emit(r.Relation)
			routeHandlers[r.Route] = append(routeHandlers[r.Route], r.Handler)
			handledRoutes[r.Route] = struct{}{}
		}
	}
	manifestImports := buildManifestImportResolver(files, readContent)

	// pythonModuleExists reports whether the repo contains a Python file that the
	// strict dotted-module matcher resolves `module` to (the module's own source
	// file or that package's __init__). It disambiguates a `from pkg import sub`
	// submodule import from an `import pkg as sub` alias rename — both record the
	// identical importsByName entry — by asking whether the submodule actually
	// exists. Results are memoized; the scan is restricted to Python files so a
	// same-stem file in another language is never mistaken for a module.
	// Shared by the relation workers below, so the memo is locked. Each module
	// is scanned for once and answered from the map after that.
	var pythonModuleMu sync.Mutex
	pythonModuleFileExists := map[string]bool{}
	pythonModuleExists := func(module string) bool {
		pythonModuleMu.Lock()
		defer pythonModuleMu.Unlock()
		if v, ok := pythonModuleFileExists[module]; ok {
			return v
		}
		found := false
		for p := range knownFiles {
			if ext := path.Ext(p); ext != ".py" && ext != ".pyi" {
				continue
			}
			if dottedModuleMatchesFileStrict(module, p) {
				found = true
				break
			}
		}
		pythonModuleFileExists[module] = found
		return found
	}

	// Package-level vars of package-qualified types, keyed by directory. A Go
	// package spans every file in a directory and a var is commonly declared in
	// one file but called in another, so this must be built before the per-file
	// loop. Used to resolve method calls on such vars to the right imported type.
	// Per-file import bindings (local name -> imported modules plus resolved
	// repo paths), kept for the signature-type and TESTS passes that run after
	// this loop so a bare type name resolves through the file's imports before
	// any global short-name fallback (a common name like Config otherwise binds
	// to whichever same-name type sorts first across the workspace).
	resolvedImportsByFile := map[string]map[string][]string{}
	pkgVarTypesByDir := map[string]map[string]pkgQualType{}
	if needsReceiverCalls {
		for _, file := range files {
			if file.Language != "Go" {
				continue
			}
			content, ok := readContent(file.Path)
			if !ok {
				continue
			}
			vars := collectPackageVarTypes(content)
			if len(vars) == 0 {
				continue
			}
			dir := filepath.ToSlash(filepath.Dir(file.Path))
			if pkgVarTypesByDir[dir] == nil {
				pkgVarTypesByDir[dir] = map[string]pkgQualType{}
			}
			for n, qt := range vars {
				pkgVarTypesByDir[dir][n] = qt
			}
		}
	}

	// Every F# module path in the project, collected once: an F# qualifier is
	// read against the whole project, not against the caller file. Repos with no
	// F# file get two empty maps for one pass over the file list.
	var fsharpProjectModulePathBySymbolID map[string]string
	var fsharpProjectDeclaredModulePaths map[string]bool
	if needsCallScan {
		fsharpProjectModulePathBySymbolID, fsharpProjectDeclaredModulePaths = fsharpProjectModulePaths(files, recordsByFile, 
readContent)
	}

	// The file scan. Every index built above is read-only from here on, and the
	// four accumulators it feeds are append-only, so files resolve on workers
	// while a reducer replays each file's relations, failures and accumulator
	// entries in the original file order. The reducer decides emission order, so
	// worker timing cannot reach the snapshot bytes.
	resolveFileRelations := func(workerCtx context.Context, file FileRecord, emit func(RelationRecord)) fileRelationScan {
		var result fileRelationScan
		// Relations stream through a bounded channel to the ordered reducer.
		// Failures remain per-file metadata, replayed after that file's relations.
		var bufferFailure func(PartialFailure)
		if recordFailure != nil {
			bufferFailure = func(failure PartialFailure) { result.failures = append(result.failures, failure) }
		}
		recordFailure := bufferFailure
		// The outer shouldStop reads emitErr, which the reducer writes. A worker
		// has to ask the context instead.
		shouldStop := func() bool { return workerCtx.Err() != nil }
		if shouldStop() {
			return result
		}
		imports, havePrecomputedImports := precomputedImports[file.Path]
		content := ""
		if !havePrecomputedImports || !skipFastProfilePerSymbolScan(spec, file.Language) {
			var ok bool
			content, ok = readContent(file.Path)
			if !ok {
				return result
			}
			if !havePrecomputedImports {
				imports = importsFor(file.Path, content)
			}
		}
		fromID := fileID(repoKey, file.Path)
		for _, imported := range imports {
			if resolved, ok := resolveLocalImport(file.Path, imported, knownFiles); ok {
				emit(RelationRecord{
					RecordType:    "relation",
					FromID:        fromID,
					ToID:          fileID(repoKey, resolved),
					Type:          "IMPORTS",
					Confidence:    0.95,
					Reason:        "relative import resolved to local file",
					RelationScope: "module",
					Resolution:    "import_resolved",
					TargetKind:    "file",
					Evidence: []Evidence{{
						Kind:     "import_statement",
						FilePath: file.Path,
						Detail:   imported,
					}},
					WarningCodes: []string{},
				})
				continue
			}
			if resolved, ok := manifestImports.resolve(file.Path, imported); ok {
				emit(RelationRecord{
					RecordType:    "relation",
					FromID:        fromID,
					ToID:          fileID(repoKey, resolved.Path),
					Type:          "IMPORTS",
					Confidence:    resolved.Confidence,
					Reason:        resolved.Reason,
					RelationScope: resolved.Scope,
					Resolution:    "import_resolved",
					TargetKind:    "file",
					Evidence: []Evidence{{
						Kind:     resolved.EvidenceKind,
						FilePath: file.Path,
						Detail:   imported,
					}},
					WarningCodes: []string{},
				})
				continue
			}
			warningCodes := []string{}
			if isRelativeImportSpec(file.Path, imported) {
				warningCodes = []string{"UNRESOLVED_RELATIVE_IMPORT"}
			}
			emit(RelationRecord{
				RecordType:    "relation",
				FromID:        fromID,
				ToID:          externalID("import", imported),
				Type:          "IMPORTS",
				Confidence:    0.8,
				Reason:        "import declaration matched by language-specific scanner",
				RelationScope: "external",
				Resolution:    "name_only",
				TargetKind:    "external",
				Evidence: []Evidence{{
					Kind:     "import_statement",
					FilePath: file.Path,
					Detail:   imported,
				}},
				WarningCodes: warningCodes,
			})
		}
		importsByName := importedNamesFor(file.Path, content)
		importsByName = resolvedImportedNameModules(file.Path, importsByName, manifestImports, knownFiles, readContent)
		if needsSignatureTypeImports && len(importsByName) > 0 {
			result.resolvedImports = importsByName
		}
		// The Python dotted-call composer resolves `alias.<tail>.fn()` from the
		// syntactic form each import binding was recorded with (plain, alias
		// rename, or from-import), keyed by [local name][module]. resolvedImported-
		// NameModules only appends resolved file paths, so the original dotted
		// modules the form map keys on survive in importsByName.
		var pythonImportForms map[string]map[string]pythonImportForm
		if file.Language == "Python" {
			pythonImportForms = importedPythonImportForms(content)
		}
		if skipFastProfilePerSymbolScan(spec, file.Language) {
			return result
		}
		lines := strings.Split(content, "
")
		currentFileSymbols := recordsByFile[file.Path]
		// callExtractionLanguage keeps the scan inside the set `capabilities
		// --json` declares CALLS for. Without it the scan also ran over
		// inventory-only `document` symbols (whose block is the whole file) and
		// over data/markup languages, inventing cross-language call edges.
		fileNeedsCallScan := needsCallScan && callExtractionLanguage(file.Language) && !skipFastCFamilyCallScan(spec, 
file.Language)
		var pythonBareScopes *pythonBareImportScopes
		var pythonIncompleteAliases map[string][]pythonImportContext
		if fileNeedsCallScan && file.Language == "Python" {
			pythonBareScopes = newPythonBareImportScopes(content, currentFileSymbols)
			if !pythonBareScopes.complete {
				pythonIncompleteAliases = pythonIncompleteAliasContexts(importedPythonBindings(content))
			}
		}
		fileNeedsRouteScan := spec.emits("HANDLES_ROUTE") && routeScanLanguage(file.Language)
		fileNeedsHTTPScan := spec.emits("HTTP_CALLS") && httpScanLanguage(file.Language)
		fileNeedsServiceScan := needsServiceRelations && serviceScanLanguage(file.Language)
		fileNeedsChannelScan := channelScanLanguage(file.Language)
		var fileStringConstants map[string]string
		if fileNeedsRouteScan || fileNeedsHTTPScan {
			fileStringConstants = constantsByFile.forFile(file.Path, content)
		}
		var routeSymbolsByID map[string]SymbolRecord
		if fileNeedsRouteScan {
			routeSymbolsByID = map[string]SymbolRecord{}
			for _, symbol := range currentFileSymbols {
				routeSymbolsByID[symbol.ID] = symbol
			}
		}
		var phpPropTypes map[string]string
		if file.Language == "PHP" && spec.callResolution == "full" {
			// Property types are declared at the class level, outside any
			// method's block: collect them once per file so property-receiver
			// calls (`$this->prop->method()`) can resolve.
			phpPropTypes = phpPropertyTypes(content)
		}
		var hsImports haskellFileImports
		if file.Language == "Haskell" && fileNeedsCallScan {
			// Import declarations live at the top of the file, outside any
			// binding's block: parse them once per file so qualified
			// applications (`Utils.fn` via `import qualified ... as Utils`)
			// and imported bare names can resolve.
			hsImports = haskellImports(content)
		}
		var ocamlOpenedModules []string
		var ocamlOpenedCallables map[string]bool
		var ocamlOpenedReferences map[string]bool
		if file.Language == "OCaml" && fileNeedsCallScan {
			ocamlOpenedModules = ocamlOpenModules(content)
			ocamlOpenedCallables = ocamlOpenedCallableNames(ocamlOpenedModules, symbolsByShortName)
			ocamlOpenedReferences = ocamlOpenedCallableReferenceNames(ocamlOpenedModules, symbolsByShortName)
		}
		var kotlinPropTypes map[string]string
		if file.Language == "Kotlin" && spec.callResolution == "full" {
			// Kotlin property types live at the class level too (primary
			// constructor val/var parameters, modifier-prefixed declarations
			// and factory initializers): collect them once per file so
			// property-receiver calls (`taskQueue.execute(...)`) can resolve.
			kotlinPropTypes = kotlinPropertyTypes(content, returnTypesBySymbolNameAndFile)
			for name, typeName := range kotlinFieldInitializerTypes(content, recordsByFile[file.Path]) {
				if existing, ok := kotlinPropTypes[name]; !ok || existing == typeName {
					kotlinPropTypes[name] = typeName
				} else {
					delete(kotlinPropTypes, name)
				}
			}
		}
		var typeScriptPropTypes map[string]string
		if file.Language == "TypeScript" && spec.callResolution == "full" {
			// TypeScript class-property receivers are commonly typed by Angular
			// DI initializers (`private router = inject(Router)`) or field
			// annotations outside the method body. Collect those once per file
			// and let receiverCallRelations apply the usual shadowing rules.
			typeScriptPropTypes = typeScriptPropertyTypes(content, recordsByFile[file.Path])
		}
		var fsharpModulePathBySymbolID map[string]string
		var fsharpDeclaredModulePaths map[string]bool
		var fsharpShadowBindings []fsharpShadowBinding
		if file.Language == "F#" && fileNeedsCallScan {
			fsharpModulePathBySymbolID, fsharpDeclaredModulePaths = fsharpProjectModulePathBySymbolID, 
fsharpProjectDeclaredModulePaths
			// Module abbreviations and value bindings are file-scoped, so this
			// is read per file rather than merged into the project-wide map.
			// They keep their positions: which of them shadows a qualifier is a
			// question each call block answers for itself, below.
			fsharpShadowBindings = fsharpFileShadowBindings(content)
		}
		var fsharpCallableNames map[string]bool
		if file.Language == "F#" && fileNeedsCallScan {
			// The names a bare juxtaposition call may name: this file's own
			// callables, plus those an `open` brings into scope unqualified.
			// Computed once per file rather than per symbol.
			fsharpCallableNames = fsharpFileCallableNames(currentFileSymbols)
			for name := range fsharpOpenedCallableNames(fsharpOpenedModules(content), symbolsByShortName) {
				fsharpCallableNames[name] = true
			}
		}
		var jsSymbolNamespaces map[string]string
		var jsScan *jsScanState
		if fileNeedsCallScan && (file.Language == "JavaScript" || file.Language == "TypeScript") {
			// One tree-sitter pass yields namespaces, binding scopes, and dotted
			// call sites for the whole file; every JS/TS scope decision below
			// shares this state instead of re-deriving it per symbol.
			var jsScanErr error
			jsScan, jsScanErr = newJSScanState(file.Path, content)
			if jsScanErr != nil && recordFailure != nil {
				// Surface the degraded relation pass the same way entity-phase
				// parse failures are surfaced, so a timed-out or failed scope
				// parse is observable instead of silently dropping namespace
				// call classification for the file.
				recordFailure(jsScanPartialFailure(file.Path, jsScanErr))
			}
			if jsScan.depthTruncated && recordFailure != nil {
				// A relation-phase walk stopped at the depth limit. Reported
				// separately from jsScanErr because it is a PARTIAL result, not
				// a failed parse: the scope state above the limit is real and
				// still used below. Same code and severity as the entity phase,
				// so one file truncated in both phases stays one record — but
				// mergePartialFailures folds this record's effect and detail into
				// it, because the loss described here (calls not classified) is
				// not the entity phase's loss (declarations not extracted).
				recordFailure(jsScanDepthPartialFailure(file.Path))
			}
			// Without namespaces there is nothing to map: every namespace-call
			// consumer below is gated on jsNamespaceCalls entries, which require
			// scanned namespaces, so skipping the per-symbol declaration matching
			// on namespace-less files (the overwhelming majority) is free.
			if len(jsScan.namespaces) > 0 {
				jsSymbolNamespaces = jsNamespaceBySymbolID(content, currentFileSymbols, jsScan.namespaces)
			}
		}
		var swiftTypes swiftFileTypes
		if file.Language == "Swift" && spec.callResolution == "full" {
			// Swift stored-property types and enum-case payload types live at
			// the type level, outside any method's block: collect them once per
			// file so property receivers (`self._buffer!.discardReadBytes()`)
			// and enum-case pattern bindings (`case .available(var buffer):`)
			// can resolve.
			swiftTypes = swiftFileTypeInfo(content)
		}
		for _, from := range currentFileSymbols {
			if shouldStop() {
				return result
			}
			block := symbolBlockFromLines(lines, from)
			if file.Language == "JavaScript" || file.Language == "TypeScript" || file.Language == "Julia" {
				if exact, ok := exactSymbolSource(content, from); ok {
					block = exact
				}
			}
			if fileNeedsCallScan && !typeLikeKind(from.Kind) && file.Language == "Erlang" {
				// Erlang call sites carry information the generic scanner cannot
				// use: a bare call is module-local by language rule, and a remote
				// `mod:fun(...)` call names the target module explicitly (module
				// `mod` lives in `mod.erl` by convention). A dedicated scanner
				// also keeps Erlang's variables (capitalized), `?MACRO(...)`
				// expansions, and `%` comments out of the call-name set.
				for _, r := range erlangCallRelations(from, block, currentFileSymbols, symbolsByShortName) {
					emit(r)
				}
			} else if fileNeedsCallScan && !typeLikeKind(from.Kind) && file.Language == "OCaml" {
				// OCaml applies functions by juxtaposition (`Mod.fn arg`), so
				// the generic `name(` scanner sees almost no OCaml call sites;
				// a dedicated scanner reads applications directly and uses the
				// module qualifier (module `Mod` lives in `mod.ml` by language
				// convention) to resolve targets. Interfaces (`.mli`) contain
				// only type mentions, and a nested module's block spans its
				// members' bodies, so both are skipped rather than misread.
				if from.Kind != "module" && ocamlCallScanFile(file.Path) {
					for _, r := range ocamlCallRelations(from, block, currentFileSymbols, symbolsByShortName, ocamlOpenedModules, 
ocamlOpenedCallables, ocamlOpenedReferences) {
						emit(r)
					}
				}
			} else if fileNeedsCallScan && !typeLikeKind(from.Kind) && file.Language == "Haskell" {
				// Haskell applies functions by whitespace (`fn arg`, `fn $
				// arg`, `Alias.fn arg`), so the generic `name(` scanner sees
				// almost no Haskell call sites; a dedicated scanner reads
				// applications directly, resolves qualified names through the
				// file's import aliases, and resolves bare names against
				// same-file bindings and the import section.
				for _, r := range haskellCallRelations(from, block, currentFileSymbols, symbolsByShortName, hsImports) {
					emit(r)
				}
			} else if fileNeedsCallScan && !typeLikeKind(from.Kind) {
				callBlock := block
				if file.Language == "F#" && from.Kind == "module" {
					// A module's block spans its members, so scanning it whole
					// credits the module with the calls its FUNCTIONS make.
					// Its own initialisation code is what is left once those
					// are blanked out, and it is the only scan that can see it.
					callBlock = fsharpModuleInitBlock(lines, from, currentFileSymbols)
				}
				if file.Language == "Rust" {
					callBlock = stripRustCodegenMacroBodies(block)
				}
				if file.Language == "C#" {
					// Multi-line verbatim/raw string bodies (SQL blocks and the
					// like) survive the generic stripper's line-scoped string
					// masking and would register as call sites.
					callBlock = maskCSharpTextBlocks(block)
				}
				if file.Language == "Swift" {
					// Multiline string bodies ("""...""") likewise survive the
					// line-scoped masking and would register as call sites.
					callBlock = maskSwiftMultilineStrings(block)
				}
				if file.Language == "Groovy" {
					// Triple-quoted, slashy, and interpolated string bodies
					// survive the generic line-scoped masking and would
					// register as call sites.
					callBlock = maskGroovyLiteralsAndComments(block)
				}
				callNames := callLikeIdentifiers(callBlock, file.Language)
				jsCallableArgumentOnly := map[string]bool{}
				jsNamespaceCalls := map[string]struct{}{}
				fsharpCallQualifiers := map[string]map[string]struct{}{}
				var juliaLocalBindings map[string]struct{}
				if file.Language == "Julia" {
					callNames = juliaCallIdentifiers(callBlock)
					if len(callNames) > 0 && from.Kind == "method" && !from.Local && from.ContainerID != "" {
						juliaLocalBindings = juliaLocalBindingNames(callBlock)
					}
				}
				if file.Language == "Rust" {
					for name := range rustTurbofishCallIdentifiers(callBlock) {
						callNames[name] = struct{}{}
					}
				}
				if file.Language == "Ruby" {
					// Ruby method names may end in `!`/`?` and are commonly called
					// without parentheses; the generic scanner misses both.
					for name := range rubySuffixedCallIdentifiers(callBlock) {
						callNames[name] = struct{}{}
					}
				}
				if file.Language == "Kotlin" {
					// Kotlin trailing-lambda calls (`runTask { ... }`) carry no
					// parentheses, so the generic `name(` scanner never sees
					// them.
					for name := range kotlinBareLambdaCallIdentifiers(callBlock) {
						callNames[name] = struct{}{}
					}
				}
				if file.Language == "Groovy" {
					// Groovy command expressions (`visitType p.type`,
					// `print 'x'`) likewise carry no parentheses. callBlock is
					// already Groovy-masked above.
					for name := range groovyCommandCallIdentifiers(callBlock) {
						callNames[name] = struct{}{}
					}
				}
				if file.Language == "JavaScript" || file.Language == "TypeScript" {
					// Same-file namespaces (`Parser.parseSourceFile(...)`) are kept
					// qualified so duplicate terminal names in other namespaces cannot
					// steal the edge. Imported and ordinary object receivers are handled
					// by their receiver-aware resolution paths below. Shadowing and
					// namespace context come from the AST-derived scan state at each
					// call site's own position.
					for name := range jsScan.namespaceCallsForSymbol(from) {
						callNames[name] = struct{}{}
						jsNamespaceCalls[name] = struct{}{}
					}
					for name := range jsCallableArgumentIdentifiers(callBlock) {
						if _, directCall := callNames[name]; !directCall {
							jsCallableArgumentOnly[name] = true
						}
						callNames[name] = struct{}{}
					}
				}
				if file.Language == "F#" {
					// F# module-qualified calls (`UpdateProcess.SmartInstall(...)`,
					// `LoadingScripts.ScriptGeneration.constructScriptsFromData(...)`)
					// hide the target behind a dotted path; forward pipes
					// (`value |> normalize`) apply a function by juxtaposition, with
					// no dot and no parentheses, so neither the dotted scanners nor
					// the generic `name(` one sees them. Resolution matches on the
					// name, but the qualifier is kept so a call naming a module this
					// file declares stays inside it.
					masked := maskFSharpBlockComments(callBlock)
					// Shadowing is lexical AND ordered, so it is answered per
					// call SITE: only the file's bindings that reach the line a
					// call is written on may un-qualify it. A binding local to a
					// sibling function, written below the block, or written
					// below the call inside this very block, is not in scope
					// there and leaves the qualifier alone.
					fsharpShadowedQualifiers := fsharpShadowsAt(fsharpShadowBindings, masked, from.StartLine)
					// An unqualified call written with parentheses (`convert(x)`)
					// has no dot and no pipe, so only the generic scanner above
					// sees it and it reached no qualifier record. A block holding
					// both `A.convert(x)` and `convert(x)` was then restricted to
					// A, and the bare site -- which meant this module's own
					// `convert` -- resolved to A's. Record the generic names
					// first, unqualified, exactly as a bare pipe target is
					// recorded, so both spellings of a bare call clear the
					// restriction alike. They are read from the masked block for
					// the same reason the targets are: a call inside `(* ... *)`
					// is not a call site.
					for name := range callLikeIdentifiers(masked, file.Language) {
						// A bare spelling carries no qualifier to shadow, so no
						// binding can change what it records.
						recordFSharpCallQualifier(fsharpCallQualifiers, fsharpDeclaredModulePaths, nil, name, name)
					}
					for target, offsets := range fsharpCallTargetSites(masked) {
						name := lastDottedCallSegment(target)
						if name == "" {
							continue
						}
						callNames[name] = struct{}{}
						// One record per SIGHTING: the same spelling written
						// above and below a binding of its head is two call
						// sites with two different answers.
						for _, offset := range offsets {
							recordFSharpCallQualifier(fsharpCallQualifiers, fsharpDeclaredModulePaths, fsharpShadowedQualifiers(offset), 
name, target)
						}
					}
					// Plain juxtaposition (`add ledger amount`) is F#'s ordinary
					// call syntax and has neither a dot, a pipe nor parentheses
					// to mark it. Whitespace alone does not say which of several
					// adjacent names is the one being applied, so the scan is
					// restricted to names that are callable bindings in this
					// file — an unrecognized name is never guessed into a call.
					for name := range fsharpJuxtapositionCallIdentifiers(callBlock, fsharpCallableNames) {
						callNames[name] = struct{}{}
						// Juxtaposition is a bare spelling just like convert(x).
						// Keep it beside any A.convert sighting with the same
						// terminal name instead of inheriting A's restriction.
						recordFSharpCallQualifier(fsharpCallQualifiers, fsharpDeclaredModulePaths, nil, name, name)
					}
				}
				if file.Language == "Lua" {
					// Lua table/module calls (`vim.split(...)`, `M.joinpath(...)`)
					// are dotted or colon-qualified; the generic scanner drops the
					// final segment because it follows a selector.
					for name := range luaDottedCallIdentifiers(callBlock) {
						callNames[name] = struct{}{}
					}
				}
				if file.Language == "Zig" {
					// Zig code frequently calls imported analyzer helpers through
					// module aliases (`analysis.resolveVarDeclAlias(...)`).
					for name := range zigDottedCallIdentifiers(callBlock) {
						callNames[name] = struct{}{}
					}
				}
				if shellCallLanguage(file.Language) {
					// Shell functions are invoked as bare commands with no
					// parentheses; the generic scanner sees no call sites at all.
					for name := range shellCommandCallIdentifiers(callBlock) {
						callNames[name] = struct{}{}
					}
				}
				if file.Language == "Clojure" || file.Language == "ClojureScript" {
					// Clojure calls are list heads, usually `(name ...)` or
					// `(alias/name ...)`, not `name(...)`.
					for name := range clojureCallIdentifiers(callBlock) {
						callNames[name] = struct{}{}
					}
				}
				if file.Language == "SQL" {
					// PostgreSQL function/procedure bodies call routines as
					// `name(...)` or `schema.name(...)`. The generic scanner
					// drops schema-qualified calls because of the preceding dot.
					for name := range sqlCallIdentifiers(callBlock) {
						callNames[name] = struct{}{}
					}
				}
				callImportsByName := importsByName
				// Python module-qualified dotted calls (`pkg.mod.fn()`) are resolved
				// by a dedicated, strictly module-scoped path (emitted after the
				// generic loop below): the generic resolver ignores the module
				// qualifier and would mis-resolve to an unrelated same-named symbol.
				var pythonDottedRelations []RelationRecord
				if file.Language == "Python" {
					allDotted, externalDotted := pythonDottedCallImportedNames(callBlock, importsByName, pythonImportForms, 
pythonModuleExists)
					if len(allDotted) > 0 {
						pythonDottedRelations = pythonDottedCallRelations(from, allDotted, externalDotted, importsByName, 
symbolsByShortName, childNamesByContainer[from.ID])
					}
				}
				for _, name := range sortedKeysOf(callNames) {
					if name == from.Name {
						continue
					}
					inputs := pythonCallImportBinding(name, from, file.Language, pythonBareScopes, symbolsByShortName, 
callImportsByName, file.Path, manifestImports, knownFiles, readContent)
					rawCandidates := inputs.rawCandidates
					rawImportModuleSets := inputs.rawImportModuleSets
					importsForCall := inputs.imports
					var pythonAliasTargets []resolvedCallTarget
					var pythonAliasExternal []RelationRecord
					pythonGenericAllowed := inputs.genericAllowed
					if file.Language == "Python" {
						// The raw FFI exception is valid only for imports visible at an
						// unshadowed AST call site in this callable. Ordinary filtered
						// resolution keeps its established file-level map when scope
						// analysis is incomplete; that incomplete view may only disable
						// the raw cross-language exception, never ordinary imports.
						if pythonBareScopes.complete {
							pythonAliasTargets, pythonAliasExternal, _ = resolvePythonAliasImportTargets(name, from, 
pythonBareScopes.importContexts(from, name), symbolsByShortName, file.Path, manifestImports, knownFiles, readContent)
						} else {
							rawCandidates = nil
							if contexts := pythonIncompleteAliases[name]; len(contexts) > 0 {
								pythonAliasExternal = pythonAliasExternalCallRelations(from, contexts)
								pythonGenericAllowed = false
							}
						}
					}
					// A container's block spans its members' definition lines, which
					// look like calls (e.g. `def validate(self):`). Skip the names of
					// direct children so a class is not credited with calling its own
					// methods; the real call site lives in the calling function.
					if childNamesByContainer[from.ID][name] {
						continue
					}
					var targets []resolvedCallTarget
					suppressExternal := false
					if file.Language == "Python" && !pythonGenericAllowed {
						suppressExternal = true
					} else if _, namespaceCall := jsNamespaceCalls[name]; namespaceCall {
						// Same-file namespace members first, then members of a
						// merged same-file value declaration, then the terminal-name
						// fallback for namespaces reopened in another file. Shadowed
						// receiver roots never reach jsNamespaceCalls, so the
						// fallback stays scope-accurate; self-calls and the caller's
						// own member names stay excluded from it, matching the
						// bare-name path.
						targets = resolveJSNamespaceCallChain(name, from, currentFileSymbols, jsSymbolNamespaces, symbolsByShortName, 
foreignJSNamespaceOf, func(terminal string) bool {
							return terminal == from.Name || childNamesByContainer[from.ID][terminal]
						})
					} else if quals := fsharpResolvableQualifiers(fsharpCallQualifiers[name]); len(quals) > 0 {
						// One resolution per SPELLING, not one per name: with both
						// `A.convert` and `B.convert` written in this caller, a single
						// entry had to pick one module or neither, and picking neither
						// left `resolveCallTargets` choosing the same-file definition
						// nearest the call site -- one real call dropped and the
						// survivor decided by line distance rather than by what was
						// written. A bare sighting is a spelling too, resolved
						// unrestricted BESIDE the qualified ones rather than
						// cancelling them. Targets are de-duplicated because two
						// qualifiers may name the same module by different relative
						// paths, and because a bare and a qualified sighting can agree.
						seenTargets := map[string]bool{}
						for _, qualifier := range quals {
							for _, to := range resolveCallTargets(name, from,
								fsharpQualifiedScope(symbolsByShortName[name], qualifier, fsharpModulePathBySymbolID[from.ID], 
fsharpModulePathBySymbolID, fsharpDeclaredModulePaths),
								fsharpQualifiedScope(currentFileSymbols, qualifier, fsharpModulePathBySymbolID[from.ID], 
fsharpModulePathBySymbolID, fsharpDeclaredModulePaths),
								callImportsByName, false) {
								if seenTargets[to.ID] {
									continue
								}
								seenTargets[to.ID] = true
								targets = append(targets, to)
							}
						}
					} else {
						targets = resolveCallTargetsWithRawImport(name, from, sharedTypeCandidates(from, symbolsByShortName[name]), 
rawCandidates, rawImportModuleSets, currentFileSymbols, importsForCall, false)
						juliaTargets, found, blocked := resolveJuliaSameContainerMethodCallTargets(name, from, currentFileSymbols, 
juliaLocalBindings)
						genericSameContainerType := len(targets) == 1 && typeLikeKind(targets[0].Kind) &&
							targets[0].FilePath == from.FilePath && targets[0].ContainerID == from.ContainerID
						if blocked {
							targets = nil
							suppressExternal = true
						} else if found && !genericSameContainerType {
							targets = juliaTargets
							suppressExternal = len(juliaTargets) == 0
						}
					}
					normalTargets := targets
					if file.Language == "Python" {
						targets = unionResolvedCallTargets(normalTargets, pythonAliasTargets)
					}
					for _, to := range targets {
						// A bare identifier passed as an argument may be a callback, but
						// it is not a construction. Keep callback discovery additive while
						// preventing `fn(input)` from linking the argument `input` to an
						// unrelated same-named type alias.
						if jsCallableArgumentOnly[name] && typeLikeKind(to.Kind) {
							continue
						}
						// Call to a type (class/struct/...) is a constructor/conversion, not a
						// callable->callable call: keep it as CONSTRUCTS for agents, out of CALLS.
						relType := "CALLS"
						if typeLikeKind(to.Kind) {
							relType = "CONSTRUCTS"
						}
						emit(RelationRecord{
							RecordType:    "relation",
							FromID:        from.ID,
							ToID:          to.ID,
							Type:          relType,
							Confidence:    to.Confidence,
							Reason:        to.Reason,
							RelationScope: to.Scope,
							Resolution:    to.Resolution,
							TargetKind:    "symbol",
							Evidence: []Evidence{{
								Kind:      "call_site",
								FilePath:  from.FilePath,
								StartLine: from.StartLine,
								EndLine:   from.EndLine,
								Detail:    name,
							}},
							WarningCodes: []string{},
						})
					}
					if len(targets) == 0 && file.Language == "Kotlin" && spec.callResolution == "full" {
						// A bare call inside a Kotlin extension-function body
						// (`fun ApplicationCall.respondResource(...)` calling
						// `resolveResource(...)`) dispatches on the implicit
						// extension receiver: resolve it against the receiver
						// type's members and matching extension functions.
						if to, reason, ok := kotlinImplicitReceiverCallTarget(from, name, methodsByContainer, superContainerByID, 
symbolsByShortName); ok {
							scope := "file"
							if to.FilePath != from.FilePath {
								scope = "module"
							}
							emit(RelationRecord{
								RecordType:    "relation",
								FromID:        from.ID,
								ToID:          to.ID,
								Type:          "CALLS",
								Confidence:    0.8,
								Reason:        reason,
								RelationScope: scope,
								Resolution:    "type_inferred",
								TargetKind:    "symbol",
								Evidence: []Evidence{{
									Kind:      "call_site",
									FilePath:  from.FilePath,
									StartLine: from.StartLine,
									EndLine:   from.EndLine,
									Detail:    name,
								}},
								WarningCodes: []string{},
							})
							continue
						}
					}
					if file.Language == "Python" {
						for _, relation := range pythonAliasExternal {
							emit(relation)
						}
						if pythonGenericAllowed && len(normalTargets) == 0 && !suppressExternal {
							for _, relation := range importedExternalCallRelationsForName(from, name, importsForCall[name]) {
								emit(relation)
							}
						}
					} else if len(targets) == 0 && !suppressExternal {
						for _, relation := range importedExternalCallRelationsForName(from, name, importsForCall[name]) {
							emit(relation)
						}
					}
				}
				for _, relation := range pythonDottedRelations {
					emit(relation)
				}
			}
			callableSymbol := !typeLikeKind(from.Kind)
			// One stripped copy of this symbol, read by every generic scanner
			// below. Behind the union of their guards, and behind the callable
			// test all of them apply, so a profile that runs none of them and a
			// symbol none of them look at both still cost nothing.
			var body symbolBody
			if callableSymbol && (needsAsyncCalls || needsDataFlow || needsFields || spec.callResolution == "full") {
				body = newSymbolBody(block)
			}
			if needsAsyncCalls && callableSymbol {
				for _, name := range asyncCallNames(body) {
					if name == from.Name {
						continue
					}
					inputs := pythonCallImportBinding(name, from, file.Language, pythonBareScopes, symbolsByShortName, importsByName, 
file.Path, manifestImports, knownFiles, readContent)
					var targets []resolvedCallTarget
					if file.Language != "Python" || inputs.genericAllowed {
						targets = resolveCallTargetsWithRawImport(name, from, sharedTypeCandidates(from, symbolsByShortName[name]), 
inputs.rawCandidates, inputs.rawImportModuleSets, currentFileSymbols, inputs.imports, false)
					}
					if file.Language == "Python" && pythonBareScopes != nil && pythonBareScopes.complete {
						aliasTargets, _, _ := resolvePythonAliasImportTargets(name, from, pythonBareScopes.importContexts(from, name), 
symbolsByShortName, file.Path, manifestImports, knownFiles, readContent)
						targets = unionResolvedCallTargets(targets, aliasTargets)
					}
					for _, to := range targets {
						if typeLikeKind(to.Kind) {
							continue // construction, not an async call
						}
						emit(RelationRecord{
							RecordType:    "relation",
							FromID:        from.ID,
							ToID:          to.ID,
							Type:          "ASYNC_CALLS",
							Confidence:    minFloat(to.Confidence, 0.85),
							Reason:        "async call site resolved to symbol",
							RelationScope: to.Scope,
							Resolution:    to.Resolution,
							TargetKind:    "symbol",
							Evidence: []Evidence{{
								Kind:      "async_call_site",
								FilePath:  from.FilePath,
								StartLine: from.StartLine,
								EndLine:   from.EndLine,
								Detail:    name,
							}},
							WarningCodes: []string{},
						})
					}
				}
			}
			if needsDataFlow && callableSymbol {
				// Several flows can describe one edge: `f(a, b, c)` forwards three
				// caller parameters into the same callee, and relation identity is
				// from+to+type, so all three land on one record. Collect every flow
				// for an edge into its evidence array here rather than emitting
				// competing records and letting the dedupe keep an arbitrary first
				// one — that reported one real flow as if it were the only one.
				// Grouping at emit keeps the streaming path's bounded memory (the
				// map lives for one symbol) and needs no dedupe-side merge.
				//
				// The residual this cannot reach: an edge two symbols each
				// justify (A forwards a parameter into B, B returns A()) is
				// produced twice from different `from` symbols, and the dedupe
				// keeps the first, unmarked. Merging those needs a boundary that
				// sees every producer, which on the streaming path means buffering
				// all DATA_FLOWS records to the end of the pass -- memory that
				// grows with the edge count, and output reordered out of the
				// canonical order this change exists to guarantee. It costs a few
				// edges here (currently 4 of 5,240, all of them mutual recursion
				// inside one file), so it is documented in the schema rather than
				// paid for. Revisit if a corpus shows it is not rare.
				edgeOrder := []string{}
				flowsByEdge := map[string]*RelationRecord{}
				for _, flow := range returnFlowCalls(body, symbolFlowParameterNames(from)) {
					if flow.Name == from.Name {
						continue
					}
					inputs := pythonCallImportBinding(flow.Name, from, file.Language, pythonBareScopes, symbolsByShortName, 
importsByName, file.Path, manifestImports, knownFiles, readContent)
					var targets []resolvedCallTarget
					if file.Language != "Python" || inputs.genericAllowed {
						targets = resolveCallTargetsWithRawImport(flow.Name, from, sharedTypeCandidates(from, 
symbolsByShortName[flow.Name]), inputs.rawCandidates, inputs.rawImportModuleSets, currentFileSymbols, inputs.imports, 
true)
					}
					if file.Language == "Python" && pythonBareScopes != nil && pythonBareScopes.complete {
						aliasTargets, _, _ := resolvePythonAliasImportTargets(flow.Name, from, pythonBareScopes.importContexts(from, 
flow.Name), symbolsByShortName, file.Path, manifestImports, knownFiles, readContent)
						targets = unionResolvedCallTargets(targets, aliasTargets)
					}
					for _, to := range targets {
						if flow.Direction == "caller_to_callee" && to.Resolution == "name_only" {
							continue
						}
						fromID, toID := to.ID, from.ID
						confidenceCap := 0.75
						if flow.Direction == "caller_to_callee" {
							fromID, toID = from.ID, to.ID
							confidenceCap = 0.7
						}
						item := Evidence{
							Kind:      flow.EvidenceKind,
							FilePath:  from.FilePath,
							StartLine: from.StartLine,
							EndLine:   from.EndLine,
							Detail:    flow.Detail,
						}
						edgeKey := fromID + "\x00" + toID
						if existing, ok := flowsByEdge[edgeKey]; ok {
							// Past the cap the array stops growing, so the record has to
							// say so rather than read as an exhaustive list again.
							//
							// Assigned, not appended: this branch runs once per dropped
							// flow, not once per edge, so appending would repeat the code
							// as many times as the cap dropped. Anything that later needs
							// to preserve other warning codes here has to append under a
							// contains-check, not switch to a bare append.
							if len(existing.Evidence) >= dataFlowEvidenceLimit {
								existing.WarningCodes = []string{evidenceTruncatedWarning}
								existing.EvidenceDropped++
								continue
							}
							existing.Evidence = append(existing.Evidence, item)
							continue
						}
						edgeOrder = append(edgeOrder, edgeKey)
						flowsByEdge[edgeKey] = &RelationRecord{
							RecordType:    "relation",
							FromID:        fromID,
							ToID:          toID,
							Type:          "DATA_FLOWS",
							Confidence:    minFloat(to.Confidence, confidenceCap),
							Reason:        flow.Reason,
							RelationScope: to.Scope,
							Resolution:    to.Resolution,
							TargetKind:    "symbol",
							Evidence:      []Evidence{item},
							WarningCodes:  []string{},
						}
					}
				}
				// returnFlowCalls is totally ordered and resolveCallTargets is
				// deterministic, so both the edge order and each evidence array are
				// reproducible without re-sorting.
				for _, edgeKey := range edgeOrder {
					emit(*flowsByEdge[edgeKey])
				}
			}
			if fileNeedsServiceScan {
				for _, boundary := range serviceBoundaries(from, block) {
					if !spec.emits(boundary.Relation) {
						continue
					}
					emit(RelationRecord{
						RecordType:    "relation",
						FromID:        from.ID,
						ToID:          externalID(boundary.Kind, boundary.Name),
						Type:          boundary.Relation,
						Confidence:    boundary.Confidence,
						Reason:        boundary.Reason,
						RelationScope: "external",
						Resolution:    "pattern",
						TargetKind:    boundary.Kind,
						Evidence: []Evidence{{
							Kind:      boundary.EvidenceKind,
							FilePath:  from.FilePath,
							StartLine: from.StartLine,
							EndLine:   from.EndLine,
							Detail:    boundary.Name,
						}},
						WarningCodes: boundary.WarningCodes,
					})
				}
			}
			if fileNeedsRouteScan {
				for _, route := range routeLiteralsForSymbol(file.Path, content, block, from, routeSymbolsByID, 
fileStringConstants) {
					if _, ok := handledRoutes[route]; ok {
						continue
					}
					relation := RelationRecord{
						RecordType:    "relation",
						FromID:        from.ID,
						ToID:          externalID("route", route),
						Type:          "HANDLES_ROUTE",
						Confidence:    0.7,
						Reason:        "route-like string literal found inside handler symbol",
						RelationScope: "external",
						Resolution:    "pattern",
						TargetKind:    "route",
						Evidence: []Evidence{{
							Kind:      "route_literal",
							FilePath:  from.FilePath,
							StartLine: from.StartLine,
							EndLine:   from.EndLine,
							Detail:    route,
						}},
						WarningCodes: []string{},
					}
					emit(relation)
					result.routeHandlers = append(result.routeHandlers, routeHandlerEntry{route: route, handler: from})
				}
			}
			if fileNeedsHTTPScan && callableSymbol {
				for _, call := range httpCallsWithConstants(block, fileStringConstants) {
					confidence := 0.7
					if call.Absolute {
						confidence = 0.6 // host ignored; cross-service path match is weaker
					}
					relation := RelationRecord{
						RecordType:    "relation",
						FromID:        from.ID,
						ToID:          externalID("route", call.Path),
						Type:          "HTTP_CALLS",
						Confidence:    confidence,
						Reason:        "outbound HTTP client call to " + call.Method + " " + call.Path,
						RelationScope: "external",
						Resolution:    "pattern",
						TargetKind:    "route",
						Evidence: []Evidence{{
							Kind:      "http_call_site",
							FilePath:  from.FilePath,
							StartLine: from.StartLine,
							EndLine:   from.EndLine,
							Detail:    call.Method + " " + call.Path,
						}},
						WarningCodes: []string{},
					}
					emit(relation)
					result.httpCalls = append(result.httpCalls, httpCallEntry{route: call.Path, relation: relation})
				}
			}
			if fileNeedsChannelScan {
				for _, event := range channelEvents(block) {
					if !spec.emits(event.Relation) {
						continue
					}
					emit(RelationRecord{
						RecordType:    "relation",
						FromID:        from.ID,
						ToID:          externalID("channel", event.Name),
						Type:          event.Relation,
						Confidence:    0.6,
						Reason:        "event/channel name detected by emit/listen pattern",
						RelationScope: "external",
						Resolution:    "pattern",
						TargetKind:    "channel",
						Evidence: []Evidence{{
							Kind:      "channel_call_site",
							FilePath:  from.FilePath,
							StartLine: from.StartLine,
							EndLine:   from.EndLine,
							Detail:    event.Name,
						}},
						WarningCodes: []string{"WEAK_PATTERN"},
					})
				}
				// NestJS microservice handlers declare their transport channel via
				// an @MessagePattern/@EventPattern decorator rather than a runtime
				// .on()/.subscribe() call, so the generic channelEvents scan misses
				// them. They are the consumer side of the transport, so emit them as
				// LISTENS_ON; the emitter side (client.emit/client.send) is picked up
				// by the generic emit scan and matched on the shared channel name.
				if spec.emits("LISTENS_ON") && !typeLikeKind(from.Kind) && jsLikeExtension(filepath.Ext(file.Path)) {
					for _, channel := range nestJSMessagePatternChannelsAroundSymbol(content, from) {
						emit(RelationRecord{
							RecordType:    "relation",
							FromID:        from.ID,
							ToID:          externalID("channel", channel),
							Type:          "LISTENS_ON",
							Confidence:    0.7,
							Reason:        "NestJS @MessagePattern/@EventPattern handler",
							RelationScope: "external",
							Resolution:    "pattern",
							TargetKind:    "channel",
							Evidence: []Evidence{{
								Kind:      "message_pattern_decorator",
								FilePath:  from.FilePath,
								StartLine: from.StartLine,
								EndLine:   from.EndLine,
								Detail:    channel,
							}},
							WarningCodes: []string{},
						})
					}
				}
			}
			// The receiver pass resolves `recv.method(...)` and is a second
			// producer of CALLS, so it takes the same language gate as the
			// bare-name scan above: without it an inventory-only `document`
			// symbol still reached it and matched a `x.y(...)` shape anywhere
			// in the file against another language's methods.
			if spec.callResolution == "full" && callExtractionLanguage(file.Language) {
				for _, r := range receiverCallRelations(from, body, methodsByContainer, superContainerByID, 
implementersByContainer, symbolsByShortName, returnTypesBySymbolNameAndFile, returnTypesBySymbolNameAndDir, 
importsByName, manifestImports.goModule, pkgVarTypesByDir[filepath.ToSlash(filepath.Dir(file.Path))], phpPropTypes, 
kotlinPropTypes, typeScriptPropTypes, fieldsByContainer, swiftTypes) {
					emit(r)
				}
				for _, r := range importedReceiverCallRelations(from, body, importsByName, symbolsByShortName) {
					emit(r)
				}
			}
			if needsFields {
				for _, r := range fieldAccessRelations(from, body, fieldsByContainer, symbolsByShortName) {
					emit(r)
				}
			}
		}

		// Erlang has no top-level call expressions: everything outside function
		// bodies is a module attribute, and attribute payloads like
		// `-spec name(...)` or `-export([...])` are declarations that would
		// register as bogus file->function call sites. OCaml is skipped for
		// the mirror-image reason: expression code lives in `let` bindings
		// (extracted as symbols and scanned by the dedicated OCaml pass), so
		// what remains at top level is declarations — opens, type definitions,
		// signatures — whose `name (` sequences are type syntax, not calls.
		// Haskell matches the same shape: all expressions live in top-level
		// bindings (extracted as symbols and scanned by the dedicated Haskell
		// pass), and what remains at top level — module/export lists, imports
		// like `hiding (doesFileExist)`, class/instance heads — would only
		// register bogus file->symbol call sites.
		if fileNeedsCallScan && file.Language != "Erlang" && file.Language != "OCaml" && file.Language != "Haskell" {
			topLevelSource := topLevelBlockFromLines(lines, currentFileSymbols)
			if jsScan != nil {
				// Byte-exact complement of the per-symbol scans: a JS/TS call
				// sharing a line with a declaration (`export function f() {}
				// helper();`) is outside every symbol's byte range, so it must
				// stay visible to the top-level scan instead of vanishing with
				// the line-granular mask.
				topLevelSource = jsScan.topLevelBlock(content, currentFileSymbols)
			}
			topLevel := stripDeclarationOnlyCallSignatures(file.Language, topLevelSource)
			if file.Language == "Rust" {
				topLevel = stripRustCodegenMacroBodies(topLevel)
			}
			if file.Language == "Groovy" {
				// Multi-line string bodies at script level would otherwise
				// register as top-level call sites.
				topLevel = maskGroovyLiteralsAndComments(topLevel)
			}
			if strings.TrimSpace(topLevel) != "" {
				fileSource := SymbolRecord{
					ID:       fileID(repoKey, file.Path),
					Kind:     "file",
					Name:     filepath.Base(file.Path),
					FilePath: file.Path,
					Language: file.Language,
				}
				topLevelNames := callLikeIdentifiers(topLevel, file.Language)
				jsCallableArgumentOnly := map[string]bool{}
				jsNamespaceCalls := map[string]struct{}{}
				topLevelFSharpQualifiers := map[string]map[string]struct{}{}
				if file.Language == "Julia" {
					topLevelNames = juliaCallIdentifiers(topLevel)
				}
				if file.Language == "Rust" {
					for name := range rustTurbofishCallIdentifiers(topLevel) {
						topLevelNames[name] = struct{}{}
					}
				}
				if file.Language == "JavaScript" || file.Language == "TypeScript" {
					// Statement-position calls inside namespace bodies resolve their
					// relative receivers through the namespace each call lexically
					// sits in (`B.f()` inside `namespace A` canonicalizes to A.B.f).
					for name := range jsScan.topLevelNamespaceCalls(currentFileSymbols) {
						topLevelNames[name] = struct{}{}
						jsNamespaceCalls[name] = struct{}{}
					}
					for name := range jsCallableArgumentIdentifiers(topLevel) {
						if _, directCall := topLevelNames[name]; !directCall {
							jsCallableArgumentOnly[name] = true
						}
						topLevelNames[name] = struct{}{}
					}
				}
				if file.Language == "F#" {
					// Statement-position pipelines (`"x" |> normalize |> ignore` in an
					// .fsx script, or in a module body) are bound to no symbol, so the
					// per-symbol scan above never sees them.
					masked := maskFSharpBlockComments(topLevel)
					// The top-level block spans the file with every symbol's
					// lines blanked, so it is already in file coordinates and a
					// binding buried in a function body covers only lines that
					// hold no top-level call site.
					fsharpShadowedQualifiers := fsharpShadowsAt(fsharpShadowBindings, masked, 1)
					// Same as the per-symbol path: a parenthesised bare call is
					// seen only by the generic scanner, so it has to clear the
					// qualifier here too, and it carries no qualifier to shadow.
					for name := range callLikeIdentifiers(masked, file.Language) {
						recordFSharpCallQualifier(topLevelFSharpQualifiers, fsharpDeclaredModulePaths, nil, name, name)
					}
					for target, offsets := range fsharpCallTargetSites(masked) {
						name := lastDottedCallSegment(target)
						if name == "" {
							continue
						}
						topLevelNames[name] = struct{}{}
						for _, offset := range offsets {
							recordFSharpCallQualifier(topLevelFSharpQualifiers, fsharpDeclaredModulePaths, 
fsharpShadowedQualifiers(offset), name, target)
						}
					}
				}
				if file.Language == "Lua" {
					for name := range luaDottedCallIdentifiers(topLevel) {
						topLevelNames[name] = struct{}{}
					}
				}
				if file.Language == "Zig" {
					for name := range zigDottedCallIdentifiers(topLevel) {
						topLevelNames[name] = struct{}{}
					}
				}
				if file.Language == "Clojure" || file.Language == "ClojureScript" {
					for name := range clojureCallIdentifiers(topLevel) {
						topLevelNames[name] = struct{}{}
					}
				}
				if file.Language == "SQL" {
					for name := range sqlCallIdentifiers(topLevel) {
						topLevelNames[name] = struct{}{}
					}
				}
				if file.Language == "Ruby" {
					for name := range rubySuffixedCallIdentifiers(topLevel) {
						topLevelNames[name] = struct{}{}
					}
				}
				for _, name := range sortedKeysOf(topLevelNames) {
					inputs := pythonCallImportBinding(name, fileSource, file.Language, pythonBareScopes, symbolsByShortName, 
importsByName, file.Path, manifestImports, knownFiles, readContent)
					rawCandidates := inputs.rawCandidates
					rawImportModuleSets := inputs.rawImportModuleSets
					importsForCall := inputs.imports
					var pythonAliasTargets []resolvedCallTarget
					var pythonIncompleteAliasExternal []RelationRecord
					pythonGenericAllowed := inputs.genericAllowed
					if file.Language == "Python" {
						if pythonBareScopes.complete {
							pythonAliasTargets, _, _ = resolvePythonAliasImportTargets(name, fileSource, 
pythonBareScopes.importContexts(fileSource, name), symbolsByShortName, file.Path, manifestImports, knownFiles, 
readContent)
						} else {
							rawCandidates = nil
							if contexts := pythonIncompleteAliases[name]; len(contexts) > 0 {
								pythonIncompleteAliasExternal = pythonAliasExternalCallRelations(fileSource, contexts)
								pythonGenericAllowed = false
							}
						}
					}
					var targets []resolvedCallTarget
					if file.Language == "Python" && !pythonGenericAllowed {
						targets = nil
					} else if _, namespaceCall := jsNamespaceCalls[name]; namespaceCall {
						// Same chain as the per-symbol namespace path above; the
						// file-level pseudo-symbol has no self-call or member names
						// to exclude, so the terminal fallback is unguarded.
						targets = resolveJSNamespaceCallChain(name, fileSource, currentFileSymbols, jsSymbolNamespaces, 
symbolsByShortName, foreignJSNamespaceOf, nil)
					} else if quals := fsharpResolvableQualifiers(topLevelFSharpQualifiers[name]); len(quals) > 0 {
						// Same as the per-symbol path: each spelling resolves on its
						// own, so a statement-position `1 |> A.convert |> B.convert`
						// keeps both edges and a file that writes `convert(1)` as
						// well as `A.convert(2)` keeps both of those.
						seenTargets := map[string]bool{}
						for _, qualifier := range quals {
							for _, to := range resolveCallTargets(name, fileSource,
								fsharpQualifiedScope(symbolsByShortName[name], qualifier, "", fsharpModulePathBySymbolID, 
fsharpDeclaredModulePaths),
								fsharpQualifiedScope(currentFileSymbols, qualifier, "", fsharpModulePathBySymbolID, fsharpDeclaredModulePaths),
								importsByName, false) {
								if seenTargets[to.ID] {
									continue
								}
								seenTargets[to.ID] = true
								targets = append(targets, to)
							}
						}
					} else {
						targets = resolveCallTargetsWithRawImport(name, fileSource, sharedTypeCandidates(fileSource, 
symbolsByShortName[name]), rawCandidates, rawImportModuleSets, currentFileSymbols, importsForCall, false)
					}
					if file.Language == "Python" {
						targets = unionResolvedCallTargets(targets, pythonAliasTargets)
					}
					for _, to := range targets {
						if jsCallableArgumentOnly[name] && typeLikeKind(to.Kind) {
							continue
						}
						relType := "CALLS"
						if typeLikeKind(to.Kind) {
							relType = "CONSTRUCTS"
						}
						emit(RelationRecord{
							RecordType:    "relation",
							FromID:        fileSource.ID,
							ToID:          to.ID,
							Type:          relType,
							Confidence:    minFloat(to.Confidence, 0.8),
							Reason:        "top-level call expression resolved to symbol",
							RelationScope: to.Scope,
							Resolution:    to.Resolution,
							TargetKind:    "symbol",
							Evidence: []Evidence{{
								Kind:     "top_level_call_site",
								FilePath: file.Path,
								Detail:   name,
							}},
							WarningCodes: []string{},
						})
					}
					for _, relation := range pythonIncompleteAliasExternal {
						emit(relation)
					}
				}
			}
		}

		if needsTypes {
			for _, r := range typeRelationsForFile(repoKey, file, content, recordsByFile[file.Path], symbolsByFile[file.Path], 
symbolsByShortName) {
				if r.Type == "EXTENDS" || r.Type == "IMPLEMENTS" {
					result.inheritance = append(result.inheritance, r)
				}
				emit(r)
			}
		}
		if needsExtensionMembers {
			for _, r := range extensionMemberRelations(repoKey, recordsByFile[file.Path], symbolsByFile[file.Path], 
symbolsByShortName) {
				emit(r)
			}
		}
		return result
	}
	// Syntax-only resolves no content-derived relations, so it runs no scan at
	// all rather than starting workers that would each return nothing.
	if profileNeedsPerFileScan(spec) {
		scanErr := runIndexedStreamingPipeline(ctx, len(files), workers,
			func(workerCtx context.Context, index int, stream func(RelationRecord)) fileRelationScan {
				return resolveFileRelations(workerCtx, files[index], stream)
			},
			func(_ int, relation RelationRecord) error {
				if shouldStop != nil && shouldStop() {
					return errRelationScanStopped
				}
				emit(relation)
				return nil
			},
			func(index int, scanned fileRelationScan) error {
				if shouldStop != nil && shouldStop() {
					return errRelationScanStopped
				}
				if recordFailure != nil {
					for _, failure := range scanned.failures {
						recordFailure(failure)
					}
				}
				if scanned.resolvedImports != nil {
					resolvedImportsByFile[files[index].Path] = scanned.resolvedImports
				}
				for _, entry := range scanned.routeHandlers {
					routeHandlers[entry.route] = append(routeHandlers[entry.route], entry.handler)
				}
				for _, entry := range scanned.httpCalls {
					httpCallsByRoute[entry.route] = append(httpCallsByRoute[entry.route], entry.relation)
				}
				inheritanceEdges = append(inheritanceEdges, scanned.inheritance...)
				return nil
			})
		if scanErr != nil {
			return
		}
	}

	if needsOverrides {
		for _, r := range overrideRelations(inheritanceEdges, methodsByContainer) {
			if shouldStop != nil && shouldStop() {
				return
			}
			emit(r)
		}
	}
	if spec.emits("HANDLES_ROUTE") {
		for _, r := range crossFileExpressRouterRelations(files, recordsByFile, readContent, knownFiles) {
			if shouldStop != nil && shouldStop() {
				return
			}
			emit(r.Relation)
			routeHandlers[r.Route] = append(routeHandlers[r.Route], r.Handler)
		}
		for _, r := range pythonIncludeRouterRelations(files, recordsByFile, readContent, knownFiles) {
			if shouldStop != nil && shouldStop() {
				return
			}
			emit(r.Relation)
			routeHandlers[r.Route] = append(routeHandlers[r.Route], r.Handler)
		}
	}
	if spec.emits("CALLS") {
		for _, r := range routeBridgeRelations(routeHandlers, httpCallsByRoute) {
			if shouldStop != nil && shouldStop() {
				return
			}
			emit(r)
		}
		for _, r := range graphqlSchemaResolverRelations(graphqlSchemaFields, graphqlResolvers) {
			if shouldStop != nil && shouldStop() {
				return
			}
			emit(r)
		}
	}
	if spec.emits("USES_TYPE") {
		for _, r := range usesTypeRelations(recordsByFile, symbolsByFile, symbolsByShortName, resolvedImportsByFile) {
			if shouldStop != nil && shouldStop() {
				return
			}
			emit(r)
		}
	}
	if spec.emits("PARAM_TYPE") || spec.emits("RETURNS_TYPE") {
		for _, r := range signatureTypeRelations(recordsByFile, symbolsByFile, symbolsByShortName, resolvedImportsByFile, 
spec) {
			if shouldStop != nil && shouldStop() {
				return
			}
			emit(r)
		}
	}
	if spec.emits("TESTS") {
		for _, r := range testRelations(recordsByFile, symbolsByShortName, resolvedImportsByFile) {
			if shouldStop != nil && shouldStop() {
				return
			}
			emit(r)
		}
	}
	if spec.emits("RESOURCE_DEPENDS_ON") {
		for _, r := range resourceDependsOnRelations(recordsByRelationSupport(recordsByFile, "RESOURCE_DEPENDS_ON"), 
readContent) {
			if shouldStop != nil && shouldStop() {
				return
			}
			emit(r)
		}
	}
	if spec.emits("CONFIGURES") {
		for _, r := range configuresRelations(recordsByRelationSupport(recordsByFile, "CONFIGURES"), readContent) {
			if shouldStop != nil && shouldStop() {
				return
			}
			emit(r)
		}
	}
	if spec.emits("SIMILAR_TO") {
		for _, r := range similarityRelations(recordsByFile, readContent) {
			if shouldStop != nil && shouldStop() {
				return
			}
			emit(r)
		}
	}
}

func routeBridgeRelations(routeHandlers map[string][]SymbolRecord, httpCallsByRoute map[string][]RelationRecord) 
[]RelationRecord {
	var routes []string
	for route := range httpCallsByRoute {
		if len(routeHandlers[route]) > 0 {
			routes = append(routes, route)
		}
	}
	sort.Strings(routes)
	var relations []RelationRecord
	for _, route := range routes {
		handlers := append([]SymbolRecord(nil), routeHandlers[route]...)
		sort.Slice(handlers, func(i, j int) bool {
			return handlers[i].ID < handlers[j].ID
		})
		calls := append([]RelationRecord(nil), httpCallsByRoute[route]...)
		sort.Slice(calls, func(i, j int) bool {
			if calls[i].FromID == calls[j].FromID {
				return calls[i].ToID < calls[j].ToID
			}
			return calls[i].FromID < calls[j].FromID
		})
		for _, call := range calls {
			for _, handler := range handlers {
				if call.FromID == handler.ID {
					continue
				}
				confidence := minFloat(call.Confidence, 0.72)
				relations = append(relations, RelationRecord{
					RecordType:    "relation",
					FromID:        call.FromID,
					ToID:          handler.ID,
					Type:          "CALLS",
					Confidence:    confidence,
					Reason:        "HTTP client call resolved to local route handler through shared route endpoint",
					RelationScope: "workspace",
					Resolution:    "pattern",
					TargetKind:    "symbol",
					Evidence: []Evidence{{
						Kind:     "route_endpoint_match",
						FilePath: handler.FilePath,
						Detail:   route,
					}},
					WarningCodes: []string{},
				})
			}
		}
	}
	return relations
}

func graphqlSchemaResolverRelations(schemaFields, resolvers map[string][]SymbolRecord) []RelationRecord {
	var endpoints []string
	for endpoint := range schemaFields {
		if len(resolvers[endpoint]) > 0 {
			endpoints = append(endpoints, endpoint)
		}
	}
	sort.Strings(endpoints)
	var relations []RelationRecord
	for _, endpoint := range endpoints {
		fields := append([]SymbolRecord(nil), schemaFields[endpoint]...)
		sort.Slice(fields, func(i, j int) bool { return fields[i].ID < fields[j].ID })
		targets := append([]SymbolRecord(nil), resolvers[endpoint]...)
		sort.Slice(targets, func(i, j int) bool { return targets[i].ID < targets[j].ID })
		for _, field := range fields {
			for _, resolver := range targets {
				if field.ID == resolver.ID {
					continue
				}
				relations = append(relations, RelationRecord{
					RecordType:    "relation",
					FromID:        field.ID,
					ToID:          resolver.ID,
					Type:          "CALLS",
					Confidence:    0.9,
					Reason:        "GraphQL schema field resolved to local resolver map field",
					RelationScope: "workspace",
					Resolution:    "exact",
					TargetKind:    "symbol",
					Evidence: []Evidence{{
						Kind:     "graphql_schema_resolver_match",
						FilePath: resolver.FilePath,
						Detail:   endpoint,
					}},
					WarningCodes: []string{},
				})
			}
		}
	}
	return relations
}

func graphqlBoundaryEndpoint(symbol SymbolRecord, operationRootAliases map[string]string) string {
	switch symbol.Kind {
	case "graphql_schema_field", "graphql_resolver":
	default:
		return ""
	}
	fields := strings.Fields(symbol.Signature)
	if len(fields) < 4 {
		return ""
	}
	if fields[0] != "GraphQL" {
		return ""
	}
	switch symbol.Kind {
	case "graphql_schema_field":
		if fields[1] != "schema" {
			return ""
		}
	case "graphql_resolver":
		if fields[1] != "resolver" {
			return ""
		}
	}
	typeName := strings.ToLower(fields[2])
	if typeName == "" {
		return ""
	}
	if operationRootAliases != nil {
		if alias := operationRootAliases[typeName]; alias != "" {
			typeName = alias
		}
	}
	name := strings.TrimSpace(fields[3])
	if name == "" {
		return ""
	}
	return typeName + " " + name
}

func graphqlRootNameFromSignature(symbol SymbolRecord) string {
	fields := strings.Fields(symbol.Signature)
	if len(fields) < 4 || fields[0] != "GraphQL" {
		return ""
	}
	return strings.ToLower(fields[2])
}

// typeRelationsForFile emits EXTENDS/IMPLEMENTS relations for the type symbols
// in a file. Most languages declare supertypes in the class/interface header,
// which the parser captured in the symbol signature; Rust states them in impl
// blocks and supertrait bounds, scanned from content. Each supertype is
// resolved to a local type symbol when possible, otherwise to an external type
// endpoint.
func typeRelationsForFile(repoKey string, file FileRecord, content string, fileSymbols, sameFileSymbols 
[]SymbolRecord, symbolsByShortName map[string][]SymbolRecord) []RelationRecord {
	var relations []RelationRecord
	for _, symbol := range fileSymbols {
		if !typeLikeKind(symbol.Kind) {
			continue
		}
		for _, edge := range supertypesFromSignature(symbol.Language, symbol.Signature) {
			relations = append(relations, buildTypeRelation(repoKey, symbol, edge.Super, edge.Relation, edge.Confidence, 
sameFileSymbols, symbolsByShortName))
			if edge.Relation == "EXTENDS" {
				relations = append(relations, buildTypeRelation(repoKey, symbol, edge.Super, "INHERITS", edge.Confidence, 
sameFileSymbols, symbolsByShortName))
			}
		}
	}
	// Horizontal member reuse stated in the type BODY, not its header: a PHP
	// `use SomeTrait;` or a Ruby `include SomeModule`. Without this edge the
	// members a class really answers to are unreachable from the class, which
	// is the same join failure as an unlinked impl block.
	if file.Language == "PHP" || file.Language == "Ruby" {
		lines := strings.Split(content, "
")
		for _, symbol := range fileSymbols {
			if !typeLikeKind(symbol.Kind) {
				continue
			}
			body := directTypeBodyLines(lines, symbol, fileSymbols)
			for _, edge := range mixinSupertypeEdges(symbol.Language, body) {
				relations = append(relations, buildMixinRelation(repoKey, symbol, edge, sameFileSymbols, symbolsByShortName))
			}
		}
	}
	if file.Language == "Rust" {
		for _, edge := range rustSupertypeEdges(content) {
			anchor, ok := firstTypeLikeNamed(fileSymbols, edge.Anchor)
			if !ok {
				continue
			}
			relations = append(relations, buildTypeRelation(repoKey, anchor, edge.Super, edge.Relation, edge.Confidence, 
sameFileSymbols, symbolsByShortName))
			if edge.Relation == "EXTENDS" {
				relations = append(relations, buildTypeRelation(repoKey, anchor, edge.Super, "INHERITS", edge.Confidence, 
sameFileSymbols, symbolsByShortName))
			}
		}
	}
	return relations
}

// buildMixinRelation resolves a body-stated member-acquisition edge (a PHP trait
// `use`, a Ruby `include`) to its declaration.
//
// It cannot go through buildTypeRelation, for two reasons the languages force:
// the supplier of the members is often a MODULE (Ruby), which is not a type-like
// kind, and short-name resolution across the whole workspace is not
// language-aware — a Ruby `include Ranged` would happily bind to a Rust trait
// called `Ranged` in the same repo, which is a confidently wrong edge. Candidates
// are therefore restricted to the same language, and an unresolved supplier
// becomes an external endpoint exactly as elsewhere.
func buildMixinRelation(repoKey string, anchor SymbolRecord, edge rawSupertype, sameFileSymbols []SymbolRecord, 
symbolsByShortName map[string][]SymbolRecord) RelationRecord {
	accepts := func(symbol SymbolRecord) bool {
		return symbol.Name == edge.Super && symbol.ID != anchor.ID &&
			symbol.Language == anchor.Language &&
			(typeLikeKind(symbol.Kind) || symbol.Kind == "module")
	}
	toID := externalID("type", edge.Super)
	targetKind, resolution, scope := "external", "name_only", "external"
	confidence := minFloat(edge.Confidence, 0.8)
	for _, symbol := range sameFileSymbols {
		if accepts(symbol) {
			toID, targetKind, resolution, scope, confidence = symbol.ID, "symbol", "exact", "file", edge.Confidence
			break
		}
	}
	if targetKind == "external" {
		for _, symbol := range sharedTypeCandidates(anchor, symbolsByShortName[edge.Super]) {
			if accepts(symbol) {
				toID, targetKind, resolution, scope, confidence = symbol.ID, "symbol", "name_only", "module", 
minFloat(edge.Confidence, 0.85)
				break
			}
		}
	}
	return RelationRecord{
		RecordType:    "relation",
		FromID:        anchor.ID,
		ToID:          toID,
		Type:          edge.Relation,
		Confidence:    confidence,
		Reason:        typeRelationReason(edge.Relation, resolution),
		RelationScope: scope,
		Resolution:    resolution,
		TargetKind:    targetKind,
		Evidence: []Evidence{{
			Kind:      "mixin_declaration",
			FilePath:  anchor.FilePath,
			StartLine: anchor.StartLine,
			EndLine:   anchor.EndLine,
			Detail:    edge.Super,
		}},
		WarningCodes: []string{},
	}
}

// partialTypeCanonicalIDs maps every declaration of a partial type to the one
// that stands for the whole type — the first part in file order. C# (and F#)
// let a single type be written as several `partial` declarations; each parses
// as its own symbol, so a member's container was whichever part happened to
// declare it and the type's member set was split across parts. Callers rewrite
// member containers through this map so the type has one member set again.
//
// Parts are matched on kind + qualified name + language, and ONLY when the
// declaration says `partial`: two same-named classes that are not partial are
// two different types (different namespaces, different assemblies) and must
// stay separate. The second return value gives each canonical part's file, so
// callers can scope a cross-file CONTAINS edge correctly.
func partialTypeCanonicalIDs(files []FileRecord, recordsByFile map[string][]SymbolRecord) (map[string]string, 
map[string]string) {
	canonicalByKey := map[string]SymbolRecord{}
	var parts []SymbolRecord
	for _, file := range files {
		for _, symbol := range recordsByFile[file.Path] {
			if !typeLikeKind(symbol.Kind) || !declaresPartialType(symbol) {
				continue
			}
			key := symbol.Language + "\x00" + symbol.Kind + "\x00" + symbol.QualifiedName
			parts = append(parts, symbol)
			if existing, ok := canonicalByKey[key]; !ok ||
				symbol.FilePath < existing.FilePath ||
				(symbol.FilePath == existing.FilePath && symbol.StartLine < existing.StartLine) {
				canonicalByKey[key] = symbol
			}
		}
	}
	if len(parts) == 0 {
		return nil, nil
	}
	canonical := make(map[string]string, len(parts))
	canonicalFile := make(map[string]string, len(canonicalByKey))
	for _, symbol := range parts {
		key := symbol.Language + "\x00" + symbol.Kind + "\x00" + symbol.QualifiedName
		anchor := canonicalByKey[key]
		canonical[symbol.ID] = anchor.ID
		canonicalFile[anchor.ID] = anchor.FilePath
	}
	return canonical, canonicalFile
}

// declaresPartialType reports whether a type symbol's declaration carries the
// `partial` modifier, read from the signature the parser captured.
func declaresPartialType(symbol SymbolRecord) bool {
	if symbol.Language != "C#" && symbol.Language != "F#" {
		return false
	}
	for _, field := range strings.Fields(stripGenerics(symbol.Signature)) {
		if field == "partial" {
			return true
		}
	}
	return false
}

// extensionMemberRelations emits the membership edge for callables declared
// outside the type they extend: C# `static bool IsEmpty(this Edit edit)` and
// Kotlin `fun Edit.isEmpty()`. Their container_id points at the static class or
// the file, which is where they are WRITTEN — so the type's own member set was
// missing them, and a caller asking what a value of that type supports got an
// incomplete answer that looked complete.
//
// The edge is CONTAINS with relation_scope "extension", so consumers can tell an
// acquired member from a declared one, and `neighbors --symbol T --relation
// CONTAINS --direction out` returns the whole surface either way. The receiver
// type is resolved same-file first (the usual case: extensions ship beside the
// type) and then through the workspace short-name index; unresolvable receivers
// emit nothing rather than an external endpoint, because a membership edge to a
// type the graph never saw cannot be navigated.
func extensionMemberRelations(repoKey string, fileSymbols, sameFileSymbols []SymbolRecord, symbolsByShortName 
map[string][]SymbolRecord) []RelationRecord {
	var relations []RelationRecord
	for _, symbol := range fileSymbols {
		if symbol.Kind != "function" && symbol.Kind != "method" && symbol.Kind != "property" {
			continue
		}
		receiver := extensionReceiverTypeName(symbol.Language, symbol.Signature)
		if receiver == "" {
			continue
		}
		// Same-language only: a Kotlin `fun Edit.isEmpty()` must not attach to a
		// Rust struct that happens to also be called Edit.
		target, ok := firstTypeLikeNamedInLanguage(sameFileSymbols, receiver, symbol.Language)
		resolution, confidence := "exact", 0.9
		if !ok || target.ID == symbol.ID {
			target, ok = firstTypeLikeNamedInLanguage(symbolsByShortName[receiver], receiver, symbol.Language)
			resolution, confidence = "name_only", 0.8
		}
		if !ok || target.ID == symbol.ID || target.ID == symbol.ContainerID {
			continue
		}
		relations = append(relations, RelationRecord{
			RecordType:    "relation",
			FromID:        target.ID,
			ToID:          symbol.ID,
			Type:          "CONTAINS",
			Confidence:    confidence,
			Reason:        "extension member declared on the receiver type",
			RelationScope: "extension",
			Resolution:    resolution,
			TargetKind:    "symbol",
			Evidence: []Evidence{{
				Kind:      "extension_receiver",
				FilePath:  symbol.FilePath,
				StartLine: symbol.StartLine,
				EndLine:   symbol.EndLine,
				Detail:    receiver,
			}},
			WarningCodes: []string{},
		})
	}
	return relations
}

func buildTypeRelation(repoKey string, anchor SymbolRecord, super, relation string, baseConfidence float64, 
sameFileSymbols []SymbolRecord, symbolsByShortName map[string][]SymbolRecord) RelationRecord {
	toID := externalID("type", super)
	targetKind, resolution, scope := "external", "name_only", "external"
	confidence := minFloat(baseConfidence, 0.8)
	if sym, ok := firstTypeLikeNamed(sameFileSymbols, super); ok && sym.ID != anchor.ID {
		toID, targetKind, resolution, scope, confidence = sym.ID, "symbol", "exact", "file", baseConfidence
	} else if sym, ok := firstTypeLikeNamed(sharedTypeCandidates(anchor, symbolsByShortName[super]), super); ok && sym.ID 
!= anchor.ID {
		toID, targetKind, resolution, scope, confidence = sym.ID, "symbol", "name_only", "module", minFloat(baseConfidence, 
0.85)
	}
	return RelationRecord{
		RecordType:    "relation",
		FromID:        anchor.ID,
		ToID:          toID,
		Type:          relation,
		Confidence:    confidence,
		Reason:        typeRelationReason(relation, resolution),
		RelationScope: scope,
		Resolution:    resolution,
		TargetKind:    targetKind,
		Evidence: []Evidence{{
			Kind:      "type_declaration",
			FilePath:  anchor.FilePath,
			StartLine: anchor.StartLine,
			EndLine:   anchor.EndLine,
			Detail:    super,
		}},
		WarningCodes: []string{},
	}
}

// receiverCallRelations resolves `receiver.method()` calls inside a caller's
// body to the target method symbol by inferring the receiver's type. Supported
// cases are this/self receivers, typed parameters, constructor assignments, and
// same-file variables assigned from a factory with an explicit local return
// type. These calls are otherwise dropped (a name preceded by '.'/'->' is not a
// plain call), so this is purely additive. Type containers are skipped as
// callers — calls live in methods/functions, not in the class declaration.
// lookupMethodUpChain finds a method by name starting in the given container and,
// failing that, walking up the superclass chain (superContainerByID). It returns
// the method, whether it was found on an ancestor rather than the start container,
// and ok. A visited set guards against inheritance cycles from misparsed headers;
// the chain is single-inheritance so the first hit is the resolution-order target.
func lookupMethodUpChain(start, name string, methodsByContainer map[string]map[string]SymbolRecord, superContainerByID 
map[string]string) (SymbolRecord, bool, bool) {
	seen := map[string]bool{}
	for c, hops := start, 0; c != "" && !seen[c] && hops < 32; c, hops = superContainerByID[c], hops+1 {
		seen[c] = true
		if m, ok := methodsByContainer[c][name]; ok {
			return m, hops > 0, true
		}
	}
	return SymbolRecord{}, false, false
}

func typeScriptReceiverTypeResolvesElsewhere(typeName string, from SymbolRecord, importsByName map[string][]string, 
symbolsByShortName map[string][]SymbolRecord, superContainerByID map[string]string) bool {
	if constraint, generic := typeScriptGenericTypeConstraints(from.Signature)[typeName]; generic {
		if constraint == "" {
			return false
		}
		typeName = constraint
	}
	if len(importsByName[typeName]) > 0 {
		return true
	}
	for _, candidate := range sharedTypeCandidates(from, symbolsByShortName[typeName]) {
		if !typeLikeKind(candidate.Kind) || candidate.FilePath != from.FilePath {
			continue
		}
		if !containerChainContains(from.ContainerID, candidate.ID, superContainerByID) {
			return true
		}
	}
	return false
}

// typeScriptGenericTypeConstraints maps method/function type parameters to the
// first named type in their constraint. Presence with an empty value records an
// unconstrained (or structurally constrained) generic. Receiver resolution
// must consult this lexical binding before a coincidentally same-named
// workspace type (`run<T>(item: T)` beside `interface T {}`).
func typeScriptGenericTypeConstraints(signature string) map[string]string {
	out := map[string]string{}
	open := strings.IndexByte(signature, '<')
	firstParen := strings.IndexByte(signature, '(')
	if open < 0 || (firstParen >= 0 && open > firstParen) {
		return out
	}
	depth := 0
	close := -1
	for index := open; index < len(signature); index++ {
		switch signature[index] {
		case '<':
			depth++
		case '>':
			if index > open && signature[index-1] == '=' {
				continue
			}
			depth--
			if depth == 0 {
				close = index
			}
		}
		if close >= 0 {
			break
		}
	}
	if close <= open {
		return out
	}
	for _, clause := range splitTypeScriptGenericClauses(signature[open+1 : close]) {
		clause = strings.TrimSpace(clause)
		if clause == "" || !(clause[0] == '_' || clause[0] == '$' || clause[0] >= 'A' && clause[0] <= 'Z' || clause[0] >= 
'a' && clause[0] <= 'z') {
			continue
		}
		nameEnd := 1
		for nameEnd < len(clause) && isASCIIIdentifierByte(clause[nameEnd]) {
			nameEnd++
		}
		name := clause[:nameEnd]
		out[name] = ""
		rest := strings.TrimSpace(clause[nameEnd:])
		if !strings.HasPrefix(rest, "extends ") {
			continue
		}
		constraint := strings.TrimSpace(strings.TrimPrefix(rest, "extends "))
		if constraint == "" || !(constraint[0] == '_' || constraint[0] == '$' || constraint[0] >= 'A' && constraint[0] <= 
'Z' || constraint[0] >= 'a' && constraint[0] <= 'z') {
			continue
		}
		end := 0
		for end < len(constraint) {
			ch := constraint[end]
			if isASCIIIdentifierByte(ch) || ch == '.' {
				end++
				continue
			}
			break
		}
		if end > 0 {
			out[name] = lastTypeSegment(constraint[:end])
		}
	}
	return out
}

func splitTypeScriptGenericClauses(clause string) []string {
	var out []string
	start := 0
	angleDepth, parenDepth, bracketDepth, braceDepth := 0, 0, 0, 0
	for index := 0; index < len(clause); index++ {
		switch clause[index] {
		case '<':
			angleDepth++
		case '>':
			if angleDepth > 0 {
				angleDepth--
			}
		case '(':
			parenDepth++
		case ')':
			if parenDepth > 0 {
				parenDepth--
			}
		case '[':
			bracketDepth++
		case ']':
			if bracketDepth > 0 {
				bracketDepth--
			}
		case '{':
			braceDepth++
		case '}':
			if braceDepth > 0 {
				braceDepth--
			}
		case ',':
			if angleDepth == 0 && parenDepth == 0 && bracketDepth == 0 && braceDepth == 0 {
				out = append(out, clause[start:index])
				start = index + 1
			}
		}
	}
	out = append(out, clause[start:])
	return out
}

func containerChainContains(start, target string, superContainerByID map[string]string) bool {
	seen := map[string]bool{}
	for c, hops := start, 0; c != "" && !seen[c] && hops < 32; c, hops = superContainerByID[c], hops+1 {
		if c == target {
			return true
		}
		seen[c] = true
	}
	return false
}

func uniqueImplementedMethod(start, name string, methodsByContainer map[string]map[string]SymbolRecord, 
superContainerByID map[string]string, implementersByContainer map[string][]string) (SymbolRecord, bool) {
	seenContainers := map[string]bool{}
	seenMethods := map[string]bool{}
	var out SymbolRecord
	var walk func(string, int) bool
	walk = func(container string, depth int) bool {
		if container == "" || depth > 16 || seenContainers[container] {
			return true
		}
		seenContainers[container] = true
		for _, impl := range implementersByContainer[container] {
			if method, _, ok := lookupMethodUpChain(impl, name, methodsByContainer, superContainerByID); ok {
				if !seenMethods[method.ID] {
					if out.ID != "" {
						return false
					}
					out = method
					seenMethods[method.ID] = true
				}
			}
			if !walk(impl, depth+1) {
				return false
			}
		}
		return true
	}
	if !walk(start, 0) || out.ID == "" {
		return SymbolRecord{}, false
	}
	return out, true
}

// resolveContainerAcrossFiles resolves a member's container name to a
// type-like symbol when per-file linking left the member orphaned. Preference
// order keeps it conservative: a unique same-file type (per-file linking can
// miss a container declared after its member), then a unique same-directory
// type (a Go package — where methods routinely live in sibling files of their
// receiver type — is a directory), then a workspace-unique type. Ambiguity at
// the first populated tier resolves to nothing rather than wrongly.
func resolveContainerAcrossFiles(name, file string, typesByShortName map[string][]SymbolRecord) (SymbolRecord, bool) {
	candidates := typesByShortName[name]
	if len(candidates) == 0 {
		return SymbolRecord{}, false
	}
	dir := filepath.ToSlash(filepath.Dir(file))
	var sameFile, sameDir []SymbolRecord
	for _, candidate := range candidates {
		switch {
		case candidate.FilePath == file:
			sameFile = append(sameFile, candidate)
		case filepath.ToSlash(filepath.Dir(candidate.FilePath)) == dir:
			sameDir = append(sameDir, candidate)
		}
	}
	for _, tier := range [][]SymbolRecord{sameFile, sameDir, candidates} {
		if len(tier) == 1 {
			return tier[0], true
		}
		if len(tier) > 1 {
			return SymbolRecord{}, false
		}
	}
	return SymbolRecord{}, false
}

// pkgQualType is a package-qualified type reference (alias.TypeName), used to
// resolve method calls on package-level vars whose bare type name is ambiguous
// across packages (e.g. zerolog's `enc = json.Encoder{}` where both internal/json
// and internal/cbor define an Encoder with the same methods).
type pkgQualType struct {
	alias    string
	typeName string
}

// pkgQualVarRe matches a package-level composite-literal var assignment:
//
//	enc = json.Encoder{...}   /   var enc = &json.Encoder{...}
var pkgQualVarRe = regexp.MustCompile(`^[ 	]*(?:var\s+)?([A-Za-z_]\w*)\s*=\s*&?([a-z]\w[\w]*)\.([A-Z]\w*)\s*\{`)

// collectPackageVarTypes scans a Go file's package-level (brace-depth 0)
// declarations for package-qualified composite literals and returns
// name -> {alias, type}. Brace depth skips function bodies; the legacy
// `var ( ... )` block uses parens, so its entries stay at depth 0.
func collectPackageVarTypes(content string) map[string]pkgQualType {
	stripped := stripCodeLiteralsAndComments(content)
	out := map[string]pkgQualType{}
	depth := 0
	for _, line := range strings.Split(stripped, "
") {
		if depth == 0 {
			if m := pkgQualVarRe.FindStringSubmatch(line); m != nil {
				out[m[1]] = pkgQualType{alias: m[2], typeName: m[3]}
			}
		}
		depth += strings.Count(line, "{") - strings.Count(line, "}")
		if depth < 0 {
			depth = 0
		}
	}
	return out
}

// resolveQualifiedType picks the type-like symbol for a package-qualified
// reference by the Go convention that a package's import alias equals its
// directory basename (json.Encoder -> the Encoder in .../json/). Requires a
// unique match so an ambiguous alias resolves to nothing rather than wrongly.
func resolveQualifiedType(from SymbolRecord, qt pkgQualType, symbolsByShortName map[string][]SymbolRecord) 
(SymbolRecord, bool) {
	var match SymbolRecord
	found := 0
	for _, cand := range sharedTypeCandidates(from, symbolsByShortName[qt.typeName]) {
		if !typeLikeKind(cand.Kind) {
			continue
		}
		if filepath.Base(filepath.Dir(filepath.ToSlash(cand.FilePath))) == qt.alias {
			match = cand
			found++
		}
	}
	if found == 1 {
		return match, true
	}
	return SymbolRecord{}, false
}

func receiverCallRelations(from SymbolRecord, body symbolBody, methodsByContainer map[string]map[string]SymbolRecord, 
superContainerByID map[string]string, implementersByContainer map[string][]string, symbolsByShortName 
map[string][]SymbolRecord, returnTypesBySymbolNameAndFile, returnTypesBySymbolNameAndDir 
map[string]map[string][]string, importsByName map[string][]string, goModule string, pkgVarTypes 
map[string]pkgQualType, phpPropTypes, kotlinPropTypes, typeScriptPropTypes map[string]string, fieldsByContainer 
map[string]map[string]SymbolRecord, swiftTypes swiftFileTypes) []RelationRecord {
	if typeLikeKind(from.Kind) {
		return nil
	}
	if from.Language == "C#" {
		// Multi-line verbatim (@"...") and raw ("""...""") string bodies pass
		// through the generic stripper (which contains string masking to one
		// line), so SQL/text blocks would feed every extractor below.
		body = body.masked(maskCSharpTextBlocks(body.text))
	}
	if from.Language == "Swift" {
		// Multiline string bodies ("""...""") likewise span lines and would
		// feed every extractor below through the line-scoped generic stripper.
		body = body.masked(maskSwiftMultilineStrings(body.text))
	}
	// The language-specific scanners below take the text and strip it their own
	// way, behind their own masks. Only the generic ones share body's copy.
	block := body.text
	calls := receiverCalls(body)
	allReceiverCalls := calls
	if from.Language == "Dart" {
		// Dart property assignment invokes a setter method when one exists
		// (`request.bodyFields = bodyFields` calls `set bodyFields(...)`), but
		// the generic receiver scanner only sees parenthesized calls.
		calls = mergeReceiverCalls(calls, dartSetterAssignmentCalls(block))
	}
	if from.Language == "C#" {
		// Chain tails (`Dependencies.MigrationsSqlGenerator.Generate(`) look
		// like `MigrationsSqlGenerator.Generate(` to the generic scanner, and
		// the typed tiers misresolve them — EF Core names properties after
		// their concrete type, so the static-call tier hits that class instead
		// of the property's interface. The typed tiers get only clean-receiver
		// calls; the chain loop below resolves the tails, and the extension
		// fallback — receiver-agnostic by construction — sees every pair.
		calls = csharpNonTailReceiverCalls(block)
	}
	chainedCalls := chainedConstructorCalls(body)
	returnedCalls := returnedReceiverCalls(body)
	chainedReturnCalls := chainedConstructorReturnCalls(body)
	deepChainedReturnCalls := chainedConstructorDeepReturnCalls(body)
	returnedChainCalls := returnedReceiverChainCalls(body)
	returnedDeepChainCalls := returnedReceiverDeepChainCalls(body)
	var rubyBareCalls []string
	if from.Language == "Ruby" {
		// Ruby call sites often omit parentheses and method names may end in
		// `!`/`?`; the generic extractors above miss both, and constructor
		// chains are spelled `Klass.new(...).method` rather than `new Klass()`.
		calls = mergeReceiverCalls(calls, rubyReceiverCalls(block))
		chainedCalls = append(chainedCalls, rubyChainedConstructorCalls(block)...)
		rubyBareCalls = rubyBareCallNames(block, from.Signature)
	}
	var kotlinChains []kotlinChainedCall
	if from.Language == "Kotlin" {
		// Kotlin safe calls (`socket?.closeQuietly()`) and trailing-lambda
		// invocations (`taskQueue.execute { ... }`) never match the generic
		// receiverCallRe, which requires a literal `.` and a literal `(`.
		// Chained receivers (`call.application.resolveResource(...)`) carry a
		// property hop the flat scanner misreads as an unknown receiver.
		calls = mergeReceiverCalls(calls, kotlinReceiverCalls(block))
		kotlinChains = kotlinChainedReceiverCalls(block)
	}
	var swiftChains []swiftChainedCall
	if from.Language == "Swift" {
		// Force-unwrapped (`self._buffer!.discardReadBytes()`) and
		// optional-chained (`delegate?.retry(...)`) receivers never match the
		// generic receiverCallRe, which requires a literal `.` directly after
		// the receiver name. Property-chain receivers
		// (`request.fileio.streamFile(...)`, often spelled across lines) carry
		// a property hop the flat scanner misreads as an unknown receiver.
		calls = mergeReceiverCalls(calls, swiftReceiverCalls(block))
		swiftChains = swiftChainedReceiverCalls(block)
	}
	var javaChains []javaCtorChainCall
	if from.Language == "Java" {
		// Nested-type fluent constructor chains
		// (`new Retrofit.Builder().baseUrl(...).build()`): the generic chain
		// regexes handle neither the dotted type nor arbitrary chain depth with
		// nested call arguments.
		javaChains = javaConstructorChainCalls(block)
	}
	if from.Language == "Objective-C" {
		// Objective-C message sends use bracket syntax (`[self setState:...]`),
		// not `receiver.method(...)`, so the generic receiver scanner never sees
		// intra-class selector calls.
		objcCalls := objectiveCMessageReceiverCalls(block)
		calls = mergeReceiverCalls(calls, objcCalls)
		allReceiverCalls = mergeReceiverCalls(allReceiverCalls, objcCalls)
	}
	var phpStatics []phpStaticCall
	var phpPropCalls []receiverCall
	var phpFactoryChains []phpPropertyFactoryChainCall
	var rustPathCalls []rustPathCall
	if from.Language == "PHP" {
		// PHP static calls use `::` (never matched by receiverCallRe) and
		// constructor chains are spelled `(new Klass(...))->m(` rather than
		// `new Klass().m(`; property receivers resolve through the class-level
		// property types the caller collected from this file.
		phpStatics = phpStaticCalls(block)
		phpPropCalls = phpPropertyReceiverCalls(block)
		phpFactoryChains = phpPropertyFactoryChainCalls(block)
		chainedCalls = append(chainedCalls, phpChainedConstructorCalls(block)...)
	}
	if from.Language == "Rust" {
		// Rust module calls (`strings::index_of(...)`) are not receiver calls:
		// the left side is a `use`-bound module alias, not a value. Resolve them
		// through Rust import bindings and Cargo/module alias resolution.
		rustPathCalls = rustModulePathCalls(block)
	}
	if from.Language == "Perl" {
		// Perl method calls commonly omit parentheses (`$self->stash`,
		// `$base->protocol`), which the generic receiver scanner never sees.
		calls = mergeReceiverCalls(calls, perlReceiverCalls(block))
	}
	var csChainCalls []csharpChainCall
	if from.Language == "C#" {
		// One-hop member chains (`Dependencies.ModelDiffer.GetDifferences(`)
		// are matched by receiverCallRe as `ModelDiffer.GetDifferences(`, an
		// untypeable receiver; the dedicated extractor keeps the full chain so
		// class-level member types can resolve it hop by hop.
