			if emitted[key] {
				continue
			}
			emitted[key] = true
			relations = append(relations, RelationRecord{
				RecordType:    "relation",
				FromID:        source.ID,
				ToID:          target.ID,
				Type:          "RESOURCE_DEPENDS_ON",
				Confidence:    minFloat(dep.Confidence+0.08, 0.9),
