var (
	laravelRouteRegistrationsArrayRe  = regexp.MustCompile(`(?is) Route::(?:get|post|put|patch|delete|options|any)\s*\(\s
*["']([^"']+)["']\s*,\s*\[\s*([A-Za-z_\][A-Za-z0-9_\]*)::class\s*,\s*["']([A-Za-z_][A-Za-z0-9_]*)["']\s*\]`)
	laravelRouteRegistrationsStringRe = regexp.MustCompile(`(?is) Route::(?:get|post|put|patch|delete|options|any)\s*\(\s
*["']([^"']+)["']\s*,\s*["']([A-Za-z_\][A-Za-z0-9_\]*)@([A-Za-z_][A-Za-z0-9_]*)["']`)
)

func laravelRouteRegistrations(content string) []laravelRouteRegistration {
	var registrations []laravelRouteRegistration
	add := func(route, controller, method, evidence string) {
		route = normalizeSlashRoute(route)
		controller = shortQualifiedName(strings.TrimSpace(controller))
		if route == "" || controller == "" || method == "" {
			return
		}
		registrations = append(registrations, laravelRouteRegistration{
			Route:        route,
			Controller:   controller,
			Method:       method,
			EvidenceKind: evidence,
			Detail:       route + " -> " + controller + "." + method,
		})
	}
	scan := func(body, prefix, evidenceSuffix string) {
		for _, match := range laravelRouteRegistrationsArrayRe.FindAllStringSubmatch(body, -1) {
			if len(match) == 4 {
				add(joinRoutePaths(prefix, match[1]), match[2], match[3], "laravel_route_controller_array"+evidenceSuffix)
			}
		}
		for _, match := range laravelRouteRegistrationsStringRe.FindAllStringSubmatch(body, -1) {
			if len(match) == 4 {
				add(joinRoutePaths(prefix, match[1]), match[2], match[3], "laravel_route_controller_string"+evidenceSuffix)
			}
		}
	}
	topLevel, groups := laravelPrefixGroups(content)
	scan(topLevel, "", "")
	for _, group := range groups {
		scan(group.Body, group.Prefix, "_prefix_group")
	}
	for _, group := range laravelControllerGroups(content) {
		for _, match := range laravelControllerGroupMethodRouteRe().FindAllStringSubmatch(group.Body, -1) {
			if len(match) == 3 {
				add(joinRoutePaths(group.Prefix, match[1]), group.Controller, match[2], "laravel_route_controller_group")
			}
		}
	}
	return registrations
}

type laravelPrefixGroup struct {
	Prefix string
	Body   string
}

type laravelControllerGroup struct {
	Prefix     string
	Controller string
	Body       string
}

var laravelPrefixGroupsRe = regexp.MustCompile(`(?is)Route::prefix\s*\(\s*["']([^"']+)["']\s*\)\s*->\s*group\s*\(\s*fun
ction\s*\(\)\s*\{(.*?)\}\s*\);`)

func laravelPrefixGroups(content string) (string, []laravelPrefixGroup) {
	var groups []laravelPrefixGroup
	top := laravelPrefixGroupsRe.ReplaceAllStringFunc(content, func(block string) string {
		match := laravelPrefixGroupsRe.FindStringSubmatch(block)
		if len(match) == 3 {
			groups = append(groups, laravelPrefixGroup{Prefix: normalizeSlashRoute(match[1]), Body: match[2]})
		}
		return ""
	})
	return top, groups
}

var (
	laravelControllerGroupsRe           = regexp.MustCompile(`(?is) Route::((?:(?:prefix|controller)\s*\([^)]*\)\s*->\s*)
+)group\s*\(\s*function\s*\(\)\s*\{(.*?)\}\s*\);`)
	laravelControllerGroupsPrefixRe     = regexp.MustCompile(`(?is) prefix\s*\(\s*["']([^"']+)["']\s*\)`)
	laravelControllerGroupsControllerRe = 
regexp.MustCompile(`(?is) controller\s*\(\s*([A-Za-z_\][A-Za-z0-9_\]*)::class\s*\)`)
)

func laravelControllerGroups(content string) []laravelControllerGroup {
	var groups []laravelControllerGroup
	for _, match := range laravelControllerGroupsRe.FindAllStringSubmatch(content, -1) {
		if len(match) != 3 {
			continue
		}
		chain, body := match[1], match[2]
		controllerMatch := laravelControllerGroupsControllerRe.FindStringSubmatch(chain)
		if len(controllerMatch) != 2 {
			continue
		}
		prefix := "/"
		if prefixMatch := laravelControllerGroupsPrefixRe.FindStringSubmatch(chain); len(prefixMatch) == 2 {
			prefix = normalizeSlashRoute(prefixMatch[1])
		}
		groups = append(groups, laravelControllerGroup{
			Prefix:     prefix,
			Controller: controllerMatch[1],
			Body:       body,
		})
	}
	return groups
}

var laravelControllerGroupMethodRouteReRe = regexp.MustCompile(`(?is) Route::(?:get|post|put|patch|delete|options|any)
\s*\(\s*["']([^"']+)["']\s*,\s*["']([A-Za-z_][A-Za-z0-9_]*)["']`)

func laravelControllerGroupMethodRouteRe() *regexp.Regexp {
	return laravelControllerGroupMethodRouteReRe
}

