func kubernetesResourceReferences(content string) []resourceReference {
	var refs []resourceReference
	metadata := yamlMapAtPath(content, "metadata")
	resourceNamespace := strings.TrimSpace(metadata["namespace"])
	add := func(kind, name, evidence string, confidence float64) {
		name = strings.Trim(strings.TrimSpace(name), `"'`)
		if name == "" {
			return
		}
		refs = append(refs, resourceReference{Kind: strings.ToLower(kind), Name: name, EvidenceKind: evidence, Confidence: 
confidence})
		if resourceNamespace != "" && kubernetesNamespacedReferenceKind(kind) {
			refs = append(refs, resourceReference{Kind: strings.ToLower(kind), Name: name, ExternalName: resourceNamespace + 
"/" + name, EvidenceKind: evidence, Confidence: confidence})
		}
	}
	if len(metadata) > 0 {
		if namespace := metadata["namespace"]; namespace != "" {
			add("namespace", namespace, "kubernetes_metadata_namespace", 0.84)
		}
	}
	for _, match := range kubernetesResourceReferencesRe.FindAllStringSubmatch(content, -1) {
		add("configmap", match[1], "kubernetes_configmap_ref", 0.8)
	}
	for _, match := range kubernetesResourceReferencesRe2.FindAllStringSubmatch(content, -1) {
		add("configmap", match[1], "kubernetes_configmap_key_ref", 0.8)
	}
