var (
	kustomizeFileReferencesRe  = regexp.MustCompile(`^(resources|patches|components):\s*$`)
	kustomizeFileReferencesRe2 = regexp.MustCompile(`^[A-Za-z0-9_-]+:`)
)

func kustomizeFileReferences(content string) []string {
	var refs []string
	inList := false
	for _, line := range strings.Split(content, "
") {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}
		switch {
		case kustomizeFileReferencesRe.MatchString(trimmed):
			inList = true
			continue
		case kustomizeFileReferencesRe2.MatchString(trimmed):
			inList = false
		}
		if !inList || !strings.HasPrefix(trimmed, "-") {
			continue
		}
		ref := strings.TrimSpace(strings.TrimPrefix(trimmed, "-"))
		ref = strings.Trim(ref, `"'`)
		if ref != "" {
			refs = append(refs, ref)
		}
	}
	sort.Strings(refs)
	return dedupeStrings(refs)
}

func composeResourceDependsOnRelations(recordsByFile map[string][]SymbolRecord, readContent contentReader) 
[]RelationRecord {
	var relations []RelationRecord
	for _, path := range sortedKeysOf(recordsByFile) {
		if !yamlDockerComposePath(path) {
			continue
		}
		content, ok := readContent(path)
		if !ok {
			continue
		}
		services := map[string]SymbolRecord{}
		for _, symbol := range recordsByFile[path] {
			if !composeServiceSymbol(symbol) {
				continue
			}
			services[composeServiceName(symbol)] = symbol
		}
		if len(services) == 0 {
			continue
		}
		lines := strings.Split(content, "
")
		for _, symbol := range recordsByFile[path] {
			if !composeServiceSymbol(symbol) {
				continue
			}
			body := symbolBlockFromLines(lines, symbol)
			for _, dep := range composeServiceDependencyRefs(body) {
				target, ok := services[dep.Name]
				if !ok || target.ID == symbol.ID {
					continue
				}
				relations = append(relations, RelationRecord{
					RecordType:    "relation",
					FromID:        symbol.ID,
					ToID:          target.ID,
					Type:          "RESOURCE_DEPENDS_ON",
					Confidence:    dep.Confidence,
					Reason:        dep.Reason,
					RelationScope: "file",
					Resolution:    "exact",
					TargetKind:    "symbol",
					Evidence: []Evidence{{
						Kind:      dep.EvidenceKind,
						FilePath:  symbol.FilePath,
						StartLine: symbol.StartLine,
						EndLine:   symbol.EndLine,
						Detail:    composeServiceName(symbol) + " -> " + dep.Name,
					}},
					WarningCodes: []string{},
				})
			}
		}
	}
	return relations
}

