var pythonTornadoRouteRegistrationsRouteTupleRe = 
regexp.MustCompile(`\(\s*((?:[rRuUbB]*)?["'][^"']+["'])\s*,\s*([A-Za-z_][A-Za-z0-9_]*) `)

func pythonTornadoRouteRegistrations(content string) []pythonTornadoRouteRegistration {
