func pythonDirectRouteRegistrations(content string) []goHTTPRouteRegistration {
	constants := staticStringConstants(content)
	handlerExpr := `[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)?`
	handlerOrAsViewExpr := `(?:` + handlerExpr + `\.as_view\s*\([^)
]*\)|` + handlerExpr + `)`
	addAPIRe := regexp.MustCompile(` [A-Za-z_][A-Za-z0-9_]*\.add_api_route\s*\(\s*([^,
]+)\s*,\s*(` + handlerExpr + `)`)
	addURLRuleKeywordRe := 
regexp.MustCompile(` [A-Za-z_][A-Za-z0-9_]*\.add_url_rule\s*\(\s*([^,
]+)[^
)]* view_func\s*=\s*(` + 
handlerOrAsViewExpr + `)`)
	addURLRulePositionalRe := 
regexp.MustCompile(` [A-Za-z_][A-Za-z0-9_]*\.add_url_rule\s*\(\s*([^,
]+)\s*,\s*[^,
)]+\s*,\s*(` + 
handlerOrAsViewExpr + `)`)
	var registrations []goHTTPRouteRegistration
	add := func(routeExpr, handler, evidence string) {
		route, ok := staticRouteExpressionValue(routeExpr, constants)
		if !ok {
			return
		}
		handler = strings.TrimSpace(handler)
		if handler == "" {
			return
		}
		allowTypeHandler := false
		if className, ok := pythonAsViewClassName(handler); ok {
			handler = className
			allowTypeHandler = true
		}
		registrations = append(registrations, goHTTPRouteRegistration{
			Route:            route,
			Handler:          handler,
			EvidenceKind:     evidence,
			Detail:           route + " -> " + handler,
			AllowTypeHandler: allowTypeHandler,
		})
	}
	for _, match := range addAPIRe.FindAllStringSubmatch(content, -1) {
		if len(match) != 3 {
			continue
		}
		add(match[1], match[2], "python_add_api_route")
	}
	for _, match := range addURLRuleKeywordRe.FindAllStringSubmatch(content, -1) {
		if len(match) != 3 {
			continue
		}
		add(match[1], match[2], "python_flask_add_url_rule")
	}
	for _, match := range addURLRulePositionalRe.FindAllStringSubmatch(content, -1) {
		if len(match) != 3 {
			continue
		}
		add(match[1], match[2], "python_flask_add_url_rule")
	}
	return registrations
}

var pythonAsViewClassNameRe = 
regexp.MustCompile(`^\s*([A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)?)\.as_view\s*\(`)

func pythonAsViewClassName(handler string) (string, bool) {
	match := pythonAsViewClassNameRe.FindStringSubmatch(handler)
	if len(match) != 2 {
		return "", false
	}
	return strings.TrimSpace(match[1]), true
}

func pythonRouterTargetFiles(importingPath, target string, importsByName map[string][]pythonImportBinding, knownFiles 
map[string]bool) []pythonRouterTarget {
	seen := map[string]bool{importingPath: true}
	files := []pythonRouterTarget{{File: importingPath, Receiver: target}}
	for _, binding := range importsByName[target] {
		resolved, ok := resolveLocalImport(importingPath, binding.Module, knownFiles)
		if !ok || seen[resolved] {
			continue
		}
		seen[resolved] = true
		receiver := strings.TrimSpace(binding.Imported)
		if receiver == "" {
			receiver = target
		}
		files = append(files, pythonRouterTarget{File: resolved, Receiver: receiver})
	}
	return files
}

func importedPythonBindings(content string) map[string][]pythonImportBinding {
	imports := map[string][]pythonImportBinding{}
	add := func(local, module, imported string) {
		local = strings.TrimSpace(local)
		module = strings.TrimSpace(module)
		if local == "" || module == "" {
			return
		}
		imports[local] = append(imports[local], pythonImportBinding{
			Module:   module,
			Imported: strings.TrimSpace(imported),
		})
	}
	fromByLine := map[int]pythonFromImportStatement{}
	for _, statement := range pythonFromImportStatements(content) {
		fromByLine[statement.line] = statement
	}
	for lineNumber, text := range strings.Split(content, "
") {
		if statement, ok := fromByLine[lineNumber]; ok {
			for _, item := range statement.items {
				name, alias := parsePythonImportItem(item)
				if name == "" || name == "*" {
					continue
				}
				local := alias
				if local == "" {
					local = name
				}
				add(local, statement.module, name)
			}
			continue
		}
		line := strings.TrimSpace(text)
		if strings.HasPrefix(line, "#") {
			continue
		}
		if matches := importedPythonNamesAndFormsImportRe.FindStringSubmatch(pythonDirectImportStatement(line)); 
len(matches) == 2 {
			for _, item := range strings.Split(matches[1], ",") {
				module, alias := parsePythonImportItem(item)
				if module == "" {
					continue
				}
				local := alias
				if local == "" {
					local = strings.Split(module, ".")[0]
				}
				add(local, module, "")
			}
			continue
		}
	}
	return imports
}

var (
	pythonRouterMountsIncludeRouterRe = regexp.MustCompile(`\.include_router\s*\(\s*([A-Za-z_][A-Za-z0-9_]*)`)
	pythonRouterMountsBlueprintRe     = regexp.MustCompile(`\.register_blueprint\s*\(\s*([A-Za-z_][A-Za-z0-9_]*)`)
	pythonRouterMountsPrefixRe        = regexp.MustCompile(` prefix\s*=\s*["']([^"']+)["']`)
	pythonRouterMountsUrlPrefixRe     = regexp.MustCompile(` url_prefix\s*=\s*["']([^"']+)["']`)
)

func pythonRouterMounts(content string) []pythonRouterMount {
	var mounts []pythonRouterMount
	for _, line := range strings.Split(content, "
") {
		targetMatch := pythonRouterMountsIncludeRouterRe.FindStringSubmatch(line)
		if len(targetMatch) == 2 {
			prefixMatch := pythonRouterMountsPrefixRe.FindStringSubmatch(line)
			if len(prefixMatch) == 2 && strings.HasPrefix(prefixMatch[1], "/") {
				mounts = append(mounts, pythonRouterMount{Prefix: prefixMatch[1], Target: targetMatch[1]})
			}
		}
		targetMatch = pythonRouterMountsBlueprintRe.FindStringSubmatch(line)
		if len(targetMatch) == 2 {
			prefix := "/"
			if prefixMatch := pythonRouterMountsUrlPrefixRe.FindStringSubmatch(line); len(prefixMatch) == 2 && 
strings.HasPrefix(prefixMatch[1], "/") {
				prefix = prefixMatch[1]
			}
			mounts = append(mounts, pythonRouterMount{Prefix: prefix, Target: targetMatch[1]})
		}
	}
	return mounts
}

func pythonRouterRoutes(content string, symbols []SymbolRecord) []pythonRouterRoute {
	var routes []pythonRouterRoute
	for _, symbol := range symbols {
