et|Post|Put|Patch|Delete|Head|Options)\s*\(\s*([^,
]+)\s*,\s*([A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)?) `)
	csharpMinimalAPIRouteRegistrationsChainedGroupRouteRe = regexp.MustCompile(` [A-Za-z_][A-Za-z0-9_]*\s*\.\s*MapGroup\s
*\(\s*([^,
)]+)\s*\)\s*\.\s*Map(?i:Get|Post|Put|Patch|Delete|Head|Options)\s*\(\s*([^,
]+)\s*,\s*([A-Za-z_][A-Za-z0-9
_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)?) `)
