func remixRouteBoundary(path string) string {
	slashPath := filepath.ToSlash(path)
	const rootMarker = "app/routes/"
	const nestedMarker = "/app/routes/"
	var relative string
	switch {
	case strings.HasPrefix(slashPath, rootMarker):
