				if name == "*" {
					segments = append(segments, "{...splat}")
				} else {
					segments = append(segments, "{"+name+"}")
				}
				continue
			}
			segments = append(segments, segment)
		}
	}
	if len(segments) == 0 {
		return "/"
	}
	return "/" + strings.Join(segments, "/")
