"""Transparent deterministic decision-support score; not a prediction."""

from __future__ import annotations

from dataclasses import asdict, dataclass
from typing import Iterable

from impactpilot.change.diff import ChangedSymbol
from impactpilot.change.impact import ImpactFinding
from impactpilot.graph.evidence import EvidenceQuality


@dataclass(frozen=True)
class RiskFactor:
    signal: str
    value: int | str
    contribution: int
    reason: str
    source: str


@dataclass(frozen=True)
class RiskResult:
    score: int
    level: str
    structural_component: int
    historical_component: int
    verification_component: int
    historical_status: str
    factors: tuple[RiskFactor, ...]
    warnings: tuple[str, ...]

    def to_dict(self) -> dict:
        return {**asdict(self), "factors": [asdict(item) for item in self.factors]}


def score_review(changes: Iterable[ChangedSymbol], findings: Iterable[ImpactFinding]) -> RiskResult:
    changes, findings = tuple(changes), tuple(findings)
    factors: list[RiskFactor] = []
    structural = 0
    for change in changes:
        if change.signature_changed:
            structural += 18; factors.append(_factor("signature change", change.symbol, 18, "Signature contracts can affect callers.", "semantic diff"))
        elif change.body_changed:
            structural += 8; factors.append(_factor("body change", change.symbol, 8, "Implementation behavior changed.", "semantic diff"))
        elif change.deleted:
            structural += 15; factors.append(_factor("removed symbol", change.symbol, 15, "Removed symbols may leave callers unresolved.", "semantic diff"))
        elif change.renamed:
            structural += 12; factors.append(_factor("renamed symbol", change.symbol, 12, "Renames may require call-site updates.", "semantic diff"))
        if change.dependents_count:
            contribution = min(8, change.dependents_count)
            structural += contribution; factors.append(_factor("semantic dependents", change.dependents_count, contribution, "Provider-reported dependent count.", "semantic diff"))
    direct = sum(1 for item in findings if item.direct)
    transitive = sum(1 for item in findings if item.transitive)
    if direct:
        contribution = min(16, direct * 4); structural += contribution; factors.append(_factor("direct impact", direct, contribution, "Direct graph neighbors deserve first review.", "impact"))
    if transitive:
        contribution = min(8, transitive * 2); structural += contribution; factors.append(_factor("transitive impact", transitive, contribution, "Transitive callers may depend on changed behavior.", "impact"))
    structural = min(60, structural)
    uncertain = [item for item in findings if item.trust.quality != EvidenceQuality.CONFIRMED]
    verification = min(10, len(uncertain) * 5)
    if uncertain:
        factors.append(_factor("verification required", len(uncertain), verification, "Uncertain graph evidence must not be treated as absence of impact.", "trust layer"))
    score = min(100, structural + verification)  # Historical (30%) is explicitly unavailable in Phase 4.
    level = "LOW" if score < 30 else "MEDIUM" if score < 60 else "HIGH" if score < 80 else "CRITICAL"
    warnings = ("Historical evidence is unavailable in Phase 4; its 30-point component is not scored.",) if changes else ()
    return RiskResult(score, level, structural, 0, verification, "unavailable", tuple(factors), warnings)


def _factor(signal: str, value: int | str, contribution: int, reason: str, source: str) -> RiskFactor:
    return RiskFactor(signal, value, contribution, reason, source)

"""Normalize Entire Graph's documented `diff --json` response."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Mapping


@dataclass(frozen=True)
class ChangedSymbol:
    symbol: str
    kind: str | None
    file: str
    line: int | None
    change_type: str
    dependents_count: int
    old_signature: str | None
    new_signature: str | None
    raw: Mapping[str, Any]

    @property
    def signature_changed(self) -> bool:
        return self.change_type == "signature_changed"

    @property
    def body_changed(self) -> bool:
        return self.change_type == "body_changed"

    @property
    def deleted(self) -> bool:
        return self.change_type == "removed"

    @property
    def renamed(self) -> bool:
        return self.change_type == "renamed"


def normalize_diff(payload: Mapping[str, Any]) -> tuple[ChangedSymbol, ...]:
    """Preserve provider records; skip only malformed records with no name."""
    changes: list[ChangedSymbol] = []
    files = payload.get("files")
    if not isinstance(files, list):
        return ()
    for file_record in files:
        if not isinstance(file_record, Mapping):
            continue
        path = file_record.get("path")
        if not isinstance(path, str):
            continue
        for item in file_record.get("changes", ()):
            if not isinstance(item, Mapping):
                continue
            name = item.get("name") or item.get("old_name") or item.get("new_name")
            change_type = item.get("type")
            if not isinstance(name, str) or not isinstance(change_type, str):
                continue
            count = item.get("dependents_count")
            changes.append(
                ChangedSymbol(
                    symbol=name,
                    kind=item.get("kind") if isinstance(item.get("kind"), str) else None,
                    file=path,
                    line=_line(item),
                    change_type=change_type,
                    dependents_count=count if isinstance(count, int) and count >= 0 else 0,
                    old_signature=item.get("old_signature") if isinstance(item.get("old_signature"), str) else None,
                    new_signature=item.get("new_signature") if isinstance(item.get("new_signature"), str) else None,
                    raw=item,
                )
            )
    return tuple(changes)


def _line(item: Mapping[str, Any]) -> int | None:
    for field in ("after_start_line", "before_start_line"):
        value = item.get(field)
        if isinstance(value, int):
            return value
    return None

"""Bounded commit-to-commit ImpactPilot review workflow."""

from __future__ import annotations

from dataclasses import asdict, dataclass
from pathlib import Path
from typing import Any, Mapping

from impactpilot.graph.client import GraphClient, GraphClientError
from impactpilot.recommendations.engine import Recommendation, VerificationPlan, recommend
from impactpilot.risk.engine import RiskResult, score_review

from .diff import ChangedSymbol, normalize_diff
from .impact import ImpactFinding, analyze_impact


@dataclass(frozen=True)
class ChangeReview:
    baseline: str
    target: str
    status: str
    changes: tuple[ChangedSymbol, ...]
    impact: tuple[ImpactFinding, ...]
    risk: RiskResult | None
    recommendations: tuple[Recommendation, ...]
    verification: VerificationPlan | None
    warnings: tuple[str, ...]

    def to_dict(self) -> dict[str, Any]:
        return {
            "review": {"baseline": self.baseline, "target": self.target, "status": self.status},
            "changes": [asdict(item) for item in self.changes],
            "impact": [_finding_dict(item) for item in self.impact],
            "risk": self.risk.to_dict() if self.risk else None,
            "recommendations": [asdict(item) for item in self.recommendations],
            "verification": self.verification.to_dict() if self.verification else None,
            "warnings": list(self.warnings),
        }


class ReviewService:
    """Uses one commit/ref semantic diff; it never claims worktree-vs-HEAD diff support."""

    def __init__(self, client: GraphClient, *, max_symbols: int = 20) -> None:
        self.client, self.max_symbols = client, max_symbols

    def review(self, repository: Path, *, base: str, head: str) -> ChangeReview:
        try:
            diff = self.client.run_json("diff", repository, "--base", base, "--head", head, "--json")
        except GraphClientError as exc:
            return ChangeReview(base, head, "failed", (), (), None, (), None, (str(exc),))
        changes = normalize_diff(diff)
        warnings = tuple(_warning(item) for item in diff.get("warnings", ()) if isinstance(item, Mapping))
        if not changes:
            return ChangeReview(base, head, "no_semantic_changes", (), (), score_review((), ()), (), recommend(())[1], warnings)
        selected = changes[: self.max_symbols]
        if len(changes) > len(selected):
            warnings += (f"Review limited to {self.max_symbols} changed symbols; remaining symbols require verification.",)
        findings: list[ImpactFinding] = []
        for change in selected:
            if change.deleted:
                warnings += (f"Removed symbol {change.symbol} cannot be queried with impact; inspect prior callers manually.",)
                continue
            try:
                impact = self.client.run_json("impact", repository, "--symbol", change.symbol, "--file", change.file, "--format", "json")
                neighbors = self.client.run_json("neighbors", repository, "--symbol", change.symbol, "--file", change.file, "--format", "json")
                findings.extend(analyze_impact(change, impact, neighbors))
            except GraphClientError as exc:
                warnings += (f"Impact unavailable for {change.symbol}: {exc}",)
        risk = score_review(selected, findings)
        recommendations, verification = recommend(findings)
        return ChangeReview(base, head, "complete", selected, tuple(findings), risk, recommendations, verification, warnings + risk.warnings)


def _warning(item: Mapping[str, Any]) -> str:
    return str(item.get("code") or item.get("message") or dict(item))


def _finding_dict(finding: ImpactFinding) -> dict[str, Any]:
    return {
        "changed_symbol": finding.changed_symbol,
        "impacted_symbol": finding.impacted_symbol,
        "relationship": finding.relationship,
        "category": finding.category,
        "direct": finding.direct,
        "transitive": finding.transitive,
        "trust": asdict(finding.trust) | {"quality": finding.trust.quality.value},
        "evidence": finding.evidence.audit_record(),
    }

